// reading-paths.js - curated reading paths (generated from scratchpad design2\paths.json by make-paths.ps1).

var READING_PATHS = [
  {slug:"silk-road",title:"The Silk Road",tagline:"Follow silk, ideas and armies along the routes that bound Eurasia together.",types:["navigator","builder"],eras:["medieval","ancient"],intro:"For over fifteen centuries, overland routes across Central Asia carried silk westward and horses, glass and gold eastward, along with religions and technologies. No single empire owned the Silk Road; instead, a relay of states opened, taxed, protected and sometimes disrupted it. This path follows that relay from the Han missions of the second century BCE, through the Parthian middlemen and the cosmopolitan markets of Tang Chang'an, to the Mongol peace and the Timurid splendour of Samarkand.",steps:[
    {name:"Han Dynasty",href:"/empire/han-dynasty",img:"/images/encyclopedia/liu-bang.jpg",meta:"Profile · 206 BCE – 220 CE",why:"Zhang Qian's missions and Emperor Wu's western campaigns opened the routes, and Han garrisons in the Tarim Basin kept them running."},
    {name:"Silk Road",href:"/encyclopedia/silk-road",img:"",meta:"Encyclopedia · Term",why:"An overview of the network itself: its routes, its goods and the ideas, Buddhism among them, that travelled along it."},
    {name:"Parthian Empire",href:"/empire/parthian-empire",img:"/images/encyclopedia/arsaces-i.jpg",meta:"Profile · 247 BCE – 224 CE",why:"Astride key segments of the route, Parthia profited as the intermediary between Rome and Han China, which knew it as Anxi."},
    {name:"Sogdians",href:"/encyclopedia/sogdians",img:"/images/encyclopedia/sogdians.jpg",meta:"Encyclopedia · People",why:"The Central Asian merchant people whose caravans and partnerships carried much of the trade between steppe, oasis and city."},
    {name:"Tang Dynasty",href:"/empire/tang-dynasty",img:"/images/encyclopedia/emperor-gaozu-of-tang.jpg",meta:"Profile · 618 CE – 907 CE",why:"Tang Chang'an, with perhaps a million people, hosted Sogdian, Persian, Arab and Indian merchants in its two great markets."},
    {name:"Battle of Talas",href:"/encyclopedia/battle-of-talas",img:"/images/encyclopedia/battle-of-talas.jpg",meta:"Encyclopedia · Event · 751",why:"In 751 Abbasid forces checked Tang expansion in Central Asia, an encounter traditionally linked with the westward spread of papermaking."},
    {name:"Mongol Empire",href:"/empire/mongol-empire",img:"/images/encyclopedia/genghis-khan.jpg",meta:"Profile · 1206 CE – 1368 CE",why:"Mongol conquest joined China to Europe, with merchants protected by the Pax Mongolica and envoys speeded by the yam relay system."},
    {name:"Pax Mongolica",href:"/encyclopedia/pax-mongolica",img:"/images/encyclopedia/pax-mongolica.jpg",meta:"Encyclopedia · Idea",why:"The idea behind the relatively safe passage of goods, envoys and travellers across Mongol-ruled Eurasia."},
    {name:"Timurid Empire",href:"/empire/timurid-empire",img:"/images/encyclopedia/samarkand.jpg",meta:"Profile · 1363 CE – 1507 CE",why:"Caravan trade between China, India and the Mediterranean enriched Samarkand, Bukhara and Herat, a late flowering of the overland routes."}
  ]},
  {slug:"steppe-empires",title:"Empires of the Steppe",tagline:"How mounted nomads built some of the largest states in history, from the Xiongnu to Timur.",types:["strategist","timekeeper"],eras:["medieval","ancient"],intro:"The grasslands stretching from Mongolia to the Black Sea produced a distinctive kind of empire: mobile, built on horses and herds, held together by charismatic leaders and tribute rather than bureaucracy. Steppe powers repeatedly humbled settled neighbours, extracted silk and grain from them and controlled the trade passing between them. This path traces that tradition from the Xiongnu confederation that confronted Han China, through the Turkic khaganates, to Genghis Khan's world empire and its heirs.",steps:[
    {name:"Xiongnu Empire",href:"/empire/xiongnu-empire",img:"/images/encyclopedia/orkhon-river.jpg",meta:"Profile · 318 BCE – 36 BCE",why:"The first great steppe empire of eastern Eurasia, united by Modu Chanyu around 209 BCE, forced Han China into decades of appeasement."},
    {name:"Heqin",href:"/encyclopedia/heqin",img:"",meta:"Encyclopedia · Institution",why:"The 'peace through kinship' arrangement of annual gifts and Han brides that bought peace from the Xiongnu after the Battle of Baideng."},
    {name:"Gokturk Empire",href:"/empire/gokturk-empire",img:"/images/encyclopedia/kul-tigin.jpg",meta:"Profile · 546 CE – 744 CE",why:"Founded by Bumin in 552, the first state to bear the name Türk managed Silk Road commerce and left the Orkhon Inscriptions."},
    {name:"Khazar Khaganate",href:"/empire/khazar-khaganate",img:"/images/encyclopedia/sarkel.jpg",meta:"Profile · 650 CE – 969 CE",why:"A western steppe power poised between Byzantium and the caliphate, notable for its religious pluralism and its rulers' conversion to Judaism."},
    {name:"Genghis Khan",href:"/encyclopedia/genghis-khan",img:"/images/encyclopedia/genghis-khan.jpg",meta:"Encyclopedia · Person · c. 1162–1227",why:"Temüjin unified the rival Mongol and Turkic tribes and was proclaimed Genghis Khan at a kurultai in 1206."},
    {name:"Mongol Empire",href:"/empire/mongol-empire",img:"/images/encyclopedia/genghis-khan.jpg",meta:"Profile · 1206 CE – 1368 CE",why:"Decimal units, promotion by merit and the yam relay system carried Mongol armies from China to Legnica and Mohi by 1241."},
    {name:"Yasa",href:"/encyclopedia/yasa",img:"",meta:"Encyclopedia · Institution",why:"The body of Mongol customary law that Genghis Khan's heirs, Chagatai above all, enforced across the conquered lands."},
    {name:"Chagatai Empire",href:"/empire/chagatai-empire",img:"/images/encyclopedia/kaidu.jpg",meta:"Profile · 1225 CE – 1500 CE",why:"The Central Asian appanage of Genghis Khan's second son shows the lasting tension between nomadic tradition and the sedentary Silk Road cities."},
    {name:"Timur",href:"/encyclopedia/timur",img:"/images/encyclopedia/timur.jpg",meta:"Encyclopedia · Person · 1336–1405",why:"Rising within the Chagatai Khanate, Timur used the Mongol framework of legitimacy to build an empire from Anatolia to the borders of China."}
  ]},
  {slug:"religion-and-power",title:"Religion and Power",tagline:"How rulers adopted, promoted and imposed faiths, and how faith in turn shaped their states.",types:["thinker"],eras:["ancient","medieval","earlymodern"],intro:"Empires have rarely been neutral about belief. Some rulers embraced a new faith and spread it across their realms; others used religion to claim legitimacy, to unite diverse subjects or to set themselves apart from rivals. This path moves from Ashoka's dhamma, Constantine's patronage of the Church and Ezana's conversion, through the first caliphs and the crowning of Charlemagne, to the crusades, Safavid Shi'ism and Akbar's policy of peace with all, showing faith as both foundation and fault line.",steps:[
    {name:"Maurya Empire",href:"/empire/maurya-empire",img:"/images/encyclopedia/chandragupta-maurya.jpg",meta:"Profile · 322 BCE – 185 BCE",why:"After the bloody Kalinga War, Ashoka renounced conquest by force, and royal patronage helped spread Buddhism across the subcontinent and beyond."},
    {name:"Edicts of Ashoka",href:"/encyclopedia/edicts-of-ashoka",img:"/images/encyclopedia/edicts-of-ashoka.jpg",meta:"Encyclopedia · Work",why:"Inscribed on rocks and pillars, the edicts proclaimed dhamma and welfare measures, even naming Hellenistic kings as recipients of Ashoka's missions."},
    {name:"Edict of Milan",href:"/encyclopedia/edict-of-milan",img:"/images/encyclopedia/edict-of-milan.jpg",meta:"Encyclopedia · Event · 313 CE",why:"The agreement of 313 between Constantine and Licinius that set a persecuted sect on the road to becoming Rome's dominant institution."},
    {name:"Aksumite Empire",href:"/empire/aksumite-empire",img:"/images/encyclopedia/ezana.jpg",meta:"Profile · 100 CE – 940 CE",why:"King Ezana's adoption of Christianity in the fourth century made the church a major pillar of Aksumite government."},
    {name:"Rashidun Caliphate",href:"/empire/rashidun-caliphate",img:"/images/encyclopedia/medina.jpg",meta:"Profile · 632 CE – 661 CE",why:"The first caliphs, successors to the Prophet Muhammad, turned a religious community into an empire reaching Syria, Egypt and Iraq."},
    {name:"Coronation of Charlemagne",href:"/encyclopedia/coronation-of-charlemagne",img:"/images/encyclopedia/coronation-of-charlemagne.jpg",meta:"Encyclopedia · Event · 800 CE",why:"On Christmas Day 800 Pope Leo III crowned Charlemagne in Rome, sealing the alliance between the papacy and the Frankish monarchy."},
    {name:"Crusades",href:"/encyclopedia/crusades",img:"/images/encyclopedia/crusades.jpg",meta:"Encyclopedia · Event",why:"Centuries of holy war in the name of faith, including the irony of 1204, when crusaders sacked Christian Constantinople."},
    {name:"Safavid Empire",href:"/empire/safavid-empire",img:"/images/encyclopedia/naqsh-e-jahan-square.jpg",meta:"Profile · 1501 CE – 1736 CE",why:"Ismail I proclaimed Twelver Shia Islam the state religion in 1501, forging an Iranian identity distinct from his Sunni Ottoman and Uzbek neighbours."},
    {name:"Mughal Empire",href:"/empire/mughal-empire",img:"/images/encyclopedia/taj-mahal.jpg",meta:"Profile · 1526 CE – 1857 CE",why:"Akbar's Sulh-i-kul, or 'peace with all', and his abolition of the jizya in 1564 contrast with Aurangzeb's return to orthodoxy."}
  ]},
  {slug:"empires-of-africa",title:"Empires of Africa",tagline:"Gold, faith and trade in the great states of Nubia, Ethiopia and West Africa.",types:["timekeeper","navigator"],eras:["medieval","ancient","earlymodern"],intro:"Africa's empires were built on control of gold, trade routes and the loyalty of diverse peoples. Kush ruled Egypt as its Twenty-Fifth Dynasty; Aksum struck its own gold coins and traded with Rome and India; and in West Africa a succession of states, Ghana, Mali and Songhai, grew rich on the trans-Saharan exchange of gold and salt. This path follows that story from the Nile to the forest kingdom of Asante, whose Golden Stool embodied the soul of the nation.",steps:[
    {name:"Kushite Empire",href:"/empire/kushite-empire",img:"/images/encyclopedia/meroe.jpg",meta:"Profile · 1070 BCE – 350 CE",why:"From Napata, Piye and his successors united Nubia and Egypt as the Twenty-Fifth Dynasty, before Meroë became a great centre of iron."},
    {name:"Aksumite Empire",href:"/empire/aksumite-empire",img:"/images/encyclopedia/ezana.jpg",meta:"Profile · 100 CE – 940 CE",why:"Controlling the Red Sea port of Adulis, Aksum issued its own gold coins and conquered Kush around 350 CE."},
    {name:"Ghana Empire",href:"/empire/ghana-empire",img:"/images/encyclopedia/walata.jpg",meta:"Profile · 300 CE – 1240 CE",why:"The Soninke 'land of gold' taxed both salt moving south and gold moving north, reserving every gold nugget for the king."},
    {name:"Sundiata Keita",href:"/encyclopedia/sundiata-keita",img:"",meta:"Encyclopedia · Person · d. c. 1255",why:"The founder of Mali, whose victory at Kirina united the Manding chiefdoms and whose epic is still preserved by griots."},
    {name:"Mali Empire",href:"/empire/mali-empire",img:"/images/encyclopedia/djenne.jpg",meta:"Profile · 1235 CE – 1600 CE",why:"Mali controlled the goldfields of Bambuk and Bure and made Timbuktu and Djenné centres of trade and Islamic learning."},
    {name:"Mansa Musa's pilgrimage",href:"/encyclopedia/mansa-musas-pilgrimage",img:"",meta:"Encyclopedia · Event · 1324",why:"Mansa Musa's lavish spending of gold in Cairo in 1324 put Mali on the map, quite literally in the Catalan Atlas."},
    {name:"Songhai Empire",href:"/empire/songhai-empire",img:"/images/encyclopedia/gao.jpg",meta:"Profile · 1430 CE – 1600 CE",why:"The largest empire in West African history, built by Sunni Ali and Askia Muhammad on the cities of Gao, Timbuktu and Djenné."},
    {name:"Battle of Tondibi",href:"/encyclopedia/battle-of-tondibi",img:"",meta:"Encyclopedia · Event · 1591",why:"In 1591 a small Moroccan force armed with arquebuses routed a much larger Songhai army in a single engagement."},
    {name:"Ashanti Empire",href:"/empire/ashanti-empire",img:"/images/encyclopedia/golden-stool.jpg",meta:"Profile · 1670 CE – 1902 CE",why:"Osei Tutu I and the priest Okomfo Anokye united the Akan chiefdoms around the Golden Stool and defeated Denkyira at Feyiase in 1701."}
  ]},
  {slug:"age-of-sail",title:"The Age of Sail",tagline:"How small Atlantic kingdoms and a merchant republic built empires across the oceans.",types:["navigator","strategist"],eras:["earlymodern"],intro:"From the fifteenth century, European ships opened sea routes that linked the continents as never before. Portugal led the way down the African coast and into the Indian Ocean; Spain crossed the Atlantic and seized the wealth of the Americas; the Dutch built a company with the powers of a state; and Britain eventually assembled the largest empire in history. This path follows that expansion, and the enslavement and violence on which much of it rested.",steps:[
    {name:"Portuguese Empire",href:"/empire/portuguese-empire",img:"/images/encyclopedia/john-i-of-portugal.jpg",meta:"Profile · 1415 CE – 1975 CE",why:"From the capture of Ceuta in 1415 to Goa, Malacca and Hormuz, Portugal built an empire of fortified trading posts rather than territory."},
    {name:"Prince Henry the Navigator",href:"/encyclopedia/prince-henry-the-navigator",img:"/images/encyclopedia/prince-henry-the-navigator.jpg",meta:"Encyclopedia · Person · 1394–1460",why:"Henry's sponsorship of voyages down the West African coast turned exploration from episodic raiding into an institutionalised commercial enterprise."},
    {name:"Vasco da Gama",href:"/encyclopedia/vasco-da-gama",img:"/images/encyclopedia/vasco-da-gama.jpg",meta:"Encyclopedia · Person · c. 1469–1524",why:"Da Gama's arrival at Calicut in 1498 completed the sea route to Asia that Bartolomeu Dias had opened by rounding the Cape."},
    {name:"Treaty of Tordesillas",href:"/encyclopedia/treaty-of-tordesillas",img:"/images/encyclopedia/treaty-of-tordesillas.jpg",meta:"Encyclopedia · Event · 1494",why:"The treaty of 1494 fixed a meridian dividing newly discovered lands between the Spanish and Portuguese spheres."},
    {name:"Spanish Empire",href:"/empire/spanish-empire",img:"/images/encyclopedia/el-escorial.jpg",meta:"Profile · 1492 CE – 1898 CE",why:"Columbus, Cortés and Pizarro made Spain master of the Americas, and under Philip II the first empire on which the sun never set."},
    {name:"Atlantic slave trade",href:"/encyclopedia/atlantic-slave-trade",img:"/images/encyclopedia/atlantic-slave-trade.jpg",meta:"Encyclopedia · Term",why:"Plantation economies such as Brazil's sugar estates rested on the forced transport of enslaved Africans across the Atlantic."},
    {name:"Dutch Empire",href:"/empire/dutch-empire",img:"/images/encyclopedia/hugo-grotius.jpg",meta:"Profile · 1581 CE – 1975 CE",why:"A small republic projected power across four continents by seizing maritime chokepoints such as Malacca, taken from Portugal in 1641."},
    {name:"Dutch East India Company",href:"/encyclopedia/dutch-east-india-company",img:"/images/encyclopedia/dutch-east-india-company.jpg",meta:"Encyclopedia · Institution",why:"Founded in 1602 with permanent capital, tradable shares and powers to wage war and make treaties, the VOC was something new."},
    {name:"British Empire",href:"/empire/british-empire",img:"/images/encyclopedia/slavery-abolition-act-1833.jpg",meta:"Profile · 1583 CE – 1997 CE",why:"Built on a fiscal-military state and a professional Royal Navy, it became the largest empire in history, ruling roughly a quarter of the world's population."}
  ]},
  {slug:"how-empires-fall",title:"How Empires Fall",tagline:"Invasion, division, bankruptcy and revolution: the many ways great powers come to an end.",types:["strategist","timekeeper"],eras:["medieval","ancient","earlymodern","modern"],intro:"No empire lasts for ever, but they end in strikingly different ways. Some erode slowly until a final blow merely confirms what has already happened; others are destroyed in a single catastrophe. This path compares the fall of the Western Roman Empire, the Mongol destruction of Abbasid Baghdad, the Ottoman conquest of Constantinople, the collapse of Qing China and the dissolution of the Ottoman Empire itself, asking what internal weakness and external pressure each contributed.",steps:[
    {name:"Roman Empire",href:"/empire/roman-empire",img:"/images/encyclopedia/julius-caesar.jpg",meta:"Profile · 27 BCE – 476 CE",why:"Adrianople, the Visigothic sack of 410 and the loss of North Africa stripped the Western Empire of armies, prestige and revenue."},
    {name:"Sack of Rome (410)",href:"/encyclopedia/sack-of-rome-410",img:"",meta:"Encyclopedia · Event · 410 CE",why:"Alaric's Visigoths shattered the myth of Roman invulnerability, though the Western Empire limped on for another sixty-six years."},
    {name:"Abbasid Caliphate",href:"/empire/abbasid-caliphate",img:"/images/encyclopedia/samarra.jpg",meta:"Profile · 750 CE – 1517 CE",why:"Once the commercial hub of the known world, the caliphate had long ceased to be a first-rank military power when the Mongols arrived."},
    {name:"Siege of Baghdad (1258)",href:"/encyclopedia/siege-of-baghdad-1258",img:"/images/encyclopedia/siege-of-baghdad-1258.jpg",meta:"Encyclopedia · Event · 1258",why:"The Mongol destruction of Baghdad in 1258 ended the caliphate there, although a shadow caliphate survived under the Mamluks in Cairo."},
    {name:"Byzantine Empire",href:"/empire/byzantine-empire",img:"/images/encyclopedia/second-arab-siege-of-constantinople.jpg",meta:"Profile · 330 CE – 1453 CE",why:"A civilisation that saw its own decline clearly: the loss of Anatolia and the crusader sack of 1204 did damage it never repaired."},
    {name:"Fall of Constantinople",href:"/encyclopedia/fall-of-constantinople",img:"/images/encyclopedia/fall-of-constantinople.jpg",meta:"Encyclopedia · Event · 1453",why:"On 29 May 1453 Mehmed II's cannon breached the Theodosian walls, extinguishing the Byzantine Empire after eleven centuries."},
    {name:"Qing Empire",href:"/empire/qing-empire",img:"/images/encyclopedia/kangxi-emperor.jpg",meta:"Profile · 1644 CE – 1912 CE",why:"Fiscal strain, rebellions such as the Taiping and defeat in the Opium Wars hollowed out China's last dynasty from within and without."},
    {name:"Xinhai Revolution",href:"/encyclopedia/xinhai-revolution",img:"/images/encyclopedia/xinhai-revolution.jpg",meta:"Encyclopedia · Event · 1911",why:"An uprising at Wuchang in 1911 spread from province to province and led to Puyi's abdication, ending two thousand years of imperial rule."},
    {name:"Ottoman Empire",href:"/empire/ottoman-empire",img:"/images/encyclopedia/suleymaniye-mosque.jpg",meta:"Profile · 1299 CE – 1922 CE",why:"The conqueror of Constantinople endured until defeat in the First World War and the abolition of the sultanate in 1922."}
  ]},
  {slug:"law-and-government",title:"Law and Government",tagline:"From Hammurabi's stele to the Napoleonic Code: how empires wrote down the rules.",types:["thinker","builder"],eras:["ancient","medieval","modern"],intro:"Conquest wins territory, but only law and administration hold it. Rulers across the world have codified laws, set out principles of statecraft and built institutions to bind diverse subjects to a single authority. This path follows some of the most influential examples: the laws of Hammurabi, the Arthashastra's manual of statecraft, Justinian's codification of Roman law, the Tang Code that shaped East Asia, Mali's founding charter and Napoleon's civil code, whose influence still reaches across continents.",steps:[
    {name:"Babylonian Empire",href:"/empire/babylonian-empire",img:"/images/encyclopedia/hammurabi.jpg",meta:"Profile · 1894 BCE – 1595 BCE",why:"Hammurabi turned a modest kingdom into the master of Mesopotamia through patient preparation, shrewd diplomacy and rapid conquest."},
    {name:"Code of Hammurabi",href:"/encyclopedia/code-of-hammurabi",img:"/images/encyclopedia/code-of-hammurabi.jpg",meta:"Encyclopedia · Work · c. 1754 BCE",why:"Inscribed on a basalt stele now in the Louvre, its 282 laws regulated wages, loans, contracts and the duties of merchants."},
    {name:"Arthashastra",href:"/encyclopedia/arthashastra",img:"",meta:"Encyclopedia · Work",why:"Attributed to Chanakya, this guide to administration, espionage, law and diplomacy is often used to illuminate Mauryan government."},
    {name:"Byzantine Empire",href:"/empire/byzantine-empire",img:"/images/encyclopedia/second-arab-siege-of-constantinople.jpg",meta:"Profile · 330 CE – 1453 CE",why:"Byzantium joined Roman codified law and professional administration to a Christian ideology of the emperor as God's chosen representative."},
    {name:"Corpus Juris Civilis",href:"/encyclopedia/corpus-juris-civilis",img:"/images/encyclopedia/corpus-juris-civilis.jpg",meta:"Encyclopedia · Work · 534 CE",why:"Justinian's codification of 529 to 534, rediscovered and taught at Bologna, became the foundation of civil law across much of the world."},
    {name:"Tang Code",href:"/encyclopedia/tang-code",img:"",meta:"Encyclopedia · Work · 653",why:"First issued in 624, the Tang Code influenced the legal systems of Japan, Korea and Vietnam, Japan's Taihō Code among them."},
    {name:"Kouroukan Fouga",href:"/encyclopedia/kouroukan-fouga",img:"/images/encyclopedia/kouroukan-fouga.jpg",meta:"Encyclopedia · Work",why:"The assembly and charter credited to Sundiata, regulating succession, clan obligations and social order in the Mali Empire."},
    {name:"French Empire",href:"/empire/french-empire",img:"/images/encyclopedia/charles-de-gaulle.jpg",meta:"Profile · 1534 CE – 1980 CE",why:"France carried its law overseas: in Algeria French civil law applied to European settlers, while most Algerians lived under the indigénat."},
    {name:"Napoleonic Code",href:"/encyclopedia/napoleonic-code",img:"/images/encyclopedia/napoleonic-code.jpg",meta:"Encyclopedia · Work",why:"Spread across Europe in Napoleon's wake and later by colonial rule, it shaped legal systems in Africa and the Americas."}
  ]},
  {slug:"science-and-learning",title:"Science and Learning",tagline:"Libraries, translators and observatories: where empires invested in knowledge.",types:["thinker"],eras:["medieval","ancient"],intro:"Imperial wealth has often paid for knowledge. Kings and caliphs founded libraries, endowed colleges, sponsored translations and built observatories, sometimes for prestige, sometimes for practical ends such as calendars and administration. This path visits the scholars of Ptolemaic Alexandria, the mathematicians of Gupta India, the translators of Abbasid Baghdad, the calendar reformers of the Seljuk court, the inventors of Song China and Ulugh Beg's astronomers in Samarkand, tracing how ideas passed from one centre of learning to the next.",steps:[
    {name:"Ptolemaic Empire",href:"/empire/ptolemaic-empire",img:"/images/encyclopedia/cleopatra-vii.jpg",meta:"Profile · 323 BCE – 30 BCE",why:"Ptolemaic Alexandria drew scholars such as Euclid, Eratosthenes and Herophilus to its Library and Mouseion."},
    {name:"Library of Alexandria",href:"/encyclopedia/library-of-alexandria",img:"/images/encyclopedia/library-of-alexandria.jpg",meta:"Encyclopedia · Institution",why:"The great royal library at the heart of Ptolemaic scholarship, whose reputation has shaped the ideal of a universal library ever since."},
    {name:"Gupta Empire",href:"/empire/gupta-empire",img:"/images/encyclopedia/abhijnanasakuntalam.jpg",meta:"Profile · 240 CE – 550 CE",why:"India's Golden Age produced Kalidasa's poetry and Aryabhata's astronomy, built on the place-value decimal system later transmitted to Europe."},
    {name:"Abbasid Caliphate",href:"/empire/abbasid-caliphate",img:"/images/encyclopedia/samarra.jpg",meta:"Profile · 750 CE – 1517 CE",why:"From Baghdad, founded in 762, the Abbasids presided over a cosmopolitan court where al-Khwarizmi wrote his treatise on al-jabr."},
    {name:"House of Wisdom",href:"/encyclopedia/house-of-wisdom",img:"/images/encyclopedia/house-of-wisdom.jpg",meta:"Encyclopedia · Institution",why:"The centre that translated Greek, Persian, Indian and Syriac texts into Arabic, preserving Aristotle, Euclid, Galen and Ptolemy."},
    {name:"Omar Khayyam",href:"/encyclopedia/omar-khayyam",img:"/images/encyclopedia/omar-khayyam.jpg",meta:"Encyclopedia · Person · 1048–1131",why:"Poet and mathematician who, under Seljuk patronage, produced the Jalali calendar of 1079, more accurate than the Julian calendar."},
    {name:"Song Dynasty",href:"/empire/song-dynasty",img:"/images/encyclopedia/emperor-taizu-of-song.jpg",meta:"Profile · 960 CE – 1279 CE",why:"Song China issued state paper money from 1024, first recorded the gunpowder formula in 1044 and chose officials by written examination."},
    {name:"Timurid Empire",href:"/empire/timurid-empire",img:"/images/encyclopedia/samarkand.jpg",meta:"Profile · 1363 CE – 1507 CE",why:"Rebuilt with the plunder of Timur's conquests, Samarkand became under Shah Rukh and Ulugh Beg a genuine centre of intellectual life."},
    {name:"Ulugh Beg Observatory",href:"/encyclopedia/ulugh-beg-observatory",img:"/images/encyclopedia/ulugh-beg-observatory.jpg",meta:"Encyclopedia · Institution",why:"Built in the 1420s, its tables listed more than a thousand stars and were later published at Oxford in 1665."}
  ]},
  {slug:"the-crusades",title:"The Crusades",tagline:"Two centuries of holy war for the eastern Mediterranean, and the states it built and broke.",types:["strategist","chronicler"],eras:["medieval"],intro:"In 1095 a pope's sermon set armed pilgrims marching east, and for two hundred years Latin Christendom fought for Jerusalem and the coast of the Levant. The crusades planted fragile kingdoms in the East, bled Byzantium, raised up Saladin and the sultans who answered the call to jihad, and bound Europe to the Mediterranean world it had half-forgotten. This path follows the whole arc, from Clermont to the fall of the crusader states.",steps:[
    {name:"Pope Urban II",href:"/encyclopedia/pope-urban-ii",img:"/images/encyclopedia/pope-urban-ii.jpg",meta:"Encyclopedia · Person · c. 1035–1099",why:"The pope whose sermon at Clermont in 1095 launched the First Crusade."},
    {name:"First Crusade",href:"/encyclopedia/first-crusade",img:"/images/encyclopedia/first-crusade.jpg",meta:"Encyclopedia · Event · captured Jerusalem 1099",why:"Against every expectation, the first expedition took Jerusalem in 1099 and made the crusading idea seem blessed."},
    {name:"Kingdom of Jerusalem",href:"/empire/kingdom-of-jerusalem",img:"/images/encyclopedia/church-of-the-holy-sepulchre.jpg",meta:"Profile · 1099 CE – 1291 CE",why:"The greatest of the crusader states: how a conquered coast was ruled, defended and finally lost."},
    {name:"Saladin",href:"/encyclopedia/saladin",img:"/images/encyclopedia/saladin.jpg",meta:"Encyclopedia · Person · d. 1193",why:"The Kurdish sultan who united Egypt and Syria and turned the tide of the holy war."},
    {name:"Battle of Hattin",href:"/encyclopedia/battle-of-hattin",img:"/images/encyclopedia/battle-of-hattin.jpg",meta:"Encyclopedia · Event · 1187",why:"One July day in 1187 destroyed the kingdom's army and gave Jerusalem back to Islam."},
    {name:"Krak des Chevaliers",href:"/encyclopedia/krak-des-chevaliers",img:"/images/encyclopedia/krak-des-chevaliers.jpg",meta:"Encyclopedia · Work",why:"The greatest of the crusader castles, and what fortress architecture reveals about holding hostile land."},
    {name:"Fourth Crusade",href:"/encyclopedia/fourth-crusade",img:"/images/encyclopedia/fourth-crusade.jpg",meta:"Encyclopedia · Event · 1204",why:"The crusade that never reached Jerusalem: it sacked Christian Constantinople instead, and Byzantium never fully recovered."},
    {name:"Crusader states",href:"/encyclopedia/crusader-states",img:"/images/encyclopedia/crusader-states.jpg",meta:"Encyclopedia · State",why:"The settlements as a whole - Edessa, Antioch, Tripoli, Jerusalem - and why they could not last."}
  ]},
  {slug:"the-fall-of-rome",title:"The Fall of Rome",tagline:"How the western half of the ancient world's greatest state came apart.",types:["timekeeper","strategist"],eras:["ancient"],intro:"Rome did not fall in a day, and half of it did not fall at all. This path traces the long unravelling of the western empire: the reforms that bought time, the frontier that broke at Adrianople, the sacks of the eternal city, and the quiet afternoon in 476 when a barbarian general sent the imperial regalia east. It ends with the Gothic kings who kept the lights on in Italy and the eastern empire that carried Rome onward for a thousand years.",steps:[
    {name:"Roman Empire",href:"/empire/roman-empire",img:"/images/encyclopedia/julius-caesar.jpg",meta:"Profile · 27 BCE – 476 CE",why:"Begin with the whole story: the power the fifth century inherited and squandered."},
    {name:"Diocletian",href:"/encyclopedia/diocletian",img:"/images/encyclopedia/diocletian.jpg",meta:"Encyclopedia · Person · r. 284–305 CE",why:"The reformer who split the empire to save it, a century before the end."},
    {name:"Battle of Adrianople",href:"/encyclopedia/battle-of-adrianople",img:"/images/encyclopedia/battle-of-adrianople.jpg",meta:"Encyclopedia · Event · 378 CE",why:"378 CE: the Goths destroyed an emperor and his army, and the frontier never truly closed again."},
    {name:"Alaric I",href:"/encyclopedia/alaric-i",img:"/images/encyclopedia/alaric-i.jpg",meta:"Encyclopedia · Person · d. 410 CE",why:"The Gothic king whose army took Rome in 410, the first sack in eight centuries."},
    {name:"Attila",href:"/encyclopedia/attila",img:"/images/encyclopedia/attila.jpg",meta:"Encyclopedia · Person · c. 406–453",why:"The Hun who bled both empires and showed how little stood behind the walls."},
    {name:"Odoacer",href:"/encyclopedia/odoacer",img:"/images/encyclopedia/odoacer.jpg",meta:"Encyclopedia · Person · c. 433–493 CE",why:"The soldier who deposed the last western emperor in 476 and ruled Italy as king."},
    {name:"Theodoric the Great",href:"/encyclopedia/theodoric-the-great",img:"/images/encyclopedia/theodoric-the-great.jpg",meta:"Encyclopedia · Person · 454–526",why:"The Ostrogoth who governed Italy in Roman style: the fall, seen from the inside, looked like continuity."},
    {name:"Byzantine Empire",href:"/empire/byzantine-empire",img:"/images/encyclopedia/second-arab-siege-of-constantinople.jpg",meta:"Profile · 330 CE – 1453 CE",why:"The half that did not fall: Rome's eastern empire endured to 1453."}
  ]},
  {slug:"the-americas-before-columbus",title:"The Americas before Columbus",tagline:"Great cities, empires and roads built long before 1492.",types:["navigator","builder"],eras:["medieval","earlymodern","ancient"],intro:"When Europeans arrived, the Americas already held some of the largest cities on earth, roads that outran anything in Europe, and empires that had risen and fallen for two thousand years. This path crosses that world: the metropolis of Teotihuacan, the island capital of the Aztecs, and the Inca realm that ran ten thousand kilometres of mountain road - and the two emperors who met the conquistadors.",steps:[
    {name:"Teotihuacan",href:"/empire/teotihuacan",img:"/images/encyclopedia/pyramid-of-the-sun.jpg",meta:"Profile · 100 BCE – 550 CE",why:"A city of a hundred thousand people, planned on a grid, that shaped Mesoamerica centuries before the Aztecs."},
    {name:"Aztec Empire",href:"/empire/aztec-empire",img:"/images/encyclopedia/templo-mayor.jpg",meta:"Profile · 1325 CE – 1521 CE",why:"The last and greatest power of Mesoamerica: tribute, war and a capital on a lake."},
    {name:"Tenochtitlan",href:"/encyclopedia/tenochtitlan",img:"/images/encyclopedia/tenochtitlan.jpg",meta:"Encyclopedia · Place",why:"The island metropolis that stunned the Spaniards, larger than most cities of Europe."},
    {name:"Moctezuma II",href:"/encyclopedia/moctezuma-ii",img:"/images/encyclopedia/moctezuma-ii.jpg",meta:"Encyclopedia · Person · c. 1466–1520",why:"The emperor who received Cortes, and whose fate still divides historians."},
    {name:"Inca Empire",href:"/empire/inca-empire",img:"/images/encyclopedia/machu-picchu.jpg",meta:"Profile · 1438 CE – 1533 CE",why:"The largest state of the pre-Columbian Americas, run by roads, storehouses and knotted cords instead of writing."},
    {name:"Machu Picchu",href:"/encyclopedia/machu-picchu",img:"/images/encyclopedia/machu-picchu.jpg",meta:"Encyclopedia · Place",why:"The royal estate in the clouds that conquest never found."},
    {name:"Atahualpa",href:"/encyclopedia/atahualpa",img:"/images/encyclopedia/atahualpa.jpg",meta:"Encyclopedia · Person · c. 1502–1533",why:"The Inca who won a civil war just in time to meet Pizarro at Cajamarca."}
  ]},
  {slug:"india-through-the-ages",title:"India through the Ages",tagline:"From Ashoka's edicts to the Marathas: the subcontinent's great powers in sequence.",types:["timekeeper","chronicler"],eras:["ancient","medieval","earlymodern"],intro:"Few lands have carried so many great states as the Indian subcontinent. This path moves through them in order: the Mauryan empire that first united the subcontinent and the emperor who renounced war; the classical age of the Guptas; the sultans of Delhi; the glittering south of Vijayanagara; the Mughal zenith and its monuments; and the Maratha confederacy that supplanted it.",steps:[
    {name:"Maurya Empire",href:"/empire/maurya-empire",img:"/images/encyclopedia/chandragupta-maurya.jpg",meta:"Profile · 322 BCE – 185 BCE",why:"The first empire to span the subcontinent, with a bureaucracy ahead of its time."},
    {name:"Ashoka",href:"/encyclopedia/ashoka",img:"/images/encyclopedia/ashoka.jpg",meta:"Encyclopedia · Person · d. 232 BCE",why:"The conqueror of Kalinga who turned to dhamma and carved his conscience onto rocks and pillars."},
    {name:"Gupta Empire",href:"/empire/gupta-empire",img:"/images/encyclopedia/abhijnanasakuntalam.jpg",meta:"Profile · 240 CE – 550 CE",why:"The classical age: mathematics, poetry and temple art under a light imperial hand."},
    {name:"Delhi Sultanate",href:"/empire/delhi-sultanate",img:"/images/encyclopedia/qutb-minar.jpg",meta:"Profile · 1206 CE – 1526 CE",why:"Three centuries of sultans who made Delhi one of the great capitals of the Islamic world."},
    {name:"Vijayanagara Empire",href:"/empire/vijayanagara-empire",img:"/images/encyclopedia/chandragiri.jpg",meta:"Profile · 1336 CE – 1646 CE",why:"The city of victory that ruled the south and awed every traveller who saw it."},
    {name:"Mughal Empire",href:"/empire/mughal-empire",img:"/images/encyclopedia/taj-mahal.jpg",meta:"Profile · 1526 CE – 1857 CE",why:"From Babur to Aurangzeb: the richest empire on earth in its day."},
    {name:"Akbar",href:"/encyclopedia/akbar",img:"/images/encyclopedia/akbar.jpg",meta:"Encyclopedia · Person · r. 1556–1605",why:"The Mughal who ruled by inclusion, debating every faith at his court."},
    {name:"Taj Mahal",href:"/encyclopedia/taj-mahal",img:"/images/encyclopedia/taj-mahal.jpg",meta:"Encyclopedia · Work",why:"Grief in white marble: the empire's wealth and craft in one building."},
    {name:"Maratha Empire",href:"/empire/maratha-empire",img:"/images/encyclopedia/shivaji.jpg",meta:"Profile · 1674 CE – 1818 CE",why:"The confederacy that broke Mughal power and dominated eighteenth-century India."}
  ]},
  {slug:"china-dynasty-by-dynasty",title:"China, Dynasty by Dynasty",tagline:"Two thousand years of the world's most durable state tradition.",types:["timekeeper","builder"],eras:["medieval","ancient","earlymodern"],intro:"No polity on earth has been reinvented as many times as China. This path takes the dynastic story in sequence - Han foundations, Tang cosmopolitanism and its great rebellion, Song brilliance, the Mongol century, Ming voyages and walls, and the Qing empire at its vast height - asking each time what survived the fall and carried over.",steps:[
    {name:"Han Dynasty",href:"/empire/han-dynasty",img:"/images/encyclopedia/liu-bang.jpg",meta:"Profile · 206 BCE – 220 CE",why:"The dynasty that defined China: the examination ideal, the historian's craft and the Silk Road."},
    {name:"Tang Dynasty",href:"/empire/tang-dynasty",img:"/images/encyclopedia/emperor-gaozu-of-tang.jpg",meta:"Profile · 618 CE – 907 CE",why:"Chang'an at its height was the largest, most cosmopolitan city on earth."},
    {name:"An Lushan Rebellion",href:"/encyclopedia/an-lushan-rebellion",img:"/images/encyclopedia/an-lushan-rebellion.jpg",meta:"Encyclopedia · Event · 755–763",why:"The catastrophe of 755 that broke the Tang world and echoed for a century."},
    {name:"Song Dynasty",href:"/empire/song-dynasty",img:"/images/encyclopedia/emperor-taizu-of-song.jpg",meta:"Profile · 960 CE – 1279 CE",why:"Paper money, printing, gunpowder and the richest economy of the medieval world."},
    {name:"Yuan Dynasty",href:"/empire/yuan-dynasty",img:"/images/encyclopedia/kublai-khan.jpg",meta:"Profile · 1271 CE – 1368 CE",why:"The Mongol century: China inside the largest land empire in history."},
    {name:"Ming Empire",href:"/empire/ming-empire",img:"/images/encyclopedia/great-wall-of-china.jpg",meta:"Profile · 1368 CE – 1644 CE",why:"Restoration, the Forbidden City, and the choice to turn inward."},
    {name:"Zheng He",href:"/encyclopedia/zheng-he",img:"/images/encyclopedia/zheng-he.jpg",meta:"Encyclopedia · Person · 1371–c. 1433",why:"The admiral whose treasure fleets reached Africa decades before the Portuguese."},
    {name:"Qing Empire",href:"/empire/qing-empire",img:"/images/encyclopedia/kangxi-emperor.jpg",meta:"Profile · 1644 CE – 1912 CE",why:"The last dynasty doubled China's size, then met the nineteenth century."}
  ]},
  {slug:"the-age-of-revolutions",title:"The Age of Revolutions",tagline:"Half a century in which subjects became citizens on three continents.",types:["chronicler","thinker"],eras:["earlymodern","modern"],intro:"Between 1775 and 1830 the political world turned upside down. Thirteen colonies defied an empire; France beheaded its king and exported revolution by arms; the enslaved of Saint-Domingue freed themselves and founded a state; and South America's liberators unmade the oldest colonial empire of all. This path follows the chain reaction.",steps:[
    {name:"American Revolution",href:"/encyclopedia/american-revolution",img:"/images/encyclopedia/american-revolution.jpg",meta:"Encyclopedia · Event · 1765–1783",why:"The war and the ideas that turned thirteen colonies into a republic."},
    {name:"French Revolution",href:"/encyclopedia/french-revolution",img:"/images/encyclopedia/french-revolution.jpg",meta:"Encyclopedia · Event · 1789–1799",why:"The revolution that devoured a monarchy and redefined politics everywhere."},
    {name:"Storming of the Bastille",href:"/encyclopedia/storming-of-the-bastille",img:"/images/encyclopedia/storming-of-the-bastille.jpg",meta:"Encyclopedia · Event · 1789",why:"14 July 1789: the day the crowd entered history."},
    {name:"French Empire",href:"/empire/french-empire",img:"/images/encyclopedia/charles-de-gaulle.jpg",meta:"Profile · 1534 CE – 1980 CE",why:"Napoleon carried the revolution's code, and its armies, across Europe."},
    {name:"Haitian Revolution",href:"/encyclopedia/haitian-revolution",img:"/images/encyclopedia/haitian-revolution.jpg",meta:"Encyclopedia · Event · 1791–1804",why:"The only successful revolution of the enslaved, and the age's most radical act."},
    {name:"Simón Bolívar",href:"/encyclopedia/simon-bolivar",img:"/images/encyclopedia/simon-bolivar.jpg",meta:"Encyclopedia · Person · 1783–1830",why:"The Liberator of six nations, and the disappointments of victory."},
    {name:"Gran Colombia",href:"/empire/gran-colombia",img:"/images/encyclopedia/simon-bolivar.jpg",meta:"Profile · 1819 CE – 1831 CE",why:"Bolivar's great experiment: a united South American republic, and why it broke apart."}
  ]},
  {slug:"women-who-ruled",title:"Women Who Ruled",tagline:"Nine rulers who held power in their own right, from the Nile to the Forbidden City.",types:["chronicler"],eras:["ancient","medieval","earlymodern"],intro:"In most ages the rules said a woman could not rule, and in every age some did anyway. This path crosses four millennia of them: a pharaoh who wore the false beard, warrior queens who fought Rome, the only woman to found a Chinese dynasty, an African queen who out-negotiated an empire, and the empresses who steered Russia and China through their most dangerous centuries.",steps:[
    {name:"Hatshepsut",href:"/encyclopedia/hatshepsut",img:"/images/encyclopedia/hatshepsut.jpg",meta:"Encyclopedia · Person · c. 1479–1458 BCE",why:"The pharaoh who ruled Egypt for two decades and built like a king."},
    {name:"Cleopatra VII",href:"/encyclopedia/cleopatra-vii",img:"/images/encyclopedia/cleopatra-vii.jpg",meta:"Encyclopedia · Person · r. 51–30 BCE",why:"The last Ptolemy, who played Rome's strongmen against each other for twenty years."},
    {name:"Boudica",href:"/encyclopedia/boudica",img:"/images/encyclopedia/boudica.jpg",meta:"Encyclopedia · Person · d. 60 or 61",why:"The Iceni queen whose revolt burned Roman London."},
    {name:"Zenobia",href:"/encyclopedia/zenobia",img:"/images/encyclopedia/zenobia.jpg",meta:"Encyclopedia · Person · c. 240–after 274",why:"The queen of Palmyra who carved an empire from Rome's east."},
    {name:"Wu Zetian",href:"/encyclopedia/wu-zetian",img:"/images/encyclopedia/wu-zetian.jpg",meta:"Encyclopedia · Person · r. 690–705",why:"The only woman to rule China as emperor in her own name."},
    {name:"Seondeok of Silla",href:"/encyclopedia/seondeok-of-silla",img:"",meta:"Encyclopedia · Person · d. 647",why:"Korea's first reigning queen, patron of scholars and stargazers."},
    {name:"Njinga of Ndongo and Matamba",href:"/encyclopedia/njinga-of-ndongo-and-matamba",img:"/images/encyclopedia/njinga-of-ndongo-and-matamba.jpg",meta:"Encyclopedia · Person · c. 1583–1663",why:"The queen who fought and out-bargained the Portuguese for forty years."},
    {name:"Elizabeth I",href:"/encyclopedia/elizabeth-i",img:"/images/encyclopedia/elizabeth-i.jpg",meta:"Encyclopedia · Person · 1533–1603",why:"Gloriana: the unmarried queen who made a weak realm a power."},
    {name:"Catherine the Great",href:"/encyclopedia/catherine-the-great",img:"/images/encyclopedia/catherine-the-great.jpg",meta:"Encyclopedia · Person · 1729–1796",why:"The empress who seized a throne and an age and gave Russia both."}
  ]},
  {slug:"city-states-and-leagues",title:"City-States and Leagues",tagline:"How single cities and their alliances outfought and outtraded empires.",types:["builder","navigator"],eras:["medieval","ancient"],intro:"Not every great power was an empire. Some were single cities with harbours, fleets and ruthless bookkeeping. This path visits the city-states that punched far above their size - Athens and Carthage in the ancient Mediterranean, Venice and Novgorod at the two ends of medieval Europe's trade, and the Hanseatic league of cities that ran the northern seas without a king at all.",steps:[
    {name:"Athens",href:"/empire/athens",img:"/images/encyclopedia/parthenon.jpg",meta:"Profile · 900 BCE – 86 BCE",why:"The democracy that built an Aegean empire on triremes and tribute."},
    {name:"Punic Empire",href:"/empire/punic-empire",img:"/images/encyclopedia/hannibal.jpg",meta:"Profile · 814 BCE – 146 BCE",why:"Carthage: a merchant city that fought three wars with Rome for the western Mediterranean."},
    {name:"Republic of Venice",href:"/empire/republic-of-venice",img:"/images/encyclopedia/venice.jpg",meta:"Profile · 697 CE – 1797 CE",why:"The lagoon republic that turned shipping lanes into an empire of islands and counting houses."},
    {name:"Fourth Crusade",href:"/encyclopedia/fourth-crusade",img:"/images/encyclopedia/fourth-crusade.jpg",meta:"Encyclopedia · Event · 1204",why:"Venice at its most ruthless: a crusade redirected to its commercial rivals' capital."},
    {name:"Novgorod Republic",href:"/empire/novgorod-republic",img:"/images/encyclopedia/church-of-the-transfiguration-on-ilyina-street.jpg",meta:"Profile · 1136 CE – 1478 CE",why:"The merchant republic of the Russian north, where the assembly could dismiss a prince."},
    {name:"Hanseatic League",href:"/empire/hanseatic-league",img:"/images/encyclopedia/bryggen.jpg",meta:"Profile · 1356 CE – 1669 CE",why:"A league of trading cities that made treaties, fought wars and set prices from London to Novgorod."}
  ]},
  {slug:"great-conquerors",title:"The Great Conquerors",tagline:"Eight lives that redrew the map, from Cyrus to Napoleon.",types:["strategist","chronicler"],eras:["ancient","medieval","earlymodern","modern"],intro:"A handful of commanders have bent whole continents to their will, and history has argued about them ever since. This path follows eight of them in order, asking what each conquest cost, what it built, and what outlived the conqueror.",steps:[
    {name:"Cyrus the Great",href:"/encyclopedia/cyrus-the-great",img:"/images/encyclopedia/cyrus-the-great.jpg",meta:"Encyclopedia · Person · c. 600–530 BCE",why:"The founder of the Persian empire, remembered as much for tolerance as for conquest."},
    {name:"Alexander the Great",href:"/encyclopedia/alexander-the-great",img:"/images/encyclopedia/alexander-the-great.jpg",meta:"Encyclopedia · Person · r. 336–323 BCE",why:"Master of the ancient world by thirty-two, dead a year later; the empire broke, the Greek century it opened did not."},
    {name:"Julius Caesar",href:"/encyclopedia/julius-caesar",img:"/images/encyclopedia/julius-caesar.jpg",meta:"Encyclopedia · Person · 100–44 BCE",why:"Gaul conquered, the Republic broken: the general whose name became a title on three continents."},
    {name:"Attila",href:"/encyclopedia/attila",img:"/images/encyclopedia/attila.jpg",meta:"Encyclopedia · Person · c. 406–453",why:"The Hun who bled two Roman empires and vanished with his realm within a decade."},
    {name:"Genghis Khan",href:"/encyclopedia/genghis-khan",img:"/images/encyclopedia/genghis-khan.jpg",meta:"Encyclopedia · Person · c. 1162–1227",why:"From orphan of the steppe to ruler of the largest land empire in history."},
    {name:"Timur",href:"/encyclopedia/timur",img:"/images/encyclopedia/timur.jpg",meta:"Encyclopedia · Person · 1336–1405",why:"The last great steppe conqueror, builder of Samarkand and destroyer of nearly everyone else."},
    {name:"Suleiman the Magnificent",href:"/encyclopedia/suleiman-the-magnificent",img:"/images/encyclopedia/suleiman-the-magnificent.jpg",meta:"Encyclopedia · Person · 1494–1566",why:"Lawgiver to the Ottomans and terror of Europe, at the summit of a dynasty's power."},
    {name:"Napoleon",href:"/encyclopedia/napoleon",img:"/images/encyclopedia/napoleon.jpg",meta:"Encyclopedia · Person · 1769–1821",why:"The artillery officer who crowned himself emperor and forced all Europe to reorganise against him."}
  ]},
  {slug:"explorers-and-travellers",title:"Explorers and Travellers",tagline:"Seven journeys that stitched the world together.",types:["navigator","chronicler"],eras:["medieval","earlymodern"],intro:"Before the world was mapped it was walked, ridden and sailed, often by people who had little idea what lay ahead. This path follows seven travellers whose journeys, and whose accounts of them, changed what the world knew about itself.",steps:[
    {name:"Xuanzang",href:"/encyclopedia/xuanzang",img:"/images/encyclopedia/xuanzang.jpg",meta:"Encyclopedia · Person · 602–664",why:"The Tang monk who walked to India for scriptures and came back a legend."},
    {name:"Marco Polo",href:"/encyclopedia/marco-polo",img:"/images/encyclopedia/marco-polo.jpg",meta:"Encyclopedia · Person · 1254–1324",why:"A Venetian in the service of Kublai Khan, whose book gave Europe its picture of Asia."},
    {name:"Ibn Battuta",href:"/encyclopedia/ibn-battuta",img:"/images/encyclopedia/ibn-battuta.jpg",meta:"Encyclopedia · Person · 1334–1341 at Delhi",why:"Thirty years and some 120,000 kilometres across the Islamic world and beyond."},
    {name:"Zheng He",href:"/encyclopedia/zheng-he",img:"/images/encyclopedia/zheng-he.jpg",meta:"Encyclopedia · Person · 1371–c. 1433",why:"Treasure fleets to Arabia and Africa, decades before Europe rounded the Cape."},
    {name:"Christopher Columbus",href:"/encyclopedia/christopher-columbus",img:"/images/encyclopedia/christopher-columbus.jpg",meta:"Encyclopedia · Person · 1451–1506",why:"Four voyages that joined two worlds and began a catastrophe and an age at once."},
    {name:"Vasco da Gama",href:"/encyclopedia/vasco-da-gama",img:"/images/encyclopedia/vasco-da-gama.jpg",meta:"Encyclopedia · Person · c. 1469–1524",why:"The sea road to India, and the gun-backed trade empire that followed it."},
    {name:"Ferdinand Magellan",href:"/encyclopedia/ferdinand-magellan",img:"/images/encyclopedia/ferdinand-magellan.jpg",meta:"Encyclopedia · Person · c. 1480–1521",why:"The expedition that proved the world round by sailing it, though its commander never came home."}
  ]},
  {slug:"the-great-historians",title:"The Great Historians",tagline:"The writers who invented how we remember the past.",types:["thinker","chronicler"],eras:["ancient","medieval"],intro:"History is itself a human invention, with inventors. This path reads five of them: the Greek who first called his inquiry historia, the exile who dissected power, the Roman hostage who explained Rome to the conquered, China's grand historian, and the North African judge who asked why states rise and fall at all.",steps:[
    {name:"Herodotus",href:"/encyclopedia/herodotus",img:"/images/encyclopedia/herodotus.jpg",meta:"Encyclopedia · Person · c. 484–c. 425 BCE",why:"The father of history: travel, marvels and the Persian Wars, told so the deeds of men not fade."},
    {name:"Thucydides",href:"/encyclopedia/thucydides",img:"/images/encyclopedia/thucydides.jpg",meta:"Encyclopedia · Person · c. 460–c. 400 BCE",why:"The Peloponnesian War by a general who fought in it, history as unflinching analysis of power."},
    {name:"Polybius",href:"/encyclopedia/polybius",img:"/images/encyclopedia/polybius.jpg",meta:"Encyclopedia · Person · c. 200–c. 118 BCE",why:"A Greek hostage in Rome who set out to explain, in forty books, how one city conquered his world in fifty-three years."},
    {name:"Sima Qian",href:"/encyclopedia/sima-qian",img:"/images/encyclopedia/sima-qian.jpg",meta:"Encyclopedia · Person · c. 145–c. 86 BCE",why:"China's grand historian, who chose disgrace over silence to finish the Records that shaped two millennia of Chinese memory."},
    {name:"Ibn Khaldun",href:"/encyclopedia/ibn-khaldun",img:"/images/encyclopedia/ibn-khaldun.jpg",meta:"Encyclopedia · Person · 1332–1406",why:"The Muqaddimah's author, who made the rise and fall of dynasties a science centuries before sociology had a name."}
  ]},
  {slug:"founders-of-world-religions",title:"Founders of World Religions",tagline:"Eight teachers whose words outlived every empire of their day.",types:["thinker","chronicler"],eras:["ancient","medieval","earlymodern"],intro:"The longest-lived institutions in history are not states but faiths. This path visits eight founders and reformers in rough chronological order, treating each historically: what we know of their lives, what they taught, and how communities carried those teachings across continents and millennia.",steps:[
    {name:"Zoroaster",href:"/encyclopedia/zoroaster",img:"",meta:"Encyclopedia · Person · c. 1200–1000 BCE (disputed)",why:"The prophet of ancient Iran whose vision of truth against the lie is among the oldest revealed religions."},
    {name:"Gautama Buddha",href:"/encyclopedia/gautama-buddha",img:"/images/encyclopedia/gautama-buddha.jpg",meta:"Encyclopedia · Person",why:"The prince who left a palace to understand suffering, and whose middle way crossed all Asia."},
    {name:"Confucius",href:"/encyclopedia/confucius",img:"/images/encyclopedia/confucius.jpg",meta:"Encyclopedia · Person · 551–479 BCE",why:"A failed official whose teaching on duty and ritual became the operating system of East Asian states."},
    {name:"Laozi",href:"/encyclopedia/laozi",img:"",meta:"Encyclopedia · Person · 6th–4th century BCE (traditional)",why:"The elusive sage of the Daodejing and the way that cannot be spoken."},
    {name:"Jesus",href:"/encyclopedia/jesus",img:"/images/encyclopedia/jesus.jpg",meta:"Encyclopedia · Person · c. 4 BCE – c. 30/33 CE",why:"A teacher in Roman Judaea whose following became the faith of empires."},
    {name:"Muhammad",href:"/encyclopedia/muhammad",img:"",meta:"Encyclopedia · Person · c. 570–632",why:"The prophet of Islam, whose community became a civilisation within a century of his death."},
    {name:"Guru Nanak",href:"/encyclopedia/guru-nanak",img:"",meta:"Encyclopedia · Person · 1469–1539",why:"The founder of Sikhism, teaching one God and the equality of all people."},
    {name:"Martin Luther",href:"/encyclopedia/martin-luther",img:"/images/encyclopedia/martin-luther.jpg",meta:"Encyclopedia · Person · 1483–1546",why:"The monk whose ninety-five theses split Western Christendom and remade Europe's map."}
  ]},
  {slug:"rebels-against-empire",title:"Rebels against Empire",tagline:"Six risings against the greatest powers of their age.",types:["chronicler","strategist"],eras:["ancient","earlymodern"],intro:"Every empire in this collection was defied by someone who refused its terms. This path follows six of them, enslaved and royal, doomed and triumphant, and asks what their revolts changed, whether they won or lost.",steps:[
    {name:"Spartacus",href:"/encyclopedia/spartacus",img:"/images/encyclopedia/spartacus.jpg",meta:"Encyclopedia · Person · d. 71 BCE",why:"The gladiator whose army of the enslaved shook Rome for two years."},
    {name:"Vercingetorix",href:"/encyclopedia/vercingetorix",img:"/images/encyclopedia/vercingetorix.jpg",meta:"Encyclopedia · Person · c. 82–46 BCE",why:"The chief who united Gaul against Caesar, and paid for it in a Roman triumph."},
    {name:"Arminius",href:"/encyclopedia/arminius",img:"/images/encyclopedia/arminius.jpg",meta:"Encyclopedia · Person · c. 17 BCE – 21 CE",why:"The Roman-trained officer who annihilated three legions and fixed the empire's frontier at the Rhine."},
    {name:"Boudica",href:"/encyclopedia/boudica",img:"/images/encyclopedia/boudica.jpg",meta:"Encyclopedia · Person · d. 60 or 61",why:"The queen whose revolt burned three Roman towns before it broke."},
    {name:"Túpac Amaru II",href:"/encyclopedia/tupac-amaru-ii",img:"/images/encyclopedia/tupac-amaru-ii.jpg",meta:"Encyclopedia · Person · 1738–1781",why:"The Andean rising of 1780 that shook Spanish Peru to its foundations."},
    {name:"Toussaint Louverture",href:"/encyclopedia/toussaint-louverture",img:"/images/encyclopedia/toussaint-louverture.jpg",meta:"Encyclopedia · Person · 1743–1803",why:"The general of the enslaved who defeated three empires and made Haiti possible."}
  ]},
  {slug:"the-great-builders",title:"The Great Builders",tagline:"Rulers who built their worlds in stone, law and cities.",types:["builder","chronicler"],eras:["ancient","medieval","earlymodern"],intro:"Some rulers are remembered for what they destroyed; these are remembered for what they raised. This path crosses four millennia of builders, of codes and canals, libraries and basilicas, mosques, palaces and whole capitals, and asks what building meant to power.",steps:[
    {name:"Hammurabi",href:"/encyclopedia/hammurabi",img:"/images/encyclopedia/hammurabi.jpg",meta:"Encyclopedia · Person · r. c. 1792–1750 BCE",why:"The Babylonian king whose law code, carved in stone, is among the oldest surviving statements of justice."},
    {name:"Ashurbanipal",href:"/encyclopedia/ashurbanipal",img:"/images/encyclopedia/ashurbanipal.jpg",meta:"Encyclopedia · Person · r. 669–627 BCE",why:"Assyria's last great king, whose library at Nineveh preserved Mesopotamia's literature for us to find."},
    {name:"Justinian I",href:"/encyclopedia/justinian-i",img:"/images/encyclopedia/justinian-i.jpg",meta:"Encyclopedia · Person · 482–565",why:"The emperor of Hagia Sophia and the Corpus Juris, Rome's law given its final form."},
    {name:"Charlemagne",href:"/encyclopedia/charlemagne",img:"/images/encyclopedia/charlemagne.jpg",meta:"Encyclopedia · Person · c. 747–814",why:"The Frankish king whose schools and scripts carried learning through Europe's leanest centuries."},
    {name:"Mansa Musa",href:"/encyclopedia/mansa-musa",img:"/images/encyclopedia/mansa-musa.jpg",meta:"Encyclopedia · Person · r. 1312–1337",why:"Mali's pilgrim emperor, whose gold built Timbuktu's mosques and reputation."},
    {name:"Shah Jahan",href:"/encyclopedia/shah-jahan",img:"/images/encyclopedia/shah-jahan.jpg",meta:"Encyclopedia · Person · 1592–1666",why:"The Mughal of the Taj Mahal, grief made architecture."},
    {name:"Louis XIV",href:"/encyclopedia/louis-xiv",img:"/images/encyclopedia/louis-xiv.jpg",meta:"Encyclopedia · Person · 1638–1715",why:"Versailles as a machine of rule: the builder-king who domesticated an aristocracy."},
    {name:"Peter the Great",href:"/encyclopedia/peter-the-great",img:"/images/encyclopedia/peter-the-great.jpg",meta:"Encyclopedia · Person · 1672–1725",why:"The tsar who built a capital on a swamp to force Russia's face towards Europe."}
  ]},
  {slug:"capitals-of-the-world",title:"Capitals of the World",tagline:"Eight cities where power lived.",types:["builder","navigator"],eras:["ancient","medieval","earlymodern"],intro:"Every age has a city where the world's business seems to be decided. This path walks through eight of them at their height, from the gates of Babylon to the lakes of Tenochtitlan, asking what made each the centre of its world and what remains.",steps:[
    {name:"Babylon",href:"/encyclopedia/babylon",img:"/images/encyclopedia/babylon.jpg",meta:"Encyclopedia · Place",why:"Gate of the gods: the ancient world's byword for the great city."},
    {name:"Rome",href:"/encyclopedia/rome",img:"/images/encyclopedia/rome.jpg",meta:"Encyclopedia · Place",why:"A million people at the centre of the Mediterranean world."},
    {name:"Constantinople",href:"/encyclopedia/constantinople",img:"/images/encyclopedia/constantinople.jpg",meta:"Encyclopedia · Place",why:"The new Rome on the Bosphorus, besieged by everyone and taken almost never."},
    {name:"Baghdad",href:"/encyclopedia/baghdad",img:"/images/encyclopedia/baghdad.jpg",meta:"Encyclopedia · Place",why:"The round city of the caliphs, where the world's learning was translated."},
    {name:"Chang'an",href:"/encyclopedia/changan",img:"/images/encyclopedia/changan.jpg",meta:"Encyclopedia · Place",why:"The Tang capital, the largest city on earth and the eastern end of the Silk Road."},
    {name:"Córdoba",href:"/encyclopedia/cordoba",img:"",meta:"Encyclopedia · Place",why:"Umayyad Córdoba, where al-Andalus outshone every city of Latin Europe."},
    {name:"Cusco",href:"/encyclopedia/cusco",img:"/images/encyclopedia/cusco.jpg",meta:"Encyclopedia · Place",why:"The navel of the Inca world, from which the four quarters ran."},
    {name:"Tenochtitlan",href:"/encyclopedia/tenochtitlan",img:"/images/encyclopedia/tenochtitlan.jpg",meta:"Encyclopedia · Place",why:"The island capital on the lake, larger than the European cities of its conquerors."}
  ]},
  {slug:"turning-point-battles",title:"Turning-Point Battles",tagline:"Eight days of fighting on which centuries turned.",types:["strategist"],eras:["ancient","medieval","earlymodern"],intro:"Most battles decide little; a few decide eras. This path examines eight engagements whose outcomes redirected history, not for the drama alone, but for what each reveals about the states that fought and the worlds that followed.",steps:[
    {name:"Battle of Marathon",href:"/encyclopedia/battle-of-marathon",img:"/images/encyclopedia/battle-of-marathon.jpg",meta:"Encyclopedia · Event · 490 BCE",why:"The Greek line held, and with it the independence that made the classical world possible."},
    {name:"Battle of Gaugamela",href:"/encyclopedia/battle-of-gaugamela",img:"/images/encyclopedia/battle-of-gaugamela.jpg",meta:"Encyclopedia · Event · 331 BCE",why:"One afternoon ended two centuries of Persian empire and opened Asia to Alexander."},
    {name:"Battle of Actium",href:"/encyclopedia/battle-of-actium",img:"/images/encyclopedia/battle-of-actium.jpg",meta:"Encyclopedia · Event · 31 BCE",why:"The sea battle that ended Rome's civil wars and began its emperors."},
    {name:"Battle of Tours",href:"/encyclopedia/battle-of-tours",img:"/images/encyclopedia/battle-of-tours.jpg",meta:"Encyclopedia · Event · 732 CE",why:"The Frankish victory that fixed the limit of the Arab advance into western Europe."},
    {name:"Battle of Manzikert",href:"/encyclopedia/battle-of-manzikert",img:"/images/encyclopedia/battle-of-manzikert.jpg",meta:"Encyclopedia · Event · 1071",why:"The day Anatolia began to turn Turkish, and Byzantium began its long retreat."},
    {name:"Battle of Ain Jalut",href:"/encyclopedia/battle-of-ain-jalut",img:"/images/encyclopedia/battle-of-ain-jalut.jpg",meta:"Encyclopedia · Event · 1260",why:"The Mamluks stopped the Mongols, the first time the conquerors of everywhere were turned back for good."},
    {name:"Battle of Lepanto",href:"/encyclopedia/battle-of-lepanto",img:"/images/encyclopedia/battle-of-lepanto.jpg",meta:"Encyclopedia · Event · 1571",why:"The last great battle of oared ships broke the spell of Ottoman invincibility at sea."},
    {name:"Battle of Waterloo",href:"/encyclopedia/battle-of-waterloo",img:"/images/encyclopedia/battle-of-waterloo.jpg",meta:"Encyclopedia · Event",why:"The afternoon that closed a quarter-century of world war and set Europe's order for a century."}
  ]},
  {slug:"wonders-and-monuments",title:"Wonders and Monuments",tagline:"What the great builders left standing.",types:["builder","navigator"],eras:["ancient","medieval","earlymodern"],intro:"Stone keeps promises that documents cannot. This path visits eight monuments, from the one surviving ancient wonder to a Mughal tomb, reading each as evidence: of the state that raised it, the labour that built it, and the beliefs it was meant to outlast.",steps:[
    {name:"Great Pyramid of Giza",href:"/encyclopedia/great-pyramid-of-giza",img:"/images/encyclopedia/great-pyramid-of-giza.jpg",meta:"Encyclopedia · Work · c. 2560 BCE",why:"The oldest of the seven wonders and the only one still standing."},
    {name:"Great Wall of China",href:"/encyclopedia/great-wall-of-china",img:"/images/encyclopedia/great-wall-of-china.jpg",meta:"Encyclopedia · Work",why:"Two thousand years of walls against the steppe, joined into one idea."},
    {name:"Petra",href:"/encyclopedia/petra",img:"/images/encyclopedia/petra.jpg",meta:"Encyclopedia · Place",why:"A caravan city carved into rose-red rock at the crossroads of incense routes."},
    {name:"Hagia Sophia",href:"/encyclopedia/hagia-sophia",img:"/images/encyclopedia/hagia-sophia.jpg",meta:"Encyclopedia · Work · 537 CE",why:"Justinian's dome, church then mosque then museum then mosque, fifteen centuries at the centre of two faiths."},
    {name:"Angkor Wat",href:"/encyclopedia/angkor-wat",img:"/images/encyclopedia/angkor-wat.jpg",meta:"Encyclopedia · Work",why:"The largest religious monument on earth, the Khmer state in stone."},
    {name:"Alhambra",href:"/encyclopedia/alhambra",img:"/images/encyclopedia/alhambra.jpg",meta:"Encyclopedia · Work",why:"The last palace of al-Andalus, beauty built on a falling frontier."},
    {name:"Machu Picchu",href:"/encyclopedia/machu-picchu",img:"/images/encyclopedia/machu-picchu.jpg",meta:"Encyclopedia · Place",why:"An Inca royal estate the conquest never found."},
    {name:"Taj Mahal",href:"/encyclopedia/taj-mahal",img:"/images/encyclopedia/taj-mahal.jpg",meta:"Encyclopedia · Work",why:"The Mughal empire's wealth and craft condensed into one tomb."}
  ]},
  {slug:"plagues-and-pandemics",title:"Plagues and Pandemics",tagline:"How disease has redirected history as surely as any army.",types:["timekeeper","thinker"],eras:["medieval","earlymodern","modern"],intro:"Microbes have ended more dynasties than generals have. This path follows disease through history, from the plague that broke Justinian's reconquest to the smallpox that emptied continents, asking how societies broke, adapted and rebuilt.",steps:[
    {name:"Black Death",href:"/encyclopedia/black-death",img:"/images/encyclopedia/black-death.jpg",meta:"Encyclopedia · Event",why:"A third to half of Europe dead in seven years, and the medieval order with them."},
    {name:"Smallpox",href:"/encyclopedia/smallpox",img:"/images/encyclopedia/smallpox.jpg",meta:"Encyclopedia · Term",why:"The conqueror that travelled with the conquistadors and did most of their work."},
    {name:"Byzantine Empire",href:"/empire/byzantine-empire",img:"/images/encyclopedia/second-arab-siege-of-constantinople.jpg",meta:"Profile · 330 CE – 1453 CE",why:"Justinian's plague arrived at the empire's height and helped bury his reconquest of the West."},
    {name:"Aztec Empire",href:"/empire/aztec-empire",img:"/images/encyclopedia/templo-mayor.jpg",meta:"Profile · 1325 CE – 1521 CE",why:"An empire of millions brought down as much by epidemics as by Spanish steel."},
    {name:"First World War",href:"/encyclopedia/first-world-war",img:"/images/encyclopedia/first-world-war.jpg",meta:"Encyclopedia · Event",why:"The war whose ending coincided with the deadliest influenza in history."}
  ]},
  {slug:"the-world-wars",title:"The World Wars",tagline:"Three decades that ended the age of empires.",types:["strategist","timekeeper"],eras:["modern"],intro:"Between 1914 and 1945 the states of Europe fought two wars that consumed the world and, in the end, their own empires. This path follows the arc from Sarajevo to Hiroshima: the war that broke four empires, the peace that failed, and the war that finished what the first began.",steps:[
    {name:"First World War",href:"/encyclopedia/first-world-war",img:"/images/encyclopedia/first-world-war.jpg",meta:"Encyclopedia · Event",why:"Four years that killed four empires: Hohenzollern, Habsburg, Romanov and Ottoman."},
    {name:"Treaty of Versailles",href:"/encyclopedia/treaty-of-versailles",img:"/images/encyclopedia/treaty-of-versailles.jpg",meta:"Encyclopedia · Event",why:"The peace that ended the war and seeded the next."},
    {name:"German Empire",href:"/empire/german-empire",img:"/images/encyclopedia/proclamation-of-the-german-empire.jpg",meta:"Profile · 1871 CE – 1918 CE",why:"The rising power whose fears and ambitions drove the July crisis of 1914."},
    {name:"Empire of Japan",href:"/empire/empire-of-japan",img:"/images/encyclopedia/emperor-meiji.jpg",meta:"Profile · 1868 CE – 1945 CE",why:"The one non-European empire of the age, from Meiji ascent to 1945."},
    {name:"Second World War",href:"/encyclopedia/second-world-war",img:"/images/encyclopedia/second-world-war.jpg",meta:"Encyclopedia · Event",why:"The deadliest war in history, and the end of Europe's centuries at the centre of the world."},
    {name:"Atomic bombings of Hiroshima and Nagasaki",href:"/encyclopedia/atomic-bombings-of-hiroshima-and-nagasaki",img:"/images/encyclopedia/atomic-bombings-of-hiroshima-and-nagasaki.jpg",meta:"Encyclopedia · Event · 1945",why:"The weeks that ended the war and opened an age in which great-power war risks everything."},
    {name:"British Empire",href:"/empire/british-empire",img:"/images/encyclopedia/slavery-abolition-act-1833.jpg",meta:"Profile · 1583 CE – 1997 CE",why:"Victorious and exhausted: how winning two world wars still cost an empire."}
  ]},
  {slug:"money-and-trade",title:"Money and Trade",tagline:"The routes, coins and companies that moved the world.",types:["builder","navigator"],eras:["earlymodern","medieval"],intro:"Armies take headlines, but trade pays for them. This path follows wealth through history, silk and spice, caravans and sea lanes, the banks that financed empires and the company that became one, asking how commerce built and broke the powers of every age.",steps:[
    {name:"Silk",href:"/encyclopedia/silk",img:"/images/encyclopedia/silk.jpg",meta:"Encyclopedia · Term",why:"The fibre that named a road and moved ideas along with cloth."},
    {name:"Trans-Saharan trade",href:"/encyclopedia/trans-saharan-trade",img:"",meta:"Encyclopedia · Term",why:"Gold north, salt south: the caravans that made Ghana, Mali and Songhai."},
    {name:"Indian Ocean trade",href:"/encyclopedia/indian-ocean-trade",img:"",meta:"Encyclopedia · Term",why:"The monsoon exchange that linked Africa, Arabia, India and China long before Europeans arrived."},
    {name:"Spice trade",href:"/encyclopedia/spice-trade",img:"/images/encyclopedia/spice-trade.jpg",meta:"Encyclopedia · Term",why:"Cloves and pepper: small cargoes worth fortunes, and the wars fought to corner them."},
    {name:"Republic of Venice",href:"/empire/republic-of-venice",img:"/images/encyclopedia/venice.jpg",meta:"Profile · 697 CE – 1797 CE",why:"The middleman city that grew rich on the eastern trade and fought to keep it."},
    {name:"Dutch East India Company",href:"/encyclopedia/dutch-east-india-company",img:"/images/encyclopedia/dutch-east-india-company.jpg",meta:"Encyclopedia · Institution",why:"The joint-stock company with a flag, an army and an empire of its own."},
    {name:"Bank of Amsterdam",href:"/encyclopedia/bank-of-amsterdam",img:"/images/encyclopedia/bank-of-amsterdam.jpg",meta:"Encyclopedia · Institution · 1609–1820",why:"The bank at the heart of the first modern financial centre."}
  ]},
  {slug:"pacific-voyagers",title:"Voyagers of the Pacific",tagline:"Canoes, stars and sacred kings: the peoples who settled the widest ocean on Earth, and what happened when Europe arrived.",types:["navigator","chronicler"],eras:["medieval","earlymodern","modern"],intro:"The Pacific was settled long before it was mapped. Descendants of Austronesian seafarers sailed east across open ocean, reading stars, winds and swells, until Polynesians had reached Hawaii, New Zealand and Rapa Nui, the corners of a triangle thousands of kilometres across. On the islands they built societies of their own: a sacred line of kings on Tonga, a basalt city in the lagoon of Pohnpei, the moai of Easter Island. This path follows them from the first voyages to the encounters with European ships in the eighteenth century, and on to the kingdoms that rose, fell or, in Tonga's case, endured.",steps:[
    {name:"Polynesians",href:"/encyclopedia/polynesians",img:"/images/encyclopedia/polynesians.jpg",meta:"Encyclopedia · People",why:"Descended from Austronesian seafarers of the Lapita culture, they reached Tonga and Samoa around 800 BCE and later found the remotest islands by stars, winds and swells."},
    {name:"Tuʻi Tonga Empire",href:"/empire/tu-i-tonga-empire",img:"/images/encyclopedia/haamonga-a-maui.jpg",meta:"Profile · 950 CE – 1865 CE",why:"A line of sacred kings at Muʻa on Tongatapu whose voyaging and tribute networks reached ʻUvea, Samoa and eastern Fiji."},
    {name:"Saudeleur dynasty",href:"/empire/saudeleur-dynasty",img:"/images/encyclopedia/temwen-island.jpg",meta:"Profile · 1100 CE – 1628 CE",why:"The first rulers of all Pohnpei governed from Nan Madol, nearly a hundred artificial islets of stacked basalt in a coral lagoon."},
    {name:"Rapa Nui",href:"/empire/rapa-nui",img:"/images/encyclopedia/rano-raraku.jpg",meta:"Profile · 1200 CE – 1888 CE",why:"Settled around 1200 on one of the remotest inhabited islands on Earth, its people carved some 887 moai and devised rongorongo, the only possible script known from Polynesia."},
    {name:"Tupaia",href:"/encyclopedia/tupaia",img:"",meta:"Encyclopedia · Person · c. 1725–1770",why:"The Raiatean priest and navigator who joined Cook's Endeavour in 1769, drew a chart of the islands Tahitians knew and spoke for Cook with the Māori."},
    {name:"James Cook",href:"/encyclopedia/james-cook",img:"/images/encyclopedia/james-cook.jpg",meta:"Encyclopedia · Person · 1728–1779",why:"Three voyages between 1768 and 1779 charted New Zealand and eastern Australia; the last ended with his death in a clash at Kealakekua Bay on Hawaii Island."},
    {name:"Kingdom of Hawaii",href:"/empire/kingdom-of-hawaii",img:"/images/encyclopedia/iolani-palace.jpg",meta:"Profile · 1795 CE – 1893 CE",why:"United by Kamehameha I by 1810 and recognised by Britain and France in 1843, it was overthrown in 1893 by businessmen backed by US troops."},
    {name:"Treaty of Waitangi",href:"/encyclopedia/treaty-of-waitangi",img:"/images/encyclopedia/treaty-of-waitangi.jpg",meta:"Encyclopedia · Event · 1840",why:"Signed in 1840 by the British Crown and Māori chiefs, in English and Māori texts that differ on sovereignty: a dispute the Waitangi Tribunal has heard since 1975."},
    {name:"Kingdom of Tonga",href:"/empire/kingdom-of-tonga",img:"/images/encyclopedia/george-tupou-i.jpg",meta:"Profile · 1845 CE – 2025 CE",why:"The only Pacific island state never formally colonised: the kingdom George Tupou I founded in 1845, whose constitution of 1875 is still in force."}
  ]},
  {slug:"the-story-of-writing",title:"The Story of Writing",tagline:"From wedges pressed into clay to the printed page: how the world learned to write.",types:["thinker","builder"],eras:["ancient","medieval"],intro:"Writing was invented more than once, and borrowed far more often. It began in Mesopotamia and Egypt with temple accounts and royal display, and from those beginnings scripts were adapted and reinvented across Eurasia: syllables for the Mycenaean palaces, an alphabet pressed into clay at Ugarit, letters made for the Slavs and for the people of Korea. This path follows that story from the first clay tablets to the printers who multiplied the written word, with the decipherers who taught us to read the old scripts again.",steps:[
    {name:"Cuneiform",href:"/encyclopedia/cuneiform",img:"/images/encyclopedia/cuneiform.jpg",meta:"Encyclopedia · Term",why:"Wedge-shaped signs pressed into clay, invented in Mesopotamia in the late fourth millennium BCE and used for some three thousand years, for Sumerian, Akkadian, Hittite and more."},
    {name:"Egyptian hieroglyphs",href:"/encyclopedia/egyptian-hieroglyphs",img:"/images/encyclopedia/egyptian-hieroglyphs.jpg",meta:"Encyclopedia · Term",why:"Egypt's formal script of pictorial signs for sounds and words: the peace treaty after Kadesh survives in them at Karnak, and in cuneiform at Hattusa."},
    {name:"Linear B",href:"/encyclopedia/linear-b",img:"/images/encyclopedia/linear-b.jpg",meta:"Encyclopedia · Term · c. 1450–1200 BCE",why:"The Mycenaean palaces' syllabic script, adapted from Linear A, listed goods, workers and offerings; Michael Ventris showed in 1952 that it was Greek."},
    {name:"Kingdom of Ugarit",href:"/empire/kingdom-of-ugarit",img:"/images/encyclopedia/tale-of-aqhat.jpg",meta:"Profile · 1800 BCE – 1185 BCE",why:"Its scribes pressed an alphabet of 30 cuneiform signs into clay, and the fire that destroyed the city baked their tablets hard."},
    {name:"Edicts of Ashoka",href:"/encyclopedia/edicts-of-ashoka",img:"/images/encyclopedia/edicts-of-ashoka.jpg",meta:"Encyclopedia · Work",why:"The Maurya emperor's inscriptions on rocks and pillars, of the third century BCE, are the earliest substantial written records of Indian history."},
    {name:"Rosetta Stone",href:"/encyclopedia/rosetta-stone",img:"/images/encyclopedia/rosetta-stone.jpg",meta:"Encyclopedia · Work · 196 BCE",why:"One decree of 196 BCE in hieroglyphs, Demotic and Greek: its parallel texts let Champollion decipher hieroglyphs in 1822."},
    {name:"Cyril and Methodius",href:"/encyclopedia/cyril-and-methodius",img:"/images/encyclopedia/cyril-and-methodius.jpg",meta:"Encyclopedia · Person · 9th century",why:"Byzantine brothers who created the Glagolitic alphabet in the ninth century and translated the liturgy into Old Church Slavonic."},
    {name:"Movable type",href:"/encyclopedia/movable-type",img:"/images/encyclopedia/movable-type.jpg",meta:"Encyclopedia · Term",why:"Bi Sheng's reusable ceramic characters of the eleventh century, about four centuries before Gutenberg's metal type."},
    {name:"Hangul",href:"/encyclopedia/hangul",img:"/images/encyclopedia/hangul.jpg",meta:"Encyclopedia · Term · 1443",why:"An alphabet made in 1443 under King Sejong and promulgated as 'the proper sounds for instructing the people', long overshadowed by classical Chinese."}
  ]},
  {slug:"revolutions-in-asia",title:"Revolutions in Asia",tagline:"From Meiji Japan to Khomeini's Iran: a century in which Asian peoples overthrew their rulers and remade their states.",types:["chronicler","strategist"],eras:["modern"],intro:"Between 1868 and 1979 revolution remade state after state across Asia. Some revolutions came from above, as when Japan's reformers restored direct imperial rule to modernise the country, or Atatürk rebuilt Turkey as a secular republic; some were risings against colonial rule, in the Philippines, Vietnam and Indonesia; others curbed or overthrew old monarchies, in Persia, China and Iran. This path follows nine of them, from the end of the Tokugawa shogunate to the founding of the Islamic Republic.",steps:[
    {name:"Meiji Restoration",href:"/encyclopedia/meiji-restoration",img:"/images/encyclopedia/meiji-restoration.jpg",meta:"Encyclopedia · Event · 1868",why:"The revolution of 1868 that ended the Tokugawa shogunate, restored direct imperial rule and launched Japan's rapid modernisation."},
    {name:"Philippine Revolution",href:"/encyclopedia/philippine-revolution",img:"/images/encyclopedia/philippine-revolution.jpg",meta:"Encyclopedia · Event · 1896–1898",why:"Begun by the Katipunan in 1896 against Spanish rule, it declared independence on 12 June 1898, but Spain then ceded the islands to the United States."},
    {name:"Persian Constitutional Revolution",href:"/encyclopedia/persian-constitutional-revolution",img:"/images/encyclopedia/persian-constitutional-revolution.jpg",meta:"Encyclopedia · Event · 1905–1911",why:"Merchants, clergy and reformers forced the Qajar shah to grant a constitution and an elected parliament, the Majlis, in 1906."},
    {name:"Xinhai Revolution",href:"/encyclopedia/xinhai-revolution",img:"/images/encyclopedia/xinhai-revolution.jpg",meta:"Encyclopedia · Event · 1911",why:"A mutiny at Wuchang in 1911 spread from province to province until the boy emperor Puyi abdicated and the Republic of China was founded."},
    {name:"Atatürk's reforms",href:"/encyclopedia/ataturks-reforms",img:"",meta:"Encyclopedia · Event · 1923–1938",why:"A secular national republic in place of the Ottoman Empire: the caliphate abolished, the Latin alphabet adopted, the vote given to women."},
    {name:"August Revolution",href:"/encyclopedia/august-revolution",img:"/images/encyclopedia/august-revolution.jpg",meta:"Encyclopedia · Event · 1945",why:"After Japan's surrender in 1945 the Viet Minh took power across Vietnam, and Ho Chi Minh proclaimed the Democratic Republic on 2 September."},
    {name:"Indonesian National Revolution",href:"/encyclopedia/indonesian-national-revolution",img:"/images/encyclopedia/indonesian-national-revolution.jpg",meta:"Encyclopedia · Event · 1947–1949",why:"Sukarno proclaimed independence in August 1945; after two Dutch offensives, international pressure brought the Netherlands to recognise it in 1949."},
    {name:"Chinese Civil War",href:"/encyclopedia/chinese-civil-war",img:"/images/encyclopedia/chinese-civil-war.jpg",meta:"Encyclopedia · Event · 1927–1949",why:"The Communists under Mao Zedong defeated the Nationalists and proclaimed the People's Republic of China in October 1949."},
    {name:"Iranian Revolution",href:"/encyclopedia/iranian-revolution",img:"",meta:"Encyclopedia · Event · 1978–1979",why:"Mass protests and strikes drove the shah out of Iran in January 1979, and Khomeini returned to found the Islamic Republic."}
  ]},
  {slug:"the-first-cities",title:"The First Cities",tagline:"Walls, temples, archives and planned streets: where people first lived together by the thousand.",types:["builder","timekeeper"],eras:["ancient"],intro:"For most of human history people lived in camps and villages. Then, in a few favoured places, they began to build cities: places of thousands, with temples, palaces, walls, workshops and the records to run them. This path visits early cities in the Near East, Egypt, the Indus, Peru, China and Mexico, from a spring-fed settlement at Jericho to the planned avenues of Teotihuacan, and shows how differently, and in how many separate places, urban life began.",steps:[
    {name:"Jericho",href:"/encyclopedia/jericho",img:"/images/encyclopedia/jericho.jpg",meta:"Encyclopedia · Place",why:"Settled at Tell es-Sultan from about 9000 BCE beside its springs, one of the oldest continuously inhabited places in the world."},
    {name:"Uruk",href:"/empire/uruk",img:"/images/encyclopedia/warka-vase.jpg",meta:"Profile · 3500 BCE – 1802 BCE",why:"The largest city in the world in the fourth millennium BCE, where temple administrators began recording goods on clay tablets around 3300 BCE."},
    {name:"Memphis, Egypt",href:"/encyclopedia/memphis-egypt",img:"/images/encyclopedia/memphis-egypt.jpg",meta:"Encyclopedia · Place",why:"Founded around 3100 BCE where the Nile valley meets the Delta, Egypt's capital for much of its history, with the pyramids of the Old Kingdom in its cemeteries."},
    {name:"Mari",href:"/empire/mari",img:"/images/encyclopedia/statue-of-ebih-il.jpg",meta:"Profile · 2900 BCE – 1761 BCE",why:"For over a thousand years it controlled river traffic on the middle Euphrates; its archive of some 20,000 tablets survived Hammurabi's conquest."},
    {name:"Caral",href:"/encyclopedia/caral",img:"/images/encyclopedia/caral.jpg",meta:"Encyclopedia · Place · c. 2600–2000 BCE",why:"Platform mounds and sunken circular plazas from about 2600 BCE make it one of the oldest cities in the Americas."},
    {name:"Indus Valley Civilisation",href:"/encyclopedia/indus-valley-civilisation",img:"/images/encyclopedia/indus-valley-civilisation.jpg",meta:"Encyclopedia · State",why:"Planned cities such as Harappa and Mohenjo-daro, linked by sea through the Gulf to Mesopotamia, whose texts probably call the land Meluhha."},
    {name:"Ur",href:"/encyclopedia/ur",img:"/images/encyclopedia/ur.jpg",meta:"Encyclopedia · Place",why:"Capital of the Third Dynasty of Ur, whose kings raised its great ziggurat, until the Elamites sacked it around 2004 BCE."},
    {name:"Yinxu",href:"/encyclopedia/yinxu",img:"/images/encyclopedia/yinxu.jpg",meta:"Encyclopedia · Place · c. 1300–1046 BCE",why:"The last Shang capital, near Anyang: palace and temple foundations, royal tombs, bronze workshops and tens of thousands of inscribed oracle bones."},
    {name:"Teotihuacan",href:"/empire/teotihuacan",img:"/images/encyclopedia/pyramid-of-the-sun.jpg",meta:"Profile · 100 BCE – 550 CE",why:"A planned city of perhaps 100,000 people in the Valley of Mexico, among the largest in the world in the 3rd to 6th centuries CE."}
  ]},
  {slug:"indian-ocean-world",title:"The Indian Ocean World",tagline:"Monsoon winds, ivory, gold and pepper: the sea that joined East Africa, Arabia, India and the Indies.",types:["navigator","builder"],eras:["medieval","ancient","earlymodern"],intro:"Long before Europeans sailed into it, the Indian Ocean was one of the great highways of the world's trade. Its monsoon winds blew one way in summer and the other in winter, and merchants timed their voyages to them, carrying ivory and gold from Africa, pepper from Malabar, and silk and porcelain from China. This path follows the ports and powers that grew rich on that traffic, from Aksum and Srivijaya to the Swahili sultans of Kilwa and the Zamorins of Calicut, and ends as Portuguese guns arrived to claim the trade.",steps:[
    {name:"Monsoon",href:"/encyclopedia/monsoon",img:"/images/encyclopedia/monsoon.jpg",meta:"Encyclopedia · Term",why:"The seasonal reversal of winds that governed farming and seaborne trade across the region: sailors timed their voyages to it."},
    {name:"Periplus of the Erythraean Sea",href:"/encyclopedia/periplus-of-the-erythraean-sea",img:"/images/encyclopedia/periplus-of-the-erythraean-sea.jpg",meta:"Encyclopedia · Work · mid-1st century CE",why:"A Greek guide of the mid-1st century CE to the ports and goods from Egypt to East Africa and India, with the earliest historical mention of Aksum."},
    {name:"Aksumite Empire",href:"/empire/aksumite-empire",img:"/images/encyclopedia/ezana.jpg",meta:"Profile · 100 CE – 940 CE",why:"Grew rich sending African ivory and gold out through its Red Sea port of Adulis, and minted its own gold coins."},
    {name:"Srivijaya Empire",href:"/empire/srivijaya-empire",img:"/images/encyclopedia/sailendra-dynasty.jpg",meta:"Profile · 650 CE – 1377 CE",why:"From Palembang on Sumatra it ruled the Strait of Malacca from the 7th to the 13th century, taxing the shipping between China and India."},
    {name:"Chola invasion of Srivijaya",href:"/encyclopedia/chola-invasion-of-srivijaya",img:"/images/encyclopedia/chola-invasion-of-srivijaya.jpg",meta:"Encyclopedia · Event · 1025; 1068",why:"In 1025 a Chola fleet from southern India sacked Srivijaya's ports and seized its ruler, breaking the monopoly it lived on."},
    {name:"Kilwa Sultanate",href:"/empire/kilwa-sultanate",img:"/images/encyclopedia/great-mosque-of-kilwa.jpg",meta:"Profile · 957 CE – 1513 CE",why:"An island sultanate that grew rich as the middleman for the gold of the Zimbabwe plateau; Ibn Battuta praised its sultan around 1331."},
    {name:"Ming treasure voyages",href:"/encyclopedia/ming-treasure-voyages",img:"/images/encyclopedia/ming-treasure-voyages.jpg",meta:"Encyclopedia · Event · 1405–1433",why:"Seven great fleets under Zheng He reached Arabia and East Africa between 1405 and 1433; then the voyages were ended and never resumed."},
    {name:"Zamorin",href:"/encyclopedia/zamorin",img:"/images/encyclopedia/zamorin.jpg",meta:"Encyclopedia · Term",why:"Calicut's rulers grew rich on the spice trade with Arab and other Muslim merchants, received Vasco da Gama in 1498 and then fought the Portuguese."},
    {name:"Malacca",href:"/encyclopedia/malacca",img:"/images/encyclopedia/malacca.jpg",meta:"Encyclopedia · Place",why:"Under its sultanate, founded around 1400, it became South-East Asia's leading entrepôt, until the Portuguese captured it in 1511."}
  ]},
  {slug:"al-andalus",title:"Al-Andalus",tagline:"Nearly eight centuries of Muslim Iberia, from Tariq's crossing in 711 to the surrender of Granada in 1492.",types:["thinker","timekeeper"],eras:["medieval"],intro:"In 711 an army from North Africa crossed into Spain, and for nearly eight centuries much of the Iberian Peninsula was al-Andalus. Under the Umayyads of Córdoba it held the largest city of western Europe and a centre of learning, where Muslims, Christians and Jews lived under one rule, though not as equals. Then it broke into rival kingdoms, was taken over by Berber empires from Morocco and was conquered piece by piece by the Christian kingdoms of the north. This path follows that story through its rulers, buildings and thinkers to the last Muslim state, at Granada.",steps:[
    {name:"Umayyad conquest of Hispania",href:"/encyclopedia/umayyad-conquest-of-hispania",img:"/images/encyclopedia/umayyad-conquest-of-hispania.jpg",meta:"Encyclopedia · Event · 711 CE",why:"In 711 Tariq ibn Ziyad crossed from North Africa and defeated King Roderic; within a few years most of the peninsula was under Umayyad rule."},
    {name:"Emirate of Córdoba",href:"/empire/emirate-of-cordoba",img:"/images/encyclopedia/mosque-cathedral-of-cordoba.jpg",meta:"Profile · 756 CE – 929 CE",why:"Founded in 756 by Abd al-Rahman I, a survivor of the Abbasid massacre of his family, it made al-Andalus an independent Islamic state."},
    {name:"Mosque–Cathedral of Córdoba",href:"/encyclopedia/mosque-cathedral-of-cordoba",img:"/images/encyclopedia/mosque-cathedral-of-cordoba.jpg",meta:"Encyclopedia · Work · 785",why:"Begun in 785 and enlarged by later emirs and caliphs, its forest of double-arched columns became a cathedral after the Christian conquest of 1236."},
    {name:"Mozarabs",href:"/encyclopedia/mozarabs",img:"/images/encyclopedia/mozarabs.jpg",meta:"Encyclopedia · People",why:"Christians who lived under Muslim rule and adopted Arabic language and culture while keeping their faith and their own liturgy."},
    {name:"Caliphate of Córdoba",href:"/empire/caliphate-of-cordoba",img:"/images/encyclopedia/abd-al-rahman-iii.jpg",meta:"Profile · 929 CE – 1031 CE",why:"Abd al-Rahman III's caliphate of 929 made Córdoba the largest city of western Europe, with the palace city of Madinat al-Zahra and celebrated libraries."},
    {name:"Taifa",href:"/encyclopedia/taifa",img:"/images/encyclopedia/taifa.jpg",meta:"Encyclopedia · Institution",why:"When the caliphate broke apart, rival taifa kings paid tribute to Christian rulers, until the fall of Toledo in 1085 brought in the Almoravids."},
    {name:"Averroes",href:"/encyclopedia/averroes",img:"/images/encyclopedia/averroes.jpg",meta:"Encyclopedia · Person · 1126–1198",why:"Philosopher, physician and judge to the Almohad caliphs, whose commentaries on Aristotle, translated into Latin, shaped European scholasticism."},
    {name:"Maimonides",href:"/encyclopedia/maimonides",img:"/images/encyclopedia/maimonides.jpg",meta:"Encyclopedia · Person · c. 1138–1204",why:"Born in Córdoba, he left al-Andalus with his family under Almohad pressure, settled in Egypt and became one of medieval Judaism's most influential thinkers."},
    {name:"Emirate of Granada",href:"/empire/emirate-of-granada",img:"/images/encyclopedia/alhambra.jpg",meta:"Profile · 1232 CE – 1492 CE",why:"The last Muslim state in Iberia survived as a tributary of Castile for over 250 years, built the Alhambra and surrendered on 2 January 1492."}
  ]},
  {slug:"bronze-age-collapse",title:"The Bronze Age Collapse",tagline:"How a connected world of great kings fell apart around 1200 BCE, and what grew in its place.",types:["timekeeper","strategist"],eras:["ancient"],intro:"In the fourteenth and thirteenth centuries BCE the eastern Mediterranean and the Near East formed something like an international system: great kings in Egypt, Hatti, Mitanni, Babylon and Assyria wrote to one another as brothers, exchanged gifts and princesses, and fought over Syria. Within a few decades around 1200 BCE much of it was gone. Palaces burned, the Hittite Empire disappeared, cities such as Ugarit were never rebuilt, and Egypt survived only in weakened form. This path follows the great powers, the crisis and the new world of iron and smaller kingdoms that came after.",steps:[
    {name:"Late Bronze Age",href:"/encyclopedia/late-bronze-age",img:"/images/encyclopedia/late-bronze-age.jpg",meta:"Encyclopedia · Idea",why:"An age of great territorial powers, Egypt, the Hittites, Mitanni, Babylon and Assyria, linked by diplomacy, trade and chariot warfare."},
    {name:"Amarna letters",href:"/encyclopedia/amarna-letters",img:"/images/encyclopedia/amarna-letters.jpg",meta:"Encyclopedia · Work · 14th century BCE",why:"Clay tablets of the 14th century BCE in which the pharaohs and the kings of Babylon, Mitanni and the Hittites wrote to one another in Akkadian."},
    {name:"Battle of Kadesh",href:"/encyclopedia/battle-of-kadesh",img:"/images/encyclopedia/battle-of-kadesh.jpg",meta:"Encyclopedia · Event · 1274 BCE",why:"Ramesses II and Muwatalli II fought one of antiquity's best-documented chariot battles in 1274 BCE, and their kingdoms later made peace."},
    {name:"Hittite Empire",href:"/empire/hittite-empire",img:"/images/encyclopedia/hattusa.jpg",meta:"Profile · 1650 BCE – 1178 BCE",why:"Anatolia's great power rivalled Egypt for Syria and left the earliest peace treaty surviving in both sides' versions, until Hattusa burned around 1180 BCE."},
    {name:"Kingdom of Ugarit",href:"/empire/kingdom-of-ugarit",img:"/images/encyclopedia/tale-of-aqhat.jpg",meta:"Profile · 1800 BCE – 1185 BCE",why:"A rich port whose last letters report enemy ships off the coast; it was sacked and burned around 1185 BCE and never rebuilt."},
    {name:"Sea Peoples",href:"/encyclopedia/sea-peoples",img:"/images/encyclopedia/sea-peoples.jpg",meta:"Encyclopedia · People · c. 1177 BCE",why:"Seafaring raiders of the end of the Late Bronze Age; Egyptian records tell of Ramesses III defeating them on land and sea around 1177 BCE."},
    {name:"Late Bronze Age collapse",href:"/encyclopedia/late-bronze-age-collapse",img:"/images/encyclopedia/late-bronze-age-collapse.jpg",meta:"Encyclopedia · Event · c. 1200 BCE",why:"Drought, famine, migrations, unrest and broken trade: the debated causes of a collapse that ended the Hittite state and weakened Egypt."},
    {name:"Philistines",href:"/encyclopedia/philistines",img:"/images/encyclopedia/philistines.jpg",meta:"Encyclopedia · People · 12th–7th centuries BCE",why:"Probably among the Sea Peoples, they settled the coast of Canaan in the 12th century BCE and formed a league of five cities."},
    {name:"Iron Age",href:"/encyclopedia/iron-age",img:"/images/encyclopedia/iron-age.jpg",meta:"Encyclopedia · Idea · from c. 1200 BCE",why:"Iron replaced bronze for tools and weapons from around 1200 BCE, in an age of new kingdoms, hillforts and first written records."}
  ]},
  {slug:"decolonisation",title:"Decolonisation",tagline:"How Asia and Africa won their independence in the thirty years after 1945.",types:["chronicler","timekeeper"],eras:["modern"],intro:"In 1945 most of Africa and much of Asia was still ruled from Europe. Thirty years later the colonial empires were almost gone. Some colonies won independence by negotiation and some by war; the new states met at Bandung to speak with their own voice, while the old powers learned at Suez and in Algeria that they could no longer hold on by force. This path follows that end of empire from the partition of India to the Portuguese revolution of 1974, through its leaders, crises and speeches.",steps:[
    {name:"Decolonisation",href:"/encyclopedia/decolonisation",img:"/images/encyclopedia/decolonisation.jpg",meta:"Encyclopedia · Event",why:"Colonies across Asia and Africa won independence in the decades after the Second World War, ending the British and French empires as global systems."},
    {name:"Partition of India",href:"/encyclopedia/partition-of-india",img:"",meta:"Encyclopedia · Event · 1947",why:"British India became India and Pakistan in August 1947; some fifteen million people crossed the new borders amid communal killing."},
    {name:"Bandung Conference",href:"/encyclopedia/bandung-conference",img:"/images/encyclopedia/bandung-conference.jpg",meta:"Encyclopedia · Event · 1955",why:"In 1955 twenty-nine newly independent and emerging states of Asia and Africa met in Indonesia and condemned colonialism."},
    {name:"Suez Crisis",href:"/encyclopedia/suez-crisis",img:"/images/encyclopedia/suez-crisis.jpg",meta:"Encyclopedia · Event · 1956",why:"Britain, France and Israel invaded Egypt after Nasser nationalised the canal in 1956, and withdrew under American and Soviet pressure."},
    {name:"Kwame Nkrumah",href:"/encyclopedia/kwame-nkrumah",img:"/images/encyclopedia/kwame-nkrumah.jpg",meta:"Encyclopedia · Person · 1909–1972",why:"He led the Gold Coast to independence in 1957 and named the new state Ghana, after the medieval empire."},
    {name:"Wind of Change speech",href:"/encyclopedia/wind-of-change-speech",img:"",meta:"Encyclopedia · Work · 1960",why:"In Cape Town in 1960 Harold Macmillan acknowledged the strength of African national consciousness and signalled that Britain would not resist decolonisation."},
    {name:"Patrice Lumumba",href:"/encyclopedia/patrice-lumumba",img:"/images/encyclopedia/patrice-lumumba.jpg",meta:"Encyclopedia · Person · 1925–1961",why:"The Congo's first prime minister in June 1960, deposed that September and killed in January 1961 with Belgian complicity."},
    {name:"Algerian War",href:"/encyclopedia/algerian-war",img:"/images/encyclopedia/algerian-war.jpg",meta:"Encyclopedia · Event · ended 1962",why:"Eight years of war, from 1954 to 1962, ended French rule in Algeria and brought a political crisis in France itself."},
    {name:"Carnation Revolution",href:"/encyclopedia/carnation-revolution",img:"/images/encyclopedia/carnation-revolution.jpg",meta:"Encyclopedia · Event · 1974",why:"A coup in Lisbon in April 1974, driven partly by the costly colonial wars, brought the Portuguese Empire in Africa to an end."}
  ]},
  {slug:"the-renaissance",title:"The Renaissance",tagline:"Florence, the Medici and the recovery of the ancient world: how a revival of learning remade European art and thought.",types:["thinker","builder"],eras:["earlymodern","medieval"],intro:"From the fourteenth century Italian scholars set out to recover the learning of Greece and Rome, hunting for lost manuscripts and learning Greek from Byzantine teachers. In Florence, a republic of bankers and wool merchants, that revival met money and ambition: patrons paid for new churches, domes, sculpture and painting, and artists studied perspective and the human body as never before. This path follows the Renaissance from Petrarch to the Sistine ceiling, Machiavelli's realism and Erasmus's Greek New Testament, as it spread from Italy across Europe.",steps:[
    {name:"Petrarch",href:"/encyclopedia/petrarch",img:"/images/encyclopedia/petrarch.jpg",meta:"Encyclopedia · Person · 1304–1374",why:"Poet of the Canzoniere, whose search for classical manuscripts made him a founder of Renaissance humanism."},
    {name:"Republic of Florence",href:"/empire/republic-of-florence",img:"/images/encyclopedia/florence-cathedral.jpg",meta:"Profile · 1115 CE – 1532 CE",why:"A republic of bankers and wool merchants whose gold florin became a standard coin of European trade, and the birthplace of the Renaissance."},
    {name:"Manuel Chrysoloras",href:"/encyclopedia/manuel-chrysoloras",img:"/images/encyclopedia/manuel-chrysoloras.jpg",meta:"Encyclopedia · Person · c. 1350–1415",why:"From 1397 this Byzantine scholar taught Greek in Florence, opening classical Greek literature to the Italian humanists."},
    {name:"Filippo Brunelleschi",href:"/encyclopedia/filippo-brunelleschi",img:"/images/encyclopedia/filippo-brunelleschi.jpg",meta:"Encyclopedia · Person · 1377–1446",why:"His dome for Florence Cathedral, built without wooden centring, is still the largest masonry dome in the world; he is also credited with the first demonstration of linear perspective."},
    {name:"Lorenzo de' Medici",href:"/encyclopedia/lorenzo-de-medici",img:"/images/encyclopedia/lorenzo-de-medici.jpg",meta:"Encyclopedia · Person · 1449–1492",why:"Florence's effective ruler from 1469: poet, diplomat and patron of Botticelli and the young Michelangelo."},
    {name:"Leonardo da Vinci",href:"/encyclopedia/leonardo-da-vinci",img:"/images/encyclopedia/leonardo-da-vinci.jpg",meta:"Encyclopedia · Person · 1452–1519",why:"Painter of the Last Supper and the Mona Lisa, whose notebooks studied anatomy, mechanics and nature."},
    {name:"Sistine Chapel",href:"/encyclopedia/sistine-chapel",img:"/images/encyclopedia/sistine-chapel.jpg",meta:"Encyclopedia · Work · 1473–1481",why:"Botticelli and Perugino painted its walls; Michelangelo painted its ceiling between 1508 and 1512 and, later, the Last Judgement."},
    {name:"The Prince",href:"/encyclopedia/the-prince",img:"/images/encyclopedia/the-prince.jpg",meta:"Encyclopedia · Work · 1513",why:"Machiavelli's treatise of 1513 on how new princes win and hold power, written after the Medici's return had cost him his office."},
    {name:"Erasmus",href:"/encyclopedia/erasmus",img:"/images/encyclopedia/erasmus.jpg",meta:"Encyclopedia · Person · 1466–1536",why:"The most famous scholar of the Northern Renaissance, whose Greek New Testament of 1516 and Praise of Folly made him a voice for reform."}
  ]},
  {slug:"the-cold-war",title:"The Cold War",tagline:"Forty years of rivalry between the United States and the Soviet Union, from containment to collapse.",types:["strategist","timekeeper"],eras:["modern"],intro:"After the Second World War the two superpowers, the United States and the Soviet Union, divided Europe and much of the world between them. They never went to war with each other directly; instead they competed through alliances, an arms race, the race into space and proxy wars in Korea, Vietnam, Africa and elsewhere. This path follows the Cold War from the Truman Doctrine of 1947 through the crises of Berlin and Cuba to the reforms that ended it and the breakup of the Soviet Union in 1991.",steps:[
    {name:"Truman Doctrine",href:"/encyclopedia/truman-doctrine",img:"/images/encyclopedia/truman-doctrine.jpg",meta:"Encyclopedia · Idea · 1947",why:"Truman's pledge of March 1947 to support countries under communist pressure, often seen as the start of containment."},
    {name:"Berlin Airlift",href:"/encyclopedia/berlin-airlift",img:"/images/encyclopedia/berlin-airlift.jpg",meta:"Encyclopedia · Event · 1948–1949",why:"When the Soviets blockaded West Berlin in June 1948, Western aircraft flew in food and coal until the blockade was lifted in May 1949."},
    {name:"Korean War",href:"/encyclopedia/korean-war",img:"/images/encyclopedia/korean-war.jpg",meta:"Encyclopedia · Event · 1950–1953",why:"North Korea invaded the South in 1950; a US-led United Nations force and then China's armies joined the war, which ended in an armistice in 1953."},
    {name:"Sputnik 1",href:"/encyclopedia/sputnik-1",img:"/images/encyclopedia/sputnik-1.jpg",meta:"Encyclopedia · Work · 1957",why:"The first artificial satellite, launched in October 1957, shocked the United States and began the space race."},
    {name:"Berlin Wall",href:"/encyclopedia/berlin-wall",img:"/images/encyclopedia/berlin-wall.jpg",meta:"Encyclopedia · Work · 1961–1989",why:"Built from 13 August 1961 to stop East Germans fleeing west, it was the leading symbol of a divided Europe until its opening in 1989."},
    {name:"Cuban Missile Crisis",href:"/encyclopedia/cuban-missile-crisis",img:"/images/encyclopedia/cuban-missile-crisis.jpg",meta:"Encyclopedia · Event · 1962",why:"Thirteen days in October 1962, over Soviet missile sites in Cuba: the closest the Cold War came to nuclear war."},
    {name:"Prague Spring",href:"/encyclopedia/prague-spring",img:"/images/encyclopedia/prague-spring.jpg",meta:"Encyclopedia · Event · 1968",why:"Czechoslovakia's 'socialism with a human face', ended when the Soviet Union and its allies invaded in August 1968."},
    {name:"Mikhail Gorbachev",href:"/encyclopedia/mikhail-gorbachev",img:"/images/encyclopedia/mikhail-gorbachev.jpg",meta:"Encyclopedia · Person · 1931–2022",why:"Glasnost and perestroika at home; abroad he ended the Cold War and allowed the communist regimes of Eastern Europe to fall in 1989."},
    {name:"Dissolution of the Soviet Union",href:"/encyclopedia/dissolution-of-the-soviet-union",img:"",meta:"Encyclopedia · Event · 1991",why:"After a failed coup by hardliners in August 1991 the republics declared independence, and on 26 December the Soviet Union ceased to exist."}
  ]},
  {slug:"ideas-that-shaped-modern-politics",title:"Ideas That Shaped Modern Politics",tagline:"Liberalism, conservatism, nationalism, socialism and fascism, read beside the thinkers who framed them.",types:["thinker","timekeeper"],eras:["modern","earlymodern"],intro:"Most of the political ideologies still argued over today took shape between the late 17th and the early 20th centuries. Liberalism grounded lawful government in the consent of the governed, and conservatism answered the French Revolution with tradition, authority and hierarchy. Nationalism held that each nation should govern itself, socialism and communism called for common ownership, and reformists sought equality through gradual democratic change. Fascism, born in Italy during World War I, exalted the nation above all and drove the Axis powers to war and genocide.",steps:[
    {name:"John Locke",href:"/encyclopedia/john-locke",img:"/images/encyclopedia/john-locke.jpg",meta:"Encyclopedia · Person · 1632–1704",why:"Locke argued that government rests on the consent of the governed and must protect life, liberty and property, and his Two Treatises shaped liberal political thought."},
    {name:"Liberalism",href:"/ideology/liberalism",img:"/images/encyclopedia/john-locke.jpg",meta:"Profile · c. 1690 CE – present",why:"Arising in 17th-century England and the Enlightenment, liberalism was used to justify the Glorious, American and French revolutions, and later split into classical and social forms."},
    {name:"Edmund Burke",href:"/encyclopedia/edmund-burke",img:"/images/encyclopedia/edmund-burke.jpg",meta:"Encyclopedia · Person · 1729–1797",why:"A Whig who backed conciliation with the American colonies, Burke became a founding figure of modern conservatism with his Reflections on the Revolution in France of 1790."},
    {name:"Conservatism",href:"/ideology/conservatism",img:"/images/encyclopedia/edmund-burke.jpg",meta:"Profile · c. 1790 CE – present",why:"Conservatism defends the established institutions of its time, in forms ranging from Disraeli's One Nation Toryism and Bismarck's welfare state to Salazar, Franco and Christian democracy."},
    {name:"Nationalism",href:"/ideology/nationalism",img:"/images/encyclopedia/johann-gottfried-herder.jpg",meta:"Profile · c. 1772 CE – present",why:"Nationalism holds that a nation should govern itself; it drove Italian unification and the independence of Africa and Asia, and is often cited as a cause of both world wars."},
    {name:"The Communist Manifesto",href:"/encyclopedia/the-communist-manifesto",img:"/images/encyclopedia/the-communist-manifesto.jpg",meta:"Encyclopedia · Work · 1848",why:"Published in London in February 1848, the pamphlet of Marx and Engels cast all history as the history of class struggles and predicted a classless society."},
    {name:"Communism",href:"/ideology/communism",img:"/images/encyclopedia/the-communist-manifesto.jpg",meta:"Profile · 1793 CE – present",why:"From the October Revolution of 1917 communist governments spread until more than a third of the world lived under them, marked by one-party rule and the suppression of opposition."},
    {name:"Eduard Bernstein",href:"/encyclopedia/eduard-bernstein",img:"/images/encyclopedia/eduard-bernstein.jpg",meta:"Encyclopedia · Person · 1850–1932",why:"Bernstein's Evolutionary Socialism (1899) disputed Marx's predicted collapse of capitalism and argued for gradual reform, which the SPD condemned but largely followed in practice."},
    {name:"Benito Mussolini",href:"/encyclopedia/benito-mussolini",img:"/images/encyclopedia/benito-mussolini.jpg",meta:"Encyclopedia · Person · 1883–1945",why:"Mussolini founded Fascism and ruled Italy as dictator from 1922 until 1943, invading Ethiopia in 1935 and allying himself with Nazi Germany."},
    {name:"Fascism",href:"/ideology/fascism",img:"/images/encyclopedia/march-on-rome.jpg",meta:"Profile · 1915 CE – present",why:"Fascism sought a totalitarian one-party state; the wars and genocides of the Axis powers, the Holocaust above all, left it almost universally condemned after 1945."}
  ]},
  {slug:"forms-of-government-through-history",title:"Forms of Government through History",tagline:"From chiefs and city-states to parliaments and single parties: how peoples have been governed.",types:["builder","thinker","timekeeper"],eras:["ancient","medieval","earlymodern","modern"],intro:"Peoples have been governed in many ways, and the same forms recur across continents and ages. A chiefdom joined villages under a hereditary chief who ruled through kinship, ritual and tribute; city-states from Sumer to Venice governed themselves and their countryside; Athens let its citizens decide in an assembly, and Rome elected its magistrates. Medieval lords and vassals divided power among landholders, early modern kings claimed it whole, and England's Bill of Rights bound the crown by law. The path ends with parliamentary democracy, born in 18th-century Britain, and the one-party state, which began in Soviet Russia after 1918.",steps:[
    {name:"Chiefdom",href:"/government/chiefdom",img:"/images/encyclopedia/kalaniopuu.jpg",meta:"Profile · c. 5000 BCE – present",why:"A chiefdom rules through kinship, ritual and tribute rather than officials, a standing army or written law, and arose independently from Mesopotamia to Polynesia."},
    {name:"Cahokia",href:"/empire/cahokia",img:"/images/encyclopedia/monks-mound.jpg",meta:"Profile · 1050 CE – 1350 CE",why:"Cahokia, built from about 1050 opposite present-day St Louis, raised Monks Mound, about 30 metres high and the largest prehistoric earthwork in the Americas."},
    {name:"City-state",href:"/government/city-state",img:"/images/encyclopedia/polis.jpg",meta:"Profile · c. 3500 BCE – present",why:"A city-state governs itself and its countryside with its own gods, laws and army, a form found in Sumer, Greece, among the Maya and in medieval Italy."},
    {name:"Athenian democracy",href:"/encyclopedia/athenian-democracy",img:"/images/encyclopedia/athenian-democracy.jpg",meta:"Encyclopedia · Term · c. 594–338 BCE",why:"Athens was governed directly: citizens attended the assembly by right and most officials and large juries were chosen by lot, though only free adult men took part."},
    {name:"Roman Republic",href:"/empire/roman-republic",img:"/images/encyclopedia/roman-senate.jpg",meta:"Profile · 509 BCE – 27 BCE",why:"From 509 to 27 BCE Rome was ruled by elected magistrates, Senate and assemblies, until civil wars from Sulla to Caesar and Octavian ended in monarchy under Augustus."},
    {name:"Feudalism",href:"/government/feudalism",img:"/images/encyclopedia/vassal.jpg",meta:"Profile · c. 800 CE – 1789 CE",why:"Feudalism bound vassals to lords by oaths of homage and fealty in return for fiefs, leaving power divided among landholders until France abolished it in 1789."},
    {name:"Louis XIV",href:"/encyclopedia/louis-xiv",img:"/images/encyclopedia/louis-xiv.jpg",meta:"Encyclopedia · Person · 1638–1715",why:"Louis XIV, King of France from 1643 to 1715, reigned at the height of royal absolutism, while his minister Colbert expanded France's colonies, navy and trading companies."},
    {name:"Bill of Rights 1689",href:"/encyclopedia/bill-of-rights-1689",img:"/images/encyclopedia/bill-of-rights-1689.jpg",meta:"Encyclopedia · Work · 1689",why:"The Bill of Rights 1689 forbade the crown to suspend laws or levy taxes without Parliament's consent, and remains a cornerstone of the British constitution."},
    {name:"Parliamentary democracy",href:"/government/parliamentary-democracy",img:"/images/encyclopedia/westminster-system.jpg",meta:"Profile · c. 1721 CE – present",why:"Between the 1720s and the 1830s real executive power in Britain passed from the monarch to a prime minister and cabinet answerable to the House of Commons."},
    {name:"One-party state",href:"/government/one-party-state",img:"/images/encyclopedia/julius-nyerere.jpg",meta:"Profile · c. 1918 CE – present",why:"The one-party state began in Soviet Russia between 1918 and 1921 and spread to Fascist Italy, Nazi Germany and many new states; most became multi-party after 1989–1991."}
  ]},
  {slug:"abolition-and-the-end-of-slavery",title:"Abolition and the End of Slavery",tagline:"Campaigners, writers and the enslaved themselves, and the laws that ended slavery in the Americas.",types:["chronicler","thinker"],eras:["modern","earlymodern"],intro:"Between 1787 and 1888 legal slavery was ended throughout the Americas. Abolitionism grew from Quaker and evangelical protest into campaigns of petitions, boycotts and public testimony, aimed first at the Atlantic slave trade and then at slavery itself. The enslaved fought for their own freedom throughout: in Saint-Domingue their revolution destroyed slavery and founded Haiti, and in the United States people who had escaped slavery led the campaign against it. The path runs from London's abolition society of 1787 to Brazil's Golden Law, after which freedom rarely brought the formerly enslaved land, compensation or equality.",steps:[
    {name:"Abolitionism",href:"/movement/abolitionism",img:"/images/encyclopedia/zong-massacre.jpg",meta:"Profile · 1787 CE – 1888 CE",why:"Abolitionism grew from Quaker and evangelical protest into the first great campaigns of petitions and boycotts, and between 1787 and 1888 ended legal slavery across the Americas."},
    {name:"Thomas Clarkson",href:"/encyclopedia/thomas-clarkson",img:"/images/encyclopedia/thomas-clarkson.jpg",meta:"Encyclopedia · Person · 1760–1846",why:"Clarkson helped found the Society for Effecting the Abolition of the Slave Trade in 1787 and gathered evidence from sailors and ports for Wilberforce's campaign."},
    {name:"Olaudah Equiano",href:"/encyclopedia/olaudah-equiano",img:"/images/encyclopedia/olaudah-equiano.jpg",meta:"Encyclopedia · Person · c. 1745–1797",why:"Equiano bought his freedom in 1766 and told Granville Sharp of the Zong massacre; his Interesting Narrative of 1789 helped win support for the Slave Trade Act of 1807."},
    {name:"Saint-Domingue",href:"/empire/saint-domingue",img:"/images/encyclopedia/toussaint-louverture.jpg",meta:"Profile · 1665 CE – 1804 CE",why:"France's richest colony took in some 790,000 to 860,000 enslaved Africans, who rose in 1791, saw slavery abolished in 1793 and beat the French army at Vertières in 1803."},
    {name:"Toussaint Louverture",href:"/encyclopedia/toussaint-louverture",img:"/images/encyclopedia/toussaint-louverture.jpg",meta:"Encyclopedia · Person · 1743–1803",why:"A formerly enslaved man, Toussaint led the revolutionary forces and governed the colony until Napoleon's expedition captured him; he died in a French prison in 1803."},
    {name:"William Wilberforce",href:"/encyclopedia/william-wilberforce",img:"/images/encyclopedia/william-wilberforce.jpg",meta:"Encyclopedia · Person · 1759–1833",why:"Wilberforce introduced abolition bills in Parliament from 1789 until the Slave Trade Act passed in 1807, then campaigned for the abolition of slavery itself."},
    {name:"Slavery Abolition Act 1833",href:"/encyclopedia/slavery-abolition-act-1833",img:"/images/encyclopedia/slavery-abolition-act-1833.jpg",meta:"Encyclopedia · Event · 1833",why:"The Act of 1833 abolished slavery in most of the British Empire after an apprenticeship period, and compensated the slave owners, not the enslaved."},
    {name:"Frederick Douglass",href:"/encyclopedia/frederick-douglass",img:"/images/encyclopedia/frederick-douglass.jpg",meta:"Encyclopedia · Person · c. 1818–1895",why:"Douglass escaped slavery in Maryland in 1838; his Narrative of 1845, his newspaper and his speeches drove the campaign against slavery in the United States."},
    {name:"Harriet Tubman",href:"/encyclopedia/harriet-tubman",img:"/images/encyclopedia/harriet-tubman.jpg",meta:"Encyclopedia · Person · c. 1822–1913",why:"After escaping in 1849 Tubman made some thirteen missions back to rescue about seventy people, and in the Civil War guided the Combahee Ferry raid that freed more than 700."},
    {name:"Brazilian Empire",href:"/empire/brazilian-empire",img:"/images/encyclopedia/pedro-ii-of-brazil.jpg",meta:"Profile · 1822 CE – 1889 CE",why:"Coffee grown by enslaved people drove Brazil's wealth; Princess Isabel signed the Lei Áurea in 1888, and the planters' lost support let an army coup end the empire in 1889."}
  ]},
  {slug:"votes-for-women",title:"Votes for Women",tagline:"From Wollstonecraft's Vindication to the Swiss vote: the long campaign for women's suffrage.",types:["chronicler","thinker"],eras:["modern","earlymodern"],intro:"The organised campaign for women's votes is usually dated from the Seneca Falls Convention of 1848, and it won its first national victory in New Zealand in 1893. Suffragists used petitions, conventions, lobbying and marches, and in Britain the militant suffragettes smashed windows, set fires and went on hunger strike. Much of Europe and North America gave women the vote around the First World War, while many women of colour and colonial subjects waited decades longer. This path begins with the feminist argument of the 1790s and follows the campaigners and the laws to Switzerland, where women won the federal vote only in 1971.",steps:[
    {name:"Mary Wollstonecraft",href:"/encyclopedia/mary-wollstonecraft",img:"/images/encyclopedia/mary-wollstonecraft.jpg",meta:"Encyclopedia · Person · 1759–1797",why:"In A Vindication of the Rights of Woman (1792) Wollstonecraft argued that women only appeared inferior because they lacked education, and should be treated as rational beings."},
    {name:"Feminism",href:"/ideology/feminism",img:"/images/encyclopedia/mary-wollstonecraft.jpg",meta:"Profile · 1792 CE – present",why:"Since the late 18th century feminist movements have campaigned for women's right to vote, hold office, work and own property; the suffrage movements were their first wave."},
    {name:"Seneca Falls Convention",href:"/encyclopedia/seneca-falls-convention",img:"/images/encyclopedia/seneca-falls-convention.jpg",meta:"Encyclopedia · Event · 1848",why:"The first women's rights convention, held in July 1848, adopted a Declaration of Sentiments, and its resolution on suffrage passed after Frederick Douglass spoke for it."},
    {name:"Susan B. Anthony",href:"/encyclopedia/susan-b-anthony",img:"/images/encyclopedia/susan-b-anthony.jpg",meta:"Encyclopedia · Person · 1820–1906",why:"Anthony founded the National Woman Suffrage Association with Elizabeth Cady Stanton in 1869, and used her trial for voting in 1872 to argue for women's citizenship."},
    {name:"Kate Sheppard",href:"/encyclopedia/kate-sheppard",img:"/images/encyclopedia/kate-sheppard.jpg",meta:"Encyclopedia · Person · 1848–1934",why:"Sheppard organised three petitions between 1891 and 1893, the last signed by 31,872 women, before New Zealand became the first self-governing country where women could vote."},
    {name:"Women's suffrage movement",href:"/movement/womens-suffrage-movement",img:"/images/encyclopedia/womens-social-and-political-union.jpg",meta:"Profile · 1848 CE – 1971 CE",why:"From 1848 to 1971 suffragists used petitions, conventions, lobbying and marches, and won women the vote and the right to stand for election in most of the world's states."},
    {name:"Emmeline Pankhurst",href:"/encyclopedia/emmeline-pankhurst",img:"/images/encyclopedia/emmeline-pankhurst.jpg",meta:"Encyclopedia · Person · 1858–1928",why:"Pankhurst founded the Women's Social and Political Union in 1903, whose suffragettes turned from processions to window-smashing and arson; she was imprisoned repeatedly."},
    {name:"Representation of the People Act 1918",href:"/encyclopedia/representation-of-the-people-act-1918",img:"/images/encyclopedia/representation-of-the-people-act-1918.jpg",meta:"Encyclopedia · Work · 1918",why:"Passed at the end of the First World War, the Act gave most women over 30 the vote for the first time and nearly tripled the United Kingdom's electorate."},
    {name:"Nineteenth Amendment to the United States Constitution",href:"/encyclopedia/nineteenth-amendment-to-the-united-states-constitution",img:"/images/encyclopedia/nineteenth-amendment-to-the-united-states-constitution.jpg",meta:"Encyclopedia · Work · 1920",why:"Ratified in August 1920, the amendment barred denying citizens the vote on account of sex, though many women of colour remained excluded from voting in practice."},
    {name:"Direct democracy",href:"/government/direct-democracy",img:"/images/encyclopedia/landsgemeinde.jpg",meta:"Profile · 508 BCE – present",why:"Swiss citizens decide by referendum and in open-air assemblies, and only in 1990 did the Federal Supreme Court order Appenzell Innerrhoden to admit women to its Landsgemeinde."}
  ]},
  {slug:"the-living-peoples",title:"The Living Peoples",tagline:"Ten Indigenous peoples alive today: their deep pasts, colonial dispossession and recovery of rights.",types:["chronicler","timekeeper"],eras:["modern","earlymodern","medieval"],intro:"Some peoples whose histories reach back thousands of years are living communities today. The ancestors of Aboriginal Australians reached Sahul 50,000 to 65,000 years ago, the Māori settled New Zealand around 1300, and the Lakota made the Black Hills their home by the 1770s. Most of these peoples met colonial rule, with killings, epidemics, forced removal and bans on their languages, and many have since won back land and recognition, from the Mabo Case in Australia to Nunavut and the Sámi parliaments. This path visits ten of them, in the order their histories begin.",steps:[
    {name:"Aboriginal Australians",href:"/culture/aboriginal-australians",img:"/images/encyclopedia/aboriginal-tasmanians.jpg",meta:"Profile · c. 63000 BCE – present",why:"Their ancestors reached Sahul 50,000 to 65,000 years ago; more than 400 peoples, each with its own language and Country, survived British colonisation from 1788."},
    {name:"San people",href:"/culture/san-people",img:"/images/encyclopedia/san-people.jpg",meta:"Profile · c. 8000 BCE – present",why:"Descendants of hunter-gatherers who 10,000 years ago were spread from Tanzania to Cape Agulhas, the San faced a Dutch East India Company policy of eradication from 1777."},
    {name:"Sámi",href:"/culture/sami",img:"",meta:"Profile · c. 1000 BCE – present",why:"In the far north of Europe since the Bronze Age or early Iron Age, the Sámi bore centuries of assimilation and have elected parliaments of their own since Finland’s of 1973."},
    {name:"Khoekhoe",href:"/culture/khoekhoe",img:"/images/encyclopedia/transhumance.jpg",meta:"Profile · c. 400 BCE – present",why:"Herders of sheep and cattle since about the turn of the era, the Khoekhoe killed Francisco de Almeida at Salt River in 1510 and later lost their land to colonial conquest."},
    {name:"Tuareg",href:"/culture/tuareg",img:"/images/encyclopedia/tuareg.jpg",meta:"Profile · c. 400 CE – present",why:"Amazigh herders and caravan traders of the Sahara with a founding queen, Tin Hinan, they resisted French conquest from 1881 to 1920 and saw their homeland divided among five states."},
    {name:"Inuit",href:"/culture/inuit",img:"",meta:"Profile · c. 1000 CE – present",why:"Descendants of the Thule people who spread east from the Bering Strait around 1000 CE, the Inuit survived forced relocation and won the land claim that created Nunavut in 1999."},
    {name:"Ainu",href:"/culture/ainu",img:"/images/encyclopedia/ainu.jpg",meta:"Profile · c. 1200 CE – present",why:"The Indigenous people of Hokkaido, Sakhalin and the Kurils, whose culture took shape from the 13th century, lost land and language to Japanese colonisation and won legal recognition in 2019."},
    {name:"Kalinago",href:"/culture/kalinago",img:"/images/encyclopedia/garifuna.jpg",meta:"Profile · c. 1200 CE – present",why:"The Island Caribs kept their independence in the Lesser Antilles against Spain, France and England, and live today chiefly in the Kalinago Territory of Dominica."},
    {name:"Māori",href:"/culture/maori",img:"/images/encyclopedia/treaty-of-waitangi.jpg",meta:"Profile · c. 1300 CE – present",why:"Sailing from eastern Polynesia in waka, the Māori settled New Zealand around 1250–1350 and built a culture of iwi, pā and carved meeting houses before the Treaty of Waitangi of 1840."},
    {name:"Lakota people",href:"/culture/lakota-people",img:"/images/encyclopedia/lakota-people.jpg",meta:"Profile · c. 1600 CE – present",why:"Bison hunters of the northern Plains who with the Cheyenne defeated Custer at the Little Bighorn in 1876, they still refuse the 1980 Supreme Court award for the Black Hills."}
  ]},
  {slug:"before-the-state",title:"Before the State",tagline:"Cultures known from their remains, from the first settled hunters to Iron Age Europe’s walled towns.",types:["timekeeper","builder"],eras:["ancient"],intro:"Long before writing and states, people lived in ways known only from what they left in the ground. The cultures on this path are archaeologists’ names for such remains: pottery, stone points, graves, houses and metalwork. They show hunter-gatherers making pottery in Japan around 14,500 BCE and living in permanent villages in the Levant, farmers building settlements of up to three thousand structures, herders crossing the steppe in wagons, and Iron Age communities growing rich on salt and trade. The path runs from the Jōmon to the La Tène culture, whose walled towns became Roman cities.",steps:[
    {name:"Jōmon culture",href:"/culture/jomon-culture",img:"",meta:"Profile · c. 14000 BCE – c. 300 BCE",why:"For some 14,000 years the people of the Japanese archipelago lived mainly by hunting, gathering and fishing, and they made the world’s oldest known pottery around 14,500 BCE."},
    {name:"Natufians",href:"/culture/natufians",img:"/images/encyclopedia/mount-carmel.jpg",meta:"Profile · c. 13000 BCE – c. 9500 BCE",why:"Hunter-gatherers of the Levant who lived in settled villages, some with round stone houses and the first known food stores, before farming began."},
    {name:"Clovis culture",href:"/culture/clovis-culture",img:"",meta:"Profile · c. 11100 BCE – c. 10800 BCE",why:"The earliest widely recognised culture of North America, mobile hunters of mammoth and bison with fluted stone points, though not the first people of the Americas."},
    {name:"Mehrgarh culture",href:"/culture/mehrgarh-culture",img:"",meta:"Profile · c. 7000 BCE – c. 2500 BCE",why:"Near the Bolan Pass, one of the earliest known places in South Asia where people farmed barley and wheat and herded sheep, goats and cattle."},
    {name:"Ubaid culture",href:"/culture/ubaid-culture",img:"/images/encyclopedia/ubaid-period.jpg",meta:"Profile · c. 6500 BCE – c. 3800 BCE",why:"It left the earliest known settlements on the southern Mesopotamian plain and the first temples there, but still no real cities: those came in the Uruk period."},
    {name:"Cucuteni–Trypillia culture",href:"/culture/cucuteni-trypillia-culture",img:"",meta:"Profile · c. 5050 BCE – c. 2950 BCE",why:"Farmers between the Carpathians and the Dnieper who built some of the largest settlements in Eurasia, and burned and rebuilt them every 60 to 80 years."},
    {name:"Yamnaya culture",href:"/culture/yamnaya-culture",img:"/images/encyclopedia/kurgan.jpg",meta:"Profile · c. 3300 BCE – c. 2600 BCE",why:"Herders of the Pontic–Caspian steppe who moved in carts and wagons, buried their dead under mounds and are widely held to have spoken a stage of Proto-Indo-European."},
    {name:"Bell Beaker culture",href:"/culture/bell-beaker-culture",img:"/images/encyclopedia/knowth.jpg",meta:"Profile · c. 2800 BCE – c. 1800 BCE",why:"Named after a drinking vessel shaped like an upside-down bell, it spread copper, gold and bronze working along sea and river routes from Portugal to Ireland and Hungary."},
    {name:"Hallstatt culture",href:"/culture/hallstatt-culture",img:"/images/encyclopedia/hochdorf-chieftains-grave.jpg",meta:"Profile · c. 1200 BCE – c. 450 BCE",why:"The salt mines of Hallstatt made its community unusually rich, and late in the period princely seats such as the Heuneburg traded with the Greek and Etruscan world."},
    {name:"La Tène culture",href:"/culture/la-tene-culture",img:"/images/encyclopedia/battersea-shield.jpg",meta:"Profile · c. 450 BCE – c. 50 BCE",why:"The successor of Hallstatt from about 450 BCE, known for its curving metalwork and its walled oppida, many of which, such as Lutetia, became Roman cities."}
  ]},
  {slug:"the-ancient-gods",title:"The Ancient Gods",tagline:"The gods of the ancient world, their temples, priests and myths, and how their worship ended.",types:["thinker","chronicler"],eras:["ancient","medieval"],intro:"For thousands of years the peoples of the Near East and Europe honoured many gods. Every Mesopotamian city had a patron god living in its temple, Egyptian kings upheld maat, the order of the world, Greek cities held festivals and games for the Olympians, and Romans exchanged prayer and sacrifice with the gods on the principle of “I give that you might give”. Much of what is known comes from tablets, inscriptions and texts written down later by Christians. This path follows these religions from the invention of writing in Mesopotamia to the last Slavic holy places of the 14th century.",steps:[
    {name:"Mesopotamian religion",href:"/religion/mesopotamian-religion",img:"/images/encyclopedia/inanna.jpg",meta:"Profile · c. 3500 BCE – c. 500 CE",why:"Attested from the invention of writing around 3500 BCE, it gave every city a patron god, Marduk at Babylon and Ashur at Assur, served in a temple run as a household."},
    {name:"Epic of Gilgamesh",href:"/encyclopedia/epic-of-gilgamesh",img:"/images/encyclopedia/epic-of-gilgamesh.jpg",meta:"Encyclopedia · Work",why:"The poem of the king of Uruk and his search for immortality, one of the oldest surviving works of literature, best known from Ashurbanipal’s library at Nineveh."},
    {name:"Ancient Egyptian religion",href:"/religion/ancient-egyptian-religion",img:"/images/encyclopedia/karnak.jpg",meta:"Profile · c. 3100 BCE – c. 537 CE",why:"For more than three thousand years Egypt worshipped Ra, Osiris, Isis and Amun to uphold maat, and its hope of eternal life inspired the pyramids and mummification."},
    {name:"Canaanite religion",href:"/religion/canaanite-religion",img:"/images/encyclopedia/asherah.jpg",meta:"Profile · c. 3000 BCE – c. 400 CE",why:"Its pantheon of El, Asherah and the storm god Baal is known chiefly from the tablets of Ugarit, and Phoenician settlers carried it west as the Punic religion."},
    {name:"Ancient Greek religion",href:"/religion/ancient-greek-religion",img:"/images/encyclopedia/paestum.jpg",meta:"Profile · c. 1400 BCE – c. 500 CE",why:"With no sacred book and no single priesthood, the Greeks honoured Zeus and the Olympians through sacrifice, festivals, oracles and games such as the Olympics."},
    {name:"Celtic religion",href:"/religion/celtic-religion",img:"/images/encyclopedia/lugus.jpg",meta:"Profile · c. 550 BCE – c. 600 CE",why:"Known from archaeology, often hostile Greek and Roman writers and medieval Irish and Welsh tales, it had druids, sacred groves and over two hundred named deities."},
    {name:"Roman religion",href:"/religion/roman-religion",img:"/images/encyclopedia/numa-pompilius.jpg",meta:"Profile · c. 509 BCE – 391 CE",why:"A religion of correct practice rather than belief, in which prayer, vow and sacrifice were exchanged with the gods on the principle of do ut des, “I give that you might give”."},
    {name:"Theodosius I",href:"/encyclopedia/theodosius-i",img:"/images/encyclopedia/theodosius-i.jpg",meta:"Encyclopedia · Person · d. 395 CE",why:"The emperor who made Nicene Christianity the official religion of the Roman state, and the last to rule both halves of the empire before its permanent division."},
    {name:"Norse religion",href:"/religion/norse-religion",img:"/images/encyclopedia/oseberg-ship.jpg",meta:"Profile · c. 500 CE – c. 1100 CE",why:"The religion of Odin, Thor, Freyr and Freyja, displaced by Christianity between the 10th and 12th centuries and known mainly from Icelandic texts of the 13th."},
    {name:"Slavic paganism",href:"/religion/slavic-paganism",img:"/images/encyclopedia/svantevit.jpg",meta:"Profile · c. 500 CE – c. 1331 CE",why:"The faith of the thunder god Perun and many-headed idols, whose rulers turned Christian between 863 and 988 while the old rites lived on in a “double faith”."}
  ]},
  {slug:"faiths-of-the-persian-world",title:"Faiths of the Persian World",tagline:"Zarathustra’s faith, the Persian empires that kept it, and the religions that grew around them.",types:["thinker","chronicler"],eras:["ancient","medieval","modern"],intro:"Iran was the home of one of the world’s oldest revealed religions. Zarathustra taught a struggle between truth and the lie under the Wise Lord, Ahura Mazda, and his faith was the religion of the Achaemenid kings and the state religion of the Parthian and Sasanian empires. Under the Sasanians the prophet Mani founded a religion of light that spread from Roman North Africa to China. After the Arab conquest Zoroastrians became a minority, and some settled in Gujarat as the Parsis. This path follows these faiths and their neighbours, from the Roman cult of Mithras to the Yazidis of Lalish and the Bahá’í Faith, born in 19th-century Iran.",steps:[
    {name:"Zoroaster",href:"/encyclopedia/zoroaster",img:"",meta:"Encyclopedia · Person · c. 1200–1000 BCE (disputed)",why:"The prophet whose hymns, the Gathas, stand at the origin of Zoroastrianism; his dates are disputed by a thousand years, most scholars favouring the late second millennium BCE."},
    {name:"Zoroastrianism",href:"/religion/zoroastrianism",img:"/images/encyclopedia/fire-temple.jpg",meta:"Profile · c. 1200 BCE – present",why:"Faith of the Achaemenid kings and state religion of the Parthians and Sasanians, whose ideas of judgement, heaven and hell may have influenced Judaism, Christianity and Islam."},
    {name:"Ahura Mazda",href:"/encyclopedia/ahura-mazda",img:"/images/encyclopedia/ahura-mazda.jpg",meta:"Encyclopedia · Idea",why:"The Wise Lord, first notably invoked in the Behistun Inscription of Darius the Great and later named in royal inscriptions in a triad with Mithra and Anahita."},
    {name:"Mithra",href:"/encyclopedia/mithra",img:"/images/encyclopedia/mithra.jpg",meta:"Encyclopedia · Idea",why:"An Indo-Iranian god of covenant, truth and light, venerated in the Avesta and shown on Kushan coins, distinct from, though related to, the Mithras of Rome."},
    {name:"Mithraism",href:"/religion/mithraism",img:"/images/encyclopedia/mithra.jpg",meta:"Profile · c. 80 CE – c. 400 CE",why:"A Roman mystery cult of soldiers and merchants who met in cave-like temples; Cumont saw it as the Roman form of Persian religion, a model scholars have generally rejected since the 1970s."},
    {name:"Sasanian Empire",href:"/empire/sasanian-empire",img:"/images/encyclopedia/ardashir-i.jpg",meta:"Profile · 224 CE – 651 CE",why:"A centralised Zoroastrian monarchy that ruled Iran and Mesopotamia from 224 to 651 and was Rome’s great rival for four centuries, until the Arab conquests ended it."},
    {name:"Manichaeism",href:"/religion/manichaeism",img:"/images/encyclopedia/bogu-qaghan.jpg",meta:"Profile · c. 240 CE – c. 1600 CE",why:"Founded by the prophet Mani in Sasanian Mesopotamia about 240, it taught a struggle of light and darkness and spread from Roman North Africa to China."},
    {name:"Parsis",href:"/encyclopedia/parsis",img:"/images/encyclopedia/parsis.jpg",meta:"Encyclopedia · People",why:"Descendants of Zoroastrians who left Iran after the Arab conquest, this community of western India preserved the old state faith of the Sasanian Empire."},
    {name:"Yazidism",href:"/religion/yazidism",img:"/images/encyclopedia/yazidis.jpg",meta:"Profile · c. 1100 CE – present",why:"Given its lasting form by Sheikh Adi at Lalish, the faith of the Peacock Angel remembers 74 campaigns of destruction, among them the genocide at Sinjar in 2014."},
    {name:"Bahá'í Faith",href:"/religion/bahai-faith",img:"/images/encyclopedia/haifa.jpg",meta:"Profile · 1844 CE – present",why:"Heralded by the Báb in Shiraz in 1844 and founded by Bahá’u’lláh, it teaches the oneness of God, of religion and of humanity, and has been persecuted in Iran from its beginnings."}
  ]},
  {slug:"the-ancient-near-east",title:"The Ancient Near East",tagline:"From the city-states of Sumer to Persia: two thousand years of Near Eastern kingdoms and empires.",types:["strategist","builder","timekeeper"],eras:["ancient"],intro:"Some of the oldest known law codes and what is widely regarded as the first empire arose in Mesopotamia and the lands around it, from southwestern Iran to Anatolia and the Lebanese coast. The path starts in Lagash, a Sumerian city-state, and follows the powers that rose over the region in turn: Akkad, the Third Dynasty of Ur, Elam, Babylon, the Hittites and Assyria. Urartu in the mountains and the Phoenician cities on the coast lived beside them, and the Achaemenid Persians, who entered Babylon in 539 BCE, gathered most of these lands into one empire.",steps:[
    {name:"Lagash",href:"/empire/lagash",img:"/images/encyclopedia/gudea.jpg",meta:"Profile · 2500 BCE – 2110 BCE",why:"A Sumerian city-state whose Stele of the Vultures records Eannatum's victory over Umma around 2450 BCE, and whose ruler Urukagina made reforms that may be the first legal code."},
    {name:"Akkadian Empire",href:"/empire/akkadian-empire",img:"/images/encyclopedia/victory-stele-of-naram-sin.jpg",meta:"Profile · 2334 BCE – 2154 BCE",why:"Sargon of Akkad brought the city-states of Sumer and Akkad under one ruler around 2334 BCE, in what is widely regarded as the world's first empire."},
    {name:"Neo-Sumerian Empire",href:"/empire/neo-sumerian-empire",img:"/images/encyclopedia/ziggurat-of-ur.jpg",meta:"Profile · 2112 BCE – 2004 BCE",why:"After the Akkadian collapse the Third Dynasty of Ur revived Sumerian rule, kept tens of thousands of tablets and issued the oldest law code that survives."},
    {name:"Elamite Confederation",href:"/empire/elamite-confederation",img:"/images/encyclopedia/chogha-zanbil.jpg",meta:"Profile · 2700 BCE – 539 BCE",why:"From Susa and Anshan in southwestern Iran, Elam sacked Ur around 2004 BCE, carried off its last king, Ibbi-Sin, and later overthrew the Kassite dynasty of Babylon."},
    {name:"Babylonian Empire",href:"/empire/babylonian-empire",img:"/images/encyclopedia/hammurabi.jpg",meta:"Profile · 1894 BCE – 1595 BCE",why:"Under Hammurabi a small Amorite city-state mastered Mesopotamia in barely a decade, and his Code of 282 laws is the fullest to survive from the ancient Near East."},
    {name:"Hittite Empire",href:"/empire/hittite-empire",img:"/images/encyclopedia/hattusa.jpg",meta:"Profile · 1650 BCE – 1178 BCE",why:"Ruled from Hattusa in Anatolia, the Hittites raided Babylon around 1595 BCE, fought Egypt at Kadesh in 1274 BCE and later concluded a peace treaty with Ramesses II."},
    {name:"Assyrian Empire",href:"/empire/assyrian-empire",img:"/images/encyclopedia/nimrud.jpg",meta:"Profile · 2025 BCE – 609 BCE",why:"From the city of Assur, Assyria grew into the largest empire yet seen, reaching Egypt in 671 BCE, until Medes and Babylonians destroyed Nineveh in 612 BCE."},
    {name:"Kingdom of Urartu",href:"/empire/kingdom-of-urartu",img:"/images/encyclopedia/van-fortress.jpg",meta:"Profile · 860 BCE – 590 BCE",why:"Assyria's great northern rival, a mountain kingdom around Lake Van whose kings built rock fortresses and canals; Argishti I founded Erebuni, the origin of Yerevan, in 782 BCE."},
    {name:"Phoenicians",href:"/culture/phoenicians",img:"/images/encyclopedia/tennes.jpg",meta:"Profile · c. 1200 BCE – 332 BCE",why:"Rival city-states of the Lebanese coast such as Tyre, Sidon and Byblos, which sold cedar and purple cloth and whose ships formed the core of the Persian navy after 539 BCE."},
    {name:"Achaemenid Empire",href:"/empire/achaemenid-empire",img:"/images/encyclopedia/persepolis.jpg",meta:"Profile · 559 BCE – 330 BCE",why:"Cyrus the Great entered Babylon in 539 BCE, and the empire he built stretched from the Indus to the Aegean and the Nile until Alexander the Great conquered it."}
  ]},
  {slug:"languages-and-their-peoples",title:"Languages and Their Peoples",tagline:"Ten languages and the peoples, cities and empires that spoke, wrote and carried them.",types:["thinker","chronicler","timekeeper"],eras:["ancient","medieval"],intro:"A language travels with the people who speak it and the states that use it. This path follows ten of them, roughly in order of age, from Sumerian, first written at Uruk around 3200 BCE, to Swahili, which grew in the merchant towns of the East African coast. Some, such as Sumerian, Latin and Ge'ez, outlived their speakers as written languages of learning, law or worship. Others, such as Arabic, Nahuatl and Swahili, became common languages of faith, empire or trade far beyond the lands where they began.",steps:[
    {name:"Sumerian",href:"/language/sumerian",img:"/images/encyclopedia/instructions-of-shuruppak.jpg",meta:"Profile · c. 3200 BCE – c. 80 CE",why:"The language of the city-states of southern Mesopotamia, whose speakers developed cuneiform around 3200 BCE; it stayed a language of learning long after it ceased to be spoken."},
    {name:"Akkadian",href:"/language/akkadian",img:"/images/encyclopedia/epic-of-gilgamesh.jpg",meta:"Profile · c. 2500 BCE – c. 80 CE",why:"The oldest recorded Semitic language, spoken in the empires of Akkad, Babylon and Assyria, and in the Amarna letters the language of diplomacy between Egypt and its neighbours."},
    {name:"Sanskrit",href:"/language/sanskrit",img:"/images/encyclopedia/mahabharata.jpg",meta:"Profile · c. 1500 BCE – present",why:"First known from the hymns of the Rigveda, composed in the north-west of the subcontinent around 1500–1200 BCE, and codified by Panini in some four thousand rules."},
    {name:"Classical Chinese",href:"/language/classical-chinese",img:"/images/encyclopedia/records-of-the-grand-historian.jpg",meta:"Profile · c. 1250 BCE – c. 1920 CE",why:"The written language of Confucius and the historians of ancient China, rooted in Shang oracle bones and used for government in Korea, Japan and Vietnam."},
    {name:"Latin",href:"/language/latin",img:"/images/encyclopedia/roman-forum.jpg",meta:"Profile · c. 600 BCE – present",why:"The language of Latium and Rome, which spread with Roman power and changed region by region into Spanish, Portuguese, French, Italian and Romanian."},
    {name:"Arabic",href:"/language/arabic",img:"/images/encyclopedia/house-of-wisdom.jpg",meta:"Profile · c. 100 BCE – present",why:"First recorded in inscriptions of the Arabian peninsula and its desert borderlands, it became a world language with the Qur'an and the conquests of the 7th century."},
    {name:"Ge'ez",href:"/language/geez",img:"/images/encyclopedia/kebra-nagast.jpg",meta:"Profile · c. 300 CE – present",why:"The language of the Kingdom of Aksum, carved on stone from the 4th century, and still the liturgical language of the Ethiopian and Eritrean churches and the Beta Israel."},
    {name:"Old English",href:"/language/old-english",img:"/images/encyclopedia/beowulf.jpg",meta:"Profile · c. 450 CE – c. 1150 CE",why:"Grown from the dialects of the Angles, Saxons and Jutes who settled in Britain, it became a language of government under Alfred the Great until the Norman Conquest."},
    {name:"Nahuatl",href:"/language/nahuatl",img:"/images/encyclopedia/codex-mendoza.jpg",meta:"Profile · c. 500 CE – present",why:"The language of the Aztecs and of trade and empire across much of Mesoamerica, written after the Spanish conquest in the Latin alphabet, as in the Florentine Codex."},
    {name:"Swahili",href:"/language/swahili",img:"/images/encyclopedia/kilwa-kisiwani.jpg",meta:"Profile · c. 800 CE – present",why:"The Bantu speech of the East African merchant towns, rich in Arabic words from Indian Ocean trade, which caravans carried inland from Zanzibar in the 19th century."}
  ]},
  {slug:"empires-of-the-sea",title:"Empires of the Sea",tagline:"States whose power rested on fleets, ports and sea lanes, from Carthage to the British Empire.",types:["navigator","strategist"],eras:["ancient","medieval","earlymodern","modern"],intro:"A thalassocracy is a state whose power rests on control of the sea, its trade routes and its ports rather than on large land territories. This path follows such powers from the ancient Mediterranean to the oceans of the modern world: Carthage and Athens, Srivijaya on the Strait of Malacca and the Chola navy that raided it, Venice on its lagoon, and the Portuguese, Dutch and British, who carried that kind of power across the oceans. Most were in the end worn down by rivals at sea or by powers on land.",steps:[
    {name:"Thalassocracy",href:"/encyclopedia/thalassocracy",img:"/images/encyclopedia/thalassocracy.jpg",meta:"Encyclopedia · Institution",why:"The term for a state built on the sea rather than on land, which needed less bureaucracy than a territorial empire; Srivijaya is the classic example."},
    {name:"Punic Empire",href:"/empire/punic-empire",img:"/images/encyclopedia/hannibal.jpg",meta:"Profile · 814 BCE – 146 BCE",why:"A Phoenician colony of Tyre in Tunisia that built a trading empire across the western Mediterranean, until three Punic Wars stripped it of Sicily, Spain and its navy."},
    {name:"Battle of Salamis",href:"/encyclopedia/battle-of-salamis",img:"/images/encyclopedia/battle-of-salamis.jpg",meta:"Encyclopedia · Event · 480 BCE",why:"In 480 BCE the allied Greek fleet, led by Athens under Themistocles, defeated the larger fleet of Xerxes I in the straits off Attica, and Xerxes withdrew to Asia."},
    {name:"Athens",href:"/empire/athens",img:"/images/encyclopedia/parthenon.jpg",meta:"Profile · 900 BCE – 86 BCE",why:"After Salamis the city led the Delian League, which it turned into a tribute-paying empire in the Aegean, until its defeat by Sparta in 404 BCE."},
    {name:"Srivijaya Empire",href:"/empire/srivijaya-empire",img:"/images/encyclopedia/sailendra-dynasty.jpg",meta:"Profile · 650 CE – 1377 CE",why:"From Palembang in Sumatra it ruled the Strait of Malacca from the 7th to the 13th century, growing rich by taxing the shipping between China and India."},
    {name:"Chola Empire",href:"/encyclopedia/chola-empire",img:"/images/encyclopedia/chola-empire.jpg",meta:"Encyclopedia · State",why:"A Tamil dynasty of southern India that built a powerful navy, and whose raids on Srivijaya's ports in the 11th century weakened its hold on maritime trade."},
    {name:"Republic of Venice",href:"/empire/republic-of-venice",img:"/images/encyclopedia/venice.jpg",meta:"Profile · 697 CE – 1797 CE",why:"A merchant republic on the lagoon whose fleets and colonies, from Dalmatia to Crete and Cyprus, made it the main link between Latin Europe and the East."},
    {name:"Portuguese Empire",href:"/empire/portuguese-empire",img:"/images/encyclopedia/john-i-of-portugal.jpg",meta:"Profile · 1415 CE – 1975 CE",why:"From Ceuta in 1415 a kingdom of perhaps a million people built the first sea-borne trading empire, opening the sea route to India with Vasco da Gama in 1498."},
    {name:"Dutch Republic",href:"/empire/dutch-republic",img:"/images/encyclopedia/amsterdam.jpg",meta:"Profile · 1581 CE – 1795 CE",why:"Its Baltic trade, its East India Company, founded in 1602, and the Amsterdam bank made it Europe's leading commercial power in the 17th century."},
    {name:"British Empire",href:"/empire/british-empire",img:"/images/encyclopedia/slavery-abolition-act-1833.jpg",meta:"Profile · 1583 CE – 1997 CE",why:"The Royal Navy's victory at Trafalgar in 1805 secured a century of naval supremacy for the largest empire in history, which dissolved within decades after 1947."}
  ]},
  {slug:"the-reformation-and-its-wars",title:"The Reformation and Its Wars",tagline:"How Luther's protest of 1517 split Western Christianity and opened a century of religious wars.",types:["thinker","strategist"],eras:["earlymodern"],intro:"In 1517 Martin Luther wrote his Ninety-five Theses against the sale of indulgences, and Western Christianity split into Lutheran, Reformed, Anglican and Anabaptist churches. Taken up or resisted by princes and cities, the new faiths became bound up with politics and war. This path follows the reformers, the Catholic answer of the Council of Trent, the settlements of Augsburg and Nantes and the wars around them, from the German Peasants' War to the Thirty Years' War, which the Peace of Westphalia ended in 1648.",steps:[
    {name:"Protestant Reformation",href:"/movement/protestant-reformation",img:"/images/encyclopedia/martin-luther.jpg",meta:"Profile · 1517 CE – 1648 CE",why:"Begun by Luther's protest against indulgences in 1517, it taught salvation by grace through faith alone and broke the unity of Western Christianity."},
    {name:"Martin Luther",href:"/encyclopedia/martin-luther",img:"/images/encyclopedia/martin-luther.jpg",meta:"Encyclopedia · Person · 1483–1546",why:"The German monk whose Ninety-five Theses began the Reformation, who refused to recant before Charles V at Worms in 1521 and translated the Bible into German."},
    {name:"German Peasants' War",href:"/encyclopedia/german-peasants-war",img:"/images/encyclopedia/german-peasants-war.jpg",meta:"Encyclopedia · Event · 1524–1525",why:"Partly inspired by the Reformation, peasants and townspeople rose in 1524–1525 demanding an end to serfdom; the princes' armies killed perhaps 100,000 people."},
    {name:"John Calvin",href:"/encyclopedia/john-calvin",img:"/images/encyclopedia/john-calvin.jpg",meta:"Encyclopedia · Person · 1509–1564",why:"The French reformer whose Institutes became a founding text of Reformed Protestantism, and whose Geneva became a model and training centre for Reformed churches."},
    {name:"Counter-Reformation",href:"/movement/counter-reformation",img:"/images/encyclopedia/counter-reformation.jpg",meta:"Profile · 1545 CE – 1648 CE",why:"The Catholic answer: the Council of Trent (1545–1563) restated doctrine and reformed the clergy, while the Jesuits carried missions to the Americas and Asia."},
    {name:"Holy Roman Empire",href:"/empire/holy-roman-empire",img:"/images/encyclopedia/frederick-barbarossa.jpg",meta:"Profile · 800 CE – 1806 CE",why:"Its fragmentation let the Reformation survive, and the Peace of Augsburg of 1555 let each ruler choose Catholicism or Lutheranism for his lands."},
    {name:"St. Bartholomew's Day Massacre",href:"/encyclopedia/st-bartholomews-day-massacre",img:"/images/encyclopedia/st-bartholomews-day-massacre.jpg",meta:"Encyclopedia · Event · 1572",why:"The killing of Huguenots in Paris and other French cities in 1572, during the French Wars of Religion, a year before Poland-Lithuania made religious tolerance law."},
    {name:"Edict of Nantes",href:"/encyclopedia/edict-of-nantes",img:"/images/encyclopedia/edict-of-nantes.jpg",meta:"Encyclopedia · Event · 1598",why:"Henry IV ended the French Wars of Religion in 1598 by granting the Huguenots freedom of conscience and fortified towns; Louis XIV revoked it in 1685."},
    {name:"Thirty Years' War",href:"/encyclopedia/thirty-years-war",img:"/images/encyclopedia/thirty-years-war.jpg",meta:"Encyclopedia · Event · 1618–1648",why:"Beginning in 1618 as a religious struggle within the Holy Roman Empire, it widened into a contest among the major European powers and devastated much of Germany."},
    {name:"Peace of Westphalia",href:"/encyclopedia/peace-of-westphalia",img:"/images/encyclopedia/peace-of-westphalia.jpg",meta:"Encyclopedia · Event · 1648",why:"The treaties of 1648 that ended the war, confirmed the princes' power over religion in their lands, recognised Dutch independence and shaped the idea of territorial sovereignty."}
  ]},
  {slug:"mesoamerica-olmecs-to-aztecs",title:"Mesoamerica, Olmecs to Aztecs",tagline:"From the Olmec heartland to Tenochtitlan's fall: the cities and states of Mexico and Central America.",types:["builder","strategist"],eras:["ancient","medieval","earlymodern"],intro:"From about 1200 BCE, when the Olmecs built San Lorenzo on Mexico's Gulf Coast, to the fall of Tenochtitlan in 1521, the peoples of Mesoamerica raised cities, carved monuments to their rulers and fought for tribute. Olmec images of rulers and gods helped shape the art of later peoples such as the Maya, and Teotihuacan's influence reached as far as the Maya cities of Tikal and Copán. The Maya never formed a single state, and after the southern kingdoms emptied, Chichén Itzá led the north, while the Aztecs looked back to the Toltecs of Tula. The last stops show the Aztec Triple Alliance and two neighbours that held out against it, the Purépecha and Tlaxcala.",steps:[
    {name:"Olmecs",href:"/culture/olmecs",img:"/images/encyclopedia/olmec-colossal-heads.jpg",meta:"Profile · c. 1200 BCE – c. 400 BCE",why:"The Olmecs built the first great centres of Mesoamerica, San Lorenzo and then La Venta, in the lowlands of Mexico's Gulf Coast between about 1200 and 400 BCE."},
    {name:"Olmec colossal heads",href:"/encyclopedia/olmec-colossal-heads",img:"/images/encyclopedia/olmec-colossal-heads.jpg",meta:"Encyclopedia · Work",why:"Seventeen basalt heads up to 3.4 metres high, thought to be portraits of rulers, carved from stone brought from the Sierra de los Tuxtlas by means still unknown."},
    {name:"Maya civilisation",href:"/culture/maya-civilisation",img:"/images/encyclopedia/temple-of-the-inscriptions.jpg",meta:"Profile · c. 2000 BCE – 1697 CE",why:"The Maya built hundreds of cities but never a single state, and their scribes created the most complete writing system of the ancient Americas."},
    {name:"Teotihuacan",href:"/empire/teotihuacan",img:"/images/encyclopedia/pyramid-of-the-sun.jpg",meta:"Profile · 100 BCE – 550 CE",why:"A planned city of perhaps 100,000 people in the Valley of Mexico, whose pyramids and architecture influenced Mesoamerica as far as the Maya cities of Tikal and Copán."},
    {name:"Palenque",href:"/encyclopedia/palenque",img:"/images/encyclopedia/palenque.jpg",meta:"Encyclopedia · Place · c. 226 BCE–c. 799",why:"Sacked by Calakmul in 599 and 611, this Maya city was rebuilt under K'inich Janaab' Pakal, whose tomb was found in the Temple of the Inscriptions in 1952."},
    {name:"Chichen Itza",href:"/encyclopedia/chichen-itza",img:"/images/encyclopedia/chichen-itza.jpg",meta:"Encyclopedia · Place · c. 600–1100",why:"In the 10th century this Yucatán city rose to be a regional capital of the northern Maya, its buildings mixing central Mexican styles with those of the region."},
    {name:"Toltec state",href:"/empire/toltec-state",img:"/images/encyclopedia/tula-mesoamerican-site.jpg",meta:"Profile · 900 CE – 1150 CE",why:"Tula's warrior statues and colonnaded halls have close parallels at Chichén Itzá, and the Aztecs later revered the Toltecs as the founders of civilisation."},
    {name:"Aztec Empire",href:"/empire/aztec-empire",img:"/images/encyclopedia/templo-mayor.jpg",meta:"Profile · 1325 CE – 1521 CE",why:"From 1428 the Triple Alliance of Tenochtitlan, Texcoco and Tlacopan ruled central Mexico through tribute, from an island city of 200,000 or more people."},
    {name:"Purépecha Empire",href:"/empire/purepecha-empire",img:"/images/encyclopedia/curicaueri.jpg",meta:"Profile · 1300 CE – 1530 CE",why:"Ruled from Tzintzuntzan on Lake Pátzcuaro, this western kingdom routed Axayacatl's Aztec army in the late 1470s and led Mesoamerica in copper and bronze."},
    {name:"Tlaxcala",href:"/empire/tlaxcala",img:"/images/encyclopedia/maxixcatzin.jpg",meta:"Profile · 1348 CE – 1521 CE",why:"Four Nahua city-states that resisted the Triple Alliance for generations, then allied with Hernán Cortés in 1519 and helped take Tenochtitlan in 1521."}
  ]},
  {slug:"civilisations-of-the-andes",title:"Civilisations of the Andes",tagline:"From Caral's platform mounds to the last Inca stronghold at Vilcabamba, the civilisations of the Andes.",types:["builder","timekeeper"],eras:["ancient","medieval","earlymodern"],intro:"Caral–Supe, on Peru's north-central coast, raised platform mounds from about 3000 BCE and is the oldest known civilisation of the Americas. Later Andean peoples built on what came before: Chavín's temple cult spread across the central Andes, Paracas is believed to have evolved into the Nazca culture, and Wari's roads and cord records foreshadowed the institutions of the Incas. The stops move between the desert coast, where Moche lords and the kings of Chimor ruled irrigated valleys, and the highlands of Wari and Tiwanaku. They end with Tawantinsuyu, which stretched some 4,000 km along the Andes, and the Neo-Inca State that held out at Vilcabamba until 1572.",steps:[
    {name:"Caral–Supe civilisation",href:"/culture/caral-supe-civilisation",img:"/images/encyclopedia/caral.jpg",meta:"Profile · c. 3000 BCE – c. 1800 BCE",why:"As many as thirty centres in three small coastal valleys raised stepped platform mounds and sunken plazas from about 3000 BCE, with no pottery and no evidence of warfare."},
    {name:"Chavín",href:"/empire/chavin",img:"/images/encyclopedia/lanzon.jpg",meta:"Profile · 950 BCE – 400 BCE",why:"A highland temple town of c. 950–400 BCE whose priests drew pilgrims from coast, mountains and forest, and whose art of jaguars, eagles and caimans spread far across Peru."},
    {name:"Paracas culture",href:"/culture/paracas-culture",img:"/images/encyclopedia/trepanning.jpg",meta:"Profile · c. 800 BCE – c. 100 BCE",why:"On Peru's south coast its dead were wrapped in layers of embroidered cloth, the Paracas Necropolis textiles, among the finest of the Pre-Columbian Andes."},
    {name:"Nazca Lines",href:"/encyclopedia/nazca-lines",img:"/images/encyclopedia/nazca-lines.jpg",meta:"Encyclopedia · Work · c. 500 BCE–500 CE",why:"Figures and lines scraped into the desert between the Nazca and Palpa valleys, mostly between about 500 BCE and 500 CE, by the Paracas and Nazca cultures."},
    {name:"Moche",href:"/empire/moche",img:"/images/encyclopedia/lord-of-sipan.jpg",meta:"Profile · 100 CE – 800 CE",why:"On Peru's north coast, c. 100–800 CE, lords ruled irrigated valleys from adobe platforms such as the Huaca del Sol, and potters made lifelike portrait vessels."},
    {name:"Wari Empire",href:"/empire/wari-empire",img:"/images/encyclopedia/pikillacta.jpg",meta:"Profile · 600 CE – 1000 CE",why:"Often called the first Andean empire, Wari planted planned centres across highland Peru from about 600, and its roads and cord records foreshadowed the Incas."},
    {name:"Tiwanaku",href:"/empire/tiwanaku",img:"/images/encyclopedia/kalasasaya.jpg",meta:"Profile · 500 CE – 1000 CE",why:"A ceremonial city at about 3,850 metres near Lake Titicaca, sustained by raised fields and llama caravans, whose Staff God imagery spread across the southern Andes."},
    {name:"Chan Chan",href:"/encyclopedia/chan-chan",img:"/images/encyclopedia/chan-chan.jpg",meta:"Encyclopedia · Place · c. 850–1470",why:"The Chimú capital near Trujillo, the largest adobe city of the pre-Columbian Americas, with some ten walled royal compounds; the Incas took it around 1470."},
    {name:"Inca Empire",href:"/empire/inca-empire",img:"/images/encyclopedia/machu-picchu.jpg",meta:"Profile · 1438 CE – 1533 CE",why:"Tawantinsuyu stretched some 4,000 km and ran on labour tribute, storehouses, a 40,000 km road network and khipu records, until Pizarro's conquest in 1532–1533."},
    {name:"Neo-Inca State",href:"/empire/neo-inca-state",img:"/images/encyclopedia/espiritu-pampa.jpg",meta:"Profile · 1537 CE – 1572 CE",why:"Founded by Manco Inca in 1537, it kept the Inca court and Sun cult alive at Vilcabamba until Spanish forces took it and executed Túpac Amaru in 1572."}
  ]},
  {slug:"west-africas-golden-age",title:"West Africa's Golden Age",tagline:"The empires that grew rich on the Saharan gold and salt trade, and their southern neighbours.",types:["navigator","builder","strategist"],eras:["medieval","earlymodern"],intro:"Caravan routes across the Sahara carried gold, slaves and ivory north and salt, horses and textiles south, and with them came Islam and literacy. Ghana, Mali and Songhai grew rich on that trade, and under Mali and Songhai Timbuktu became a centre of Islamic learning whose scholars were famous across the Islamic world. Further east, Kanem-Bornu tied the Lake Chad basin to the route to Tripoli, and the walled Hausa city-kingdoms linked the Sahara with the forest. To the south, Benin's royal guilds cast the Benin Bronzes, Oyo's cavalry made it the leading power between the Niger and the Volta, and the Asante were bound together by the Golden Stool.",steps:[
    {name:"Trans-Saharan trade",href:"/encyclopedia/trans-saharan-trade",img:"",meta:"Encyclopedia · Term",why:"Caravans carried gold, slaves and ivory north across the Sahara and salt, horses and textiles south, and this trade underpinned the wealth of Ghana, Mali and Songhai."},
    {name:"Koumbi Saleh",href:"/encyclopedia/koumbi-saleh",img:"/images/encyclopedia/koumbi-saleh.jpg",meta:"Encyclopedia · Place",why:"Widely identified as the capital of the Ghana Empire, a twin city of a Muslim merchant quarter and a royal town, and a major centre of the gold and salt trade."},
    {name:"Mali Empire",href:"/empire/mali-empire",img:"/images/encyclopedia/djenne.jpg",meta:"Profile · 1235 CE – 1600 CE",why:"Founded by Sundiata Keita, Mali sent the gold of Bambuk and Bure into the Saharan trade, and in 1324 Mansa Musa's pilgrimage to Mecca dazzled Cairo with it."},
    {name:"Timbuktu",href:"/encyclopedia/timbuktu",img:"/images/encyclopedia/timbuktu.jpg",meta:"Encyclopedia · Place",why:"A city near the Niger at the southern edge of the Sahara, a centre of trade and Islamic learning under Mali that reached its height under Songhai."},
    {name:"Songhai Empire",href:"/empire/songhai-empire",img:"/images/encyclopedia/gao.jpg",meta:"Profile · 1430 CE – 1600 CE",why:"The largest empire in West African history held Gao, Timbuktu and Djenné on the Niger Bend, until a Moroccan army with firearms routed it at Tondibi in 1591."},
    {name:"Kanem-Bornu Empire",href:"/empire/kanem-bornu-empire",img:"/images/encyclopedia/sayf-ibn-dhi-yazan.jpg",meta:"Profile · 700 CE – 1893 CE",why:"Ruled for close to eight centuries by the Sayfawa dynasty, this Lake Chad empire held the route to Tripoli and tied the central Sudan to the Muslim world."},
    {name:"Hausa kingdoms",href:"/empire/hausa-kingdoms",img:"/images/encyclopedia/gobarau-minaret.jpg",meta:"Profile · 1000 CE – 1808 CE",why:"Walled city-kingdoms such as Kano, Katsina and Zazzau never united, but shared a language, court institutions and a trade network linking the Sahara and the forest."},
    {name:"Benin Empire",href:"/empire/benin-empire",img:"/images/encyclopedia/benin-bronzes.jpg",meta:"Profile · 1180 CE – 1897 CE",why:"From Benin City the Edo Obas built a regional empire from the 15th century, and royal guilds cast the Benin Bronzes, looted by a British expedition in 1897."},
    {name:"Oyo Empire",href:"/empire/oyo-empire",img:"/images/encyclopedia/yorubaland.jpg",meta:"Profile · 1300 CE – 1896 CE",why:"Its cavalry made this Yoruba savannah state the leading power between the Niger and the Volta, and in the 18th century it forced Dahomey into vassalage."},
    {name:"Golden Stool",href:"/encyclopedia/golden-stool",img:"/images/encyclopedia/golden-stool.jpg",meta:"Encyclopedia · Work",why:"The sacred throne of the Asante, believed to hold the soul of the nation; the British governor's demand of 1900 that it be surrendered provoked a war."}
  ]},
  {slug:"east-and-southern-africa",title:"East and Southern Africa",tagline:"Highland Christian kings, Swahili merchant towns, plateau gold and the kingdoms that faced Portugal and Britain.",types:["navigator","builder","strategist"],eras:["medieval","ancient","earlymodern","modern"],intro:"Aksum, in highland Ethiopia and Eritrea, grew rich on the Red Sea trade and under King Ezana became one of the first states to adopt Christianity. On the coast, Swahili merchant towns traded across the Indian Ocean from around the 8th century, and island Kilwa controlled the gold trade from Sofala. That gold came from the interior, where Mapungubwe, Great Zimbabwe and the Mutapa Empire rose one after another. The last stops turn to kingdoms that fought European expansion: Kongo and Ndongo against Portugal, and the Zulu Kingdom, which routed a British force at Isandlwana in 1879.",steps:[
    {name:"Aksumite Empire",href:"/empire/aksumite-empire",img:"/images/encyclopedia/ezana.jpg",meta:"Profile · 100 CE – 940 CE",why:"Aksum grew rich trading ivory and gold through its Red Sea port of Adulis, and under King Ezana became one of the first states to adopt Christianity."},
    {name:"Rock-hewn churches of Lalibela",href:"/encyclopedia/rock-hewn-churches-of-lalibela",img:"/images/encyclopedia/rock-hewn-churches-of-lalibela.jpg",meta:"Encyclopedia · Work",why:"Medieval churches carved out of the rock in the northern Ethiopian highlands, linked with King Lalibela of the Zagwe dynasty and still a major site of pilgrimage."},
    {name:"Swahili",href:"/language/swahili",img:"/images/encyclopedia/kilwa-kisiwani.jpg",meta:"Profile · c. 800 CE – present",why:"The Bantu speech of the East African coast took shape in merchant towns that traded across the Indian Ocean from around the 8th century, absorbing many Arabic words."},
    {name:"Kilwa Kisiwani",href:"/encyclopedia/kilwa-kisiwani",img:"/images/encyclopedia/kilwa-kisiwani.jpg",meta:"Encyclopedia · Place",why:"Seat of the Kilwa Sultanate, which controlled the gold trade from Sofala; Ibn Battuta praised it in 1331, and the Portuguese sacked it in 1505."},
    {name:"Kingdom of Mapungubwe",href:"/empire/kingdom-of-mapungubwe",img:"/images/encyclopedia/mapungubwe-hill.jpg",meta:"Profile · 1220 CE – 1290 CE",why:"Around 1220 its rulers moved onto a hill above the Limpopo, apart from the commoners below, and were buried with gold, among it the famous gold-foil rhinoceros."},
    {name:"Kingdom of Zimbabwe",href:"/empire/kingdom-of-zimbabwe",img:"/images/encyclopedia/great-zimbabwe.jpg",meta:"Profile · 1220 CE – 1450 CE",why:"A Shona kingdom rich on cattle and on gold and ivory sent to Sofala, whose dry-stone walls are the largest precolonial stone structures in southern Africa."},
    {name:"Mutapa Empire",href:"/empire/mutapa-empire",img:"/images/encyclopedia/zambezi.jpg",meta:"Profile · 1430 CE – 1760 CE",why:"Founded around 1430 as Great Zimbabwe declined, this Shona state between the Zambezi and Limpopo traded its gold through Swahili and later Portuguese merchants."},
    {name:"Kongo Empire",href:"/empire/kongo-empire",img:"/images/encyclopedia/lukeni-lua-nimi.jpg",meta:"Profile · 1390 CE – 1914 CE",why:"Ruled from Mbanza Kongo, it adopted Christianity and Portuguese literacy, and in 1526 Afonso I wrote to Portugal protesting the abuses of the slave trade."},
    {name:"Njinga of Ndongo and Matamba",href:"/encyclopedia/njinga-of-ndongo-and-matamba",img:"/images/encyclopedia/njinga-of-ndongo-and-matamba.jpg",meta:"Encyclopedia · Person · c. 1583–1663",why:"Queen of the Mbundu kingdoms of Ndongo and Matamba, she allied with the Dutch in the 1640s and resisted Portuguese expansion for decades, making peace in 1656."},
    {name:"Zulu Kingdom",href:"/empire/zulu-kingdom",img:"/images/encyclopedia/dingane.jpg",meta:"Profile · 1816 CE – 1887 CE",why:"Shaka turned a small chiefdom into the strongest state in southeastern Africa from 1816, and in 1879 the Zulu routed a British force at Isandlwana."}
  ]},
  {slug:"the-mongol-world",title:"The Mongol World",tagline:"Follow Genghis Khan's empire from the steppe to the rival khanates and Timur's heirs.",types:["strategist","navigator"],eras:["medieval"],intro:"In 1206 a kurultai on the Mongolian steppe proclaimed Temüjin Genghis Khan, and his armies built the largest contiguous land empire in history. Within two generations his sons and grandsons ruled from Sarai on the Volga, from Persia and Iraq, from the Silk Road cities of Central Asia and from Dadu in China, and the succession war of 1260–1264 split the empire into khanates. This path follows each of them: the Golden Horde and the Rus' princes, the Ilkhanate that ended the Abbasid Caliphate, the Chagatai realm that produced Timur, and Kublai's Yuan Dynasty, closing with the Timurid Empire, whose courts at Samarkand and Herat lasted until 1507.",steps:[
    {name:"Secret History of the Mongols",href:"/encyclopedia/secret-history-of-the-mongols",img:"/images/encyclopedia/secret-history-of-the-mongols.jpg",meta:"Encyclopedia · Work · 13th century",why:"The oldest surviving work of Mongolian literature tells of Temüjin's youth and his struggles with the Tatars and Merkits before his rise to power."},
    {name:"Mongol Empire",href:"/empire/mongol-empire",img:"/images/encyclopedia/genghis-khan.jpg",meta:"Profile · 1206 CE – 1368 CE",why:"Proclaimed Genghis Khan at a kurultai in 1206, Temüjin built the largest contiguous land empire in history, which split into rival khanates after 1260."},
    {name:"Batu Khan",href:"/encyclopedia/batu-khan",img:"/images/encyclopedia/batu-khan.jpg",meta:"Encyclopedia · Person · c. 1205–1255",why:"A grandson of Genghis Khan, Batu led the western campaign of 1236 to 1242 into Rus', Poland and Hungary, then ruled the western steppe from Sarai."},
    {name:"Golden Horde",href:"/empire/golden-horde",img:"/images/encyclopedia/mengu-timur.jpg",meta:"Profile · 1242 CE – 1502 CE",why:"From Sarai on the Volga, Jochi's descendants took tribute from the Rus' princes for over two centuries, until the Great Stand on the Ugra in 1480 ended Moscow's tribute."},
    {name:"Hulagu Khan",href:"/encyclopedia/hulagu-khan",img:"/images/encyclopedia/hulagu-khan.jpg",meta:"Encyclopedia · Person · c. 1217–1265",why:"Another grandson led the Mongol campaigns into south-western Asia in the 1250s, sacking Baghdad in 1258 and ending the Abbasid Caliphate."},
    {name:"Ilkhanate",href:"/empire/ilkhanate",img:"/images/encyclopedia/dome-of-soltaniyeh.jpg",meta:"Profile · 1256 CE – 1357 CE",why:"Hulagu's khanate in Persia and Iraq became a Persianised Islamic state under Ghazan, who converted in 1295 and began sweeping reforms with Rashid al-Din."},
    {name:"Chagatai Empire",href:"/empire/chagatai-empire",img:"/images/encyclopedia/kaidu.jpg",meta:"Profile · 1225 CE – 1500 CE",why:"Genghis Khan allotted Central Asia's steppe and Silk Road cities to his son Chagatai; the khanate turned Muslim and Turkic and lost Transoxiana to Timur by 1370."},
    {name:"Kublai Khan",href:"/encyclopedia/kublai-khan",img:"/images/encyclopedia/kublai-khan.jpg",meta:"Encyclopedia · Person · 1215–1294",why:"Great Khan and founder of the Yuan Dynasty, Kublai completed the conquest of the Song in 1279, and his disputed succession helped break the empire apart."},
    {name:"Yuan Dynasty",href:"/empire/yuan-dynasty",img:"/images/encyclopedia/kublai-khan.jpg",meta:"Profile · 1271 CE – 1368 CE",why:"Ruling China from Dadu, the Yuan linked it to Persia and Europe across the Mongol network until floods, inflation and the Red Turbans brought it down in 1368."},
    {name:"Timurid Empire",href:"/empire/timurid-empire",img:"/images/encyclopedia/samarkand.jpg",meta:"Profile · 1363 CE – 1507 CE",why:"Timur, produced by the Chagatai realm, conquered from Anatolia to the borders of China, and his heirs made Samarkand and Herat centres of painting, poetry and astronomy."}
  ]},
  {slug:"japan-from-jomon-to-meiji",title:"Japan from Jōmon to Meiji",tagline:"Follow the Japanese archipelago from its first potters to the emperor's restored rule.",types:["chronicler","strategist"],eras:["medieval","ancient","earlymodern","modern"],intro:"For some 14,000 years the people of the Japanese archipelago lived mainly by hunting, gathering and fishing, and their potters made the world's oldest known ceramics. Wet-rice farming came with the Yayoi, and the Yamato court around Nara extended its authority over much of the islands. From the late twelfth century warrior governments held power: the Kamakura and Ashikaga shogunates, then, after the unification begun by Oda Nobunaga, the Tokugawa shoguns at Edo. This path follows that story to 1868, when the Meiji Restoration returned power to the emperor and set Japan on the way to becoming an industrial great power.",steps:[
    {name:"Jōmon culture",href:"/culture/jomon-culture",img:"",meta:"Profile · c. 14000 BCE – c. 300 BCE",why:"For some 14,000 years hunters, gatherers and fishers lived in settled villages here, and their potters made the world's oldest known ceramics, around 14,500 BCE."},
    {name:"Yayoi culture",href:"/culture/yayoi-culture",img:"/images/encyclopedia/wet-rice-agriculture.jpg",meta:"Profile · c. 300 BCE – c. 300 CE",why:"Farming migrants from the Korean Peninsula and the continent brought wet-rice farming, bronze and iron, and mixed with the Jōmon population from about 300 BCE."},
    {name:"Yamato court",href:"/encyclopedia/yamato-court",img:"/images/encyclopedia/yamato-court.jpg",meta:"Encyclopedia · State · c. 250–710",why:"Centred around modern Nara, the court from which the imperial line descends built keyhole-shaped burial mounds and received writing and Buddhism through Baekje."},
    {name:"Heian-kyō",href:"/encyclopedia/heian-kyo",img:"/images/encyclopedia/heian-kyo.jpg",meta:"Encyclopedia · Place",why:"Founded by Emperor Kanmu in 794 on a grid modelled on Chang'an, the capital on the site of modern Kyoto remained the imperial seat for more than a thousand years."},
    {name:"Minamoto no Yoritomo",href:"/encyclopedia/minamoto-no-yoritomo",img:"/images/encyclopedia/minamoto-no-yoritomo.jpg",meta:"Encyclopedia · Person · 1147–1199",why:"Victor over the Taira in the Genpei War of 1180–1185, Yoritomo set up a warrior government at Kamakura and received the title of shogun in 1192."},
    {name:"Ashikaga Takauji",href:"/encyclopedia/ashikaga-takauji",img:"/images/encyclopedia/ashikaga-takauji.jpg",meta:"Encyclopedia · Person · 1305–1358",why:"Turning against the Kamakura shogunate in 1333, Takauji took Kyoto in 1336 and in 1338 became shogun, founding the Ashikaga, or Muromachi, shogunate."},
    {name:"Oda Nobunaga",href:"/encyclopedia/oda-nobunaga",img:"/images/encyclopedia/oda-nobunaga.jpg",meta:"Encyclopedia · Person · 1534–1582",why:"A warlord of the Sengoku period, Nobunaga began the military unification of Japan that Toyotomi Hideyoshi continued and Tokugawa Ieyasu completed."},
    {name:"Tokugawa Shogunate",href:"/empire/tokugawa-shogunate",img:"/images/encyclopedia/edo-castle.jpg",meta:"Profile · 1603 CE – 1868 CE",why:"After victory at Sekigahara the Tokugawa shoguns ruled from Edo, keeping some 260 daimyo in check through two and a half centuries of internal peace."},
    {name:"Meiji Restoration",href:"/movement/meiji-restoration",img:"/images/encyclopedia/meiji-restoration.jpg",meta:"Profile · 1853 CE – 1889 CE",why:"Perry's expedition and the unequal treaties undermined the shogunate; in 1868 Emperor Meiji declared power restored, and the domains and the samurai class were abolished."},
    {name:"Empire of Japan",href:"/empire/empire-of-japan",img:"/images/encyclopedia/emperor-meiji.jpg",meta:"Profile · 1868 CE – 1945 CE",why:"Born of the Restoration, Japan went from feudal isolation to industrial great power in barely a generation, until a war it could not sustain ended in surrender in 1945."}
  ]},
  {slug:"korea-through-the-ages",title:"Korea through the Ages",tagline:"Follow the Korean Peninsula from its early farming villages to its division in 1945.",types:["chronicler","builder","strategist"],eras:["medieval","ancient","earlymodern","modern"],intro:"Archaeologists name a long stretch of Korean prehistory after the plain pottery of the Mumun farmers, whose villages gave way to the first chiefdom-like societies in Korea. Gojoseon fell to the Han in 108 BCE, and the Three Kingdoms of Goguryeo, Baekje and Silla contended for the peninsula until Silla, allied with Tang China, destroyed its rivals and then expelled the Tang. Goryeo reunified the peninsula in 936 and gave Korea its Western name; Joseon, its longest-ruling dynasty, made Neo-Confucianism the basis of the state and created the Korean alphabet. The path ends with the Japanese protectorate of 1905 and the division of 1945, which left two Korean states.",steps:[
    {name:"Mumun culture",href:"/culture/mumun-culture",img:"",meta:"Profile · c. 1500 BCE – c. 300 BCE",why:"Named after its plain pottery, the culture of c. 1500–300 BCE saw intensive farming, large villages and the first chiefdom-like societies in Korea."},
    {name:"Ugeo of Gojoseon",href:"/encyclopedia/ugeo-of-gojoseon",img:"",meta:"Encyclopedia · Person · ?–108 BCE",why:"The last king of Wiman Joseon, the final phase of Gojoseon, refused to submit to Emperor Wu of Han, whose invasion took his capital in 108 BCE."},
    {name:"Goguryeo",href:"/empire/goguryeo",img:"/images/encyclopedia/gwanggaeto-stele.jpg",meta:"Profile · 37 BCE – 668 CE",why:"The largest of the Three Kingdoms ruled Manchuria and the northern peninsula, and its fortresses held off Sui and Tang invasions for seventy years."},
    {name:"Baekje",href:"/empire/baekje",img:"/images/encyclopedia/asuka-dera.jpg",meta:"Profile · 18 BCE – 660 CE",why:"The south-western kingdom, known for refined Buddhist art, passed Chinese writing, Buddhism and craftsmen to Yamato Japan before falling to Silla and the Tang in 660."},
    {name:"Silla",href:"/empire/silla",img:"/images/encyclopedia/bulguksa.jpg",meta:"Profile · 57 BCE – 935 CE",why:"Allied with Tang China, Silla destroyed Baekje and Goguryeo, expelled the Tang by 676 and presided over a Buddhist golden age at Gyeongju."},
    {name:"Goryeo",href:"/empire/goryeo",img:"/images/encyclopedia/gung-ye.jpg",meta:"Profile · 918 CE – 1392 CE",why:"Founded by Wang Geon in 918, the dynasty that gave Korea its Western name carved the Tripitaka Koreana and endured Mongol overlordship from 1259."},
    {name:"Joseon",href:"/empire/joseon",img:"/images/encyclopedia/hunminjeongeum.jpg",meta:"Profile · 1392 CE – 1897 CE",why:"Korea's longest-ruling dynasty, founded by Yi Seong-gye in 1392, made Neo-Confucianism the basis of state and society and survived Japanese and Manchu invasions."},
    {name:"Hangul",href:"/encyclopedia/hangul",img:"/images/encyclopedia/hangul.jpg",meta:"Encyclopedia · Term · 1443",why:"Created in 1443 under King Sejong and promulgated as 'the proper sounds for instructing the people', the alphabet became Korea's national script in the 20th century."},
    {name:"Japan–Korea Treaty of 1905",href:"/encyclopedia/japan-korea-treaty-of-1905",img:"/images/encyclopedia/japan-korea-treaty-of-1905.jpg",meta:"Encyclopedia · Event · 1905",why:"Pushed through with troops around the palace after the Russo-Japanese War, the treaty made Korea a Japanese protectorate; Japan annexed the country in 1910."},
    {name:"Division of Korea",href:"/encyclopedia/division-of-korea",img:"",meta:"Encyclopedia · Event · 1945",why:"Split at the 38th parallel in 1945, the peninsula gained two rival states in 1948, and the armistice of 1953 left it divided along the Demilitarized Zone."}
  ]},
  {slug:"kingdoms-of-southeast-asia",title:"Kingdoms of Southeast Asia",tagline:"Follow the trading ports, temple cities and sultanates of mainland and island Southeast Asia.",types:["navigator","builder"],eras:["medieval","ancient","earlymodern"],intro:"Funan, generally considered the first known kingdom of Southeast Asia, traded through its port of Óc Eo with India, China and the Roman world. Along the Mekong, the Vietnamese coast and the straits, later states drew their wealth from sea trade, rice and tribute, and built in stone: the Sailendras raised Borobudur in Java, the Khmer kings Angkor Wat, and the kings of Pagan some 10,000 Buddhist monuments on the Irrawaddy. This path follows these kingdoms in the order of their rise, closing with Ayutthaya on the Chao Phraya and the Muslim sultanate of Malacca, which the Portuguese took in 1511.",steps:[
    {name:"Funan",href:"/empire/funan",img:"/images/encyclopedia/angkor-borei.jpg",meta:"Profile · 50 CE – 627 CE",why:"Generally considered the first known kingdom of Southeast Asia, Funan traded through its port of Óc Eo, where Roman gold medallions and Indian and Persian goods were found."},
    {name:"Champa",href:"/empire/champa",img:"/images/encyclopedia/kauthara.jpg",meta:"Profile · 192 CE – 1832 CE",why:"A confederation of Cham principalities on the coast of present-day Vietnam, whose fleets controlled the spice and silk trade of the South China Sea from the 7th to the 10th century."},
    {name:"Chenla",href:"/empire/chenla",img:"/images/encyclopedia/sambor-prei-kuk.jpg",meta:"Profile · 550 CE – 802 CE",why:"The Khmer principalities that broke from Funan absorbed it under Isanavarman I, before Jayavarman II proclaimed the Khmer Empire in 802."},
    {name:"Srivijaya Empire",href:"/empire/srivijaya-empire",img:"/images/encyclopedia/sailendra-dynasty.jpg",meta:"Profile · 650 CE – 1377 CE",why:"From Palembang in Sumatra this sea power ruled the Strait of Malacca, taxed China-India shipping and became a renowned centre of Buddhist learning."},
    {name:"Borobudur",href:"/encyclopedia/borobudur",img:"/images/encyclopedia/borobudur.jpg",meta:"Encyclopedia · Work",why:"One of the largest Buddhist monuments in the world, the temple was built in central Java under the Sailendra dynasty, closely connected to Srivijaya."},
    {name:"Khmer Empire",href:"/empire/khmer-empire",img:"/images/encyclopedia/angkor-wat.jpg",meta:"Profile · 802 CE – 1431 CE",why:"Founded in 802, the empire ruled much of mainland Southeast Asia from Angkor, where vast reservoirs and canals paid for Angkor Wat and Angkor Thom."},
    {name:"Pagan Kingdom",href:"/empire/pagan-kingdom",img:"/images/encyclopedia/ananda-temple.jpg",meta:"Profile · 849 CE – 1297 CE",why:"The first state to unite the Irrawaddy valley built some 10,000 Buddhist monuments on the plain of Bagan before Mongol invasions in the 1280s broke it apart."},
    {name:"Majapahit Empire",href:"/empire/majapahit-empire",img:"/images/encyclopedia/trowulan.jpg",meta:"Profile · 1293 CE – 1527 CE",why:"The high point of Hindu-Buddhist Java claimed suzerainty over much of the archipelago, its fleets paid for by Brantas rice and the spice trade."},
    {name:"Ayutthaya Kingdom",href:"/empire/ayutthaya-kingdom",img:"/images/encyclopedia/wat-phra-si-sanphet.jpg",meta:"Profile · 1351 CE – 1767 CE",why:"The Siamese kingdom on the Chao Phraya absorbed Sukhothai in 1438 and welcomed Chinese, Japanese, Persian and European merchants until Burma destroyed it in 1767."},
    {name:"Malacca Sultanate",href:"/empire/malacca-sultanate",img:"/images/encyclopedia/parameswara.jpg",meta:"Profile · 1400 CE – 1511 CE",why:"Founded about 1400 by Parameswara under Ming protection, the port became the great entrepôt of the strait and a centre of Islamic learning until the Portuguese took it in 1511."}
  ]},
  {slug:"the-ottoman-centuries",title:"The Ottoman Centuries",tagline:"The Ottoman state from a frontier beylik in Anatolia to the Republic of Turkey.",types:["strategist","chronicler","builder"],eras:["earlymodern","medieval","modern"],intro:"The Ottoman Empire lasted over six centuries, from about 1299 to 1922, and at its height ruled across three continents. These stops follow it from Osman I's beylik on the Byzantine frontier through the conquest of Constantinople, the gains of Selim I and the reign of Suleiman the Magnificent. They then turn to the reforms of the nineteenth century, the Tanzimat and the Young Turks, and to the defeat in the First World War that ended the sultanate in 1922. The last stops show the Republic proclaimed in Ankara in 1923 under Mustafa Kemal.",steps:[
    {name:"Ottoman Empire",href:"/empire/ottoman-empire",img:"/images/encyclopedia/suleymaniye-mosque.jpg",meta:"Profile · 1299 CE – 1922 CE",why:"A frontier beylik in Anatolia grew, with Janissary infantry, gunpowder artillery and a sophisticated bureaucracy, into a power spanning three continents for six centuries."},
    {name:"Osman I",href:"/encyclopedia/osman-i",img:"/images/encyclopedia/osman-i.jpg",meta:"Encyclopedia · Person · d. c. 1324",why:"Osman I, a Turkoman chieftain of the Kayı clan, held a beylik in Bithynia on the Byzantine frontier, and his victory at Bapheus in 1301 gave the dynasty its military credibility."},
    {name:"Fall of Constantinople",href:"/encyclopedia/fall-of-constantinople",img:"/images/encyclopedia/fall-of-constantinople.jpg",meta:"Encyclopedia · Event · 1453",why:"In 1453 Mehmed II took the Byzantine capital after a siege in which heavy artillery played a major role, ending the Byzantine Empire and making the city the Ottoman capital."},
    {name:"Selim I",href:"/encyclopedia/selim-i",img:"/images/encyclopedia/selim-i.jpg",meta:"Encyclopedia · Person · 1470–1520",why:"Selim I defeated the Safavids at Chaldiran in 1514 and conquered the Mamluk Sultanate in 1516–1517, bringing Syria, Egypt and the holy cities of Arabia under Ottoman rule."},
    {name:"Suleiman the Magnificent",href:"/encyclopedia/suleiman-the-magnificent",img:"/images/encyclopedia/suleiman-the-magnificent.jpg",meta:"Encyclopedia · Person · 1494–1566",why:"Suleiman, known in Turkish as Kanuni, the Lawgiver, conquered Belgrade, won at Mohács and besieged Vienna, in a reign treated as the height of Ottoman power and legal codification."},
    {name:"Janissaries",href:"/encyclopedia/janissaries",img:"/images/encyclopedia/janissaries.jpg",meta:"Encyclopedia · Institution",why:"First recruited from Christian boys through the devshirme, the elite infantry became one of Europe's first standing armies to use firearms on a large scale, until their abolition in 1826."},
    {name:"Tanzimat",href:"/movement/tanzimat",img:"/images/encyclopedia/tanzimat.jpg",meta:"Profile · 1839 CE – 1876 CE",why:"From the Edict of Gülhane in 1839 to the constitution of 1876, Ottoman statesmen rebuilt the ministries, courts, schools, law codes and army and promised equality to all subjects."},
    {name:"Young Turks",href:"/movement/young-turks",img:"/images/encyclopedia/enver-pasha.jpg",meta:"Profile · 1889 CE – 1918 CE",why:"Their Committee of Union and Progress forced the sultan to restore the constitution in 1908, later ruled as a dictatorship and masterminded the genocides of Ottoman Christians."},
    {name:"Mustafa Kemal Atatürk",href:"/encyclopedia/mustafa-kemal-ataturk",img:"/images/encyclopedia/mustafa-kemal-ataturk.jpg",meta:"Encyclopedia · Person · c. 1881–1938",why:"After the Ottoman defeat and the Allied occupation of Istanbul, Mustafa Kemal, an Ottoman army officer, led the Turkish national movement against the post-war partition of Anatolia."},
    {name:"Republic of Turkey",href:"/empire/republic-of-turkey",img:"/images/encyclopedia/mustafa-kemal-ataturk.jpg",meta:"Profile · 1923 CE – 2025 CE",why:"Proclaimed in Ankara on 29 October 1923 after the Treaty of Lausanne, the Republic was turned by Mustafa Kemal's reforms into a secular nation state with a new civil code and alphabet."}
  ]},
  {slug:"russia-from-rus-to-revolution",title:"Russia from Rus' to Revolution",tagline:"The Russian state from the princes of Kiev to the Soviet Union and its end.",types:["strategist","chronicler","timekeeper"],eras:["medieval","earlymodern","modern"],intro:"The first great East Slavic state was Kievan Rus', ruled by the Rurikid princes from Kiev on the river route from the Baltic to Byzantium. These stops follow its conversion to Orthodox Christianity, the merchant republic of Novgorod, the Mongol conquest and the rise of Moscow, which gathered the Russian lands and threw off Tatar rule. They continue through the tsars from Ivan IV to Peter the Great, the Russian Empire that grew to some 22.8 million square kilometres, and the revolution of 1917. The last stop is the Soviet Union, founded in 1922 and dissolved in 1991.",steps:[
    {name:"Kievan Rus'",href:"/empire/kievan-rus",img:"/images/encyclopedia/golden-gate-kyiv.jpg",meta:"Profile · 882 CE – 1240 CE",why:"Rurikid princes ruled the first great East Slavic state from Kiev, a federation of principalities on the river route from the Baltic to Byzantium, until the Mongols sacked Kiev in 1240."},
    {name:"Vladimir the Great",href:"/encyclopedia/vladimir-the-great",img:"/images/encyclopedia/vladimir-the-great.jpg",meta:"Encyclopedia · Person · c. 958–1015",why:"In 988 Vladimir the Great accepted Christianity from Byzantium and married the emperor's sister Anna, bringing churches, Church Slavonic writing and Byzantine art to Kievan Rus'."},
    {name:"Novgorod Republic",href:"/empire/novgorod-republic",img:"/images/encyclopedia/church-of-the-transfiguration-on-ilyina-street.jpg",meta:"Profile · 1136 CE – 1478 CE",why:"This merchant city-state of the Russian north elected its officials and archbishop, hired princes by contract and traded furs with the Hanseatic League until Ivan III annexed it in 1478."},
    {name:"Mongol invasion of Kievan Rus'",href:"/encyclopedia/mongol-invasion-of-kievan-rus",img:"/images/encyclopedia/mongol-invasion-of-kievan-rus.jpg",meta:"Encyclopedia · Event · 1223–1242",why:"Batu Khan's conquest of 1237–1240 destroyed Ryazan, Vladimir and many other cities, and the Rus' principalities then paid tribute to the Golden Horde for some two centuries."},
    {name:"Grand Duchy of Moscow",href:"/empire/grand-duchy-of-moscow",img:"/images/encyclopedia/dormition-cathedral-moscow.jpg",meta:"Profile · 1263 CE – 1547 CE",why:"A small appanage on the Moskva River grew rich collecting tribute for the Golden Horde, ended Tatar overlordship at the Ugra River in 1480 and annexed Novgorod and Tver."},
    {name:"Tsardom of Russia",href:"/empire/tsardom-of-russia",img:"/images/encyclopedia/red-square.jpg",meta:"Profile · 1547 CE – 1721 CE",why:"Founded when Ivan IV was crowned the first Tsar of All Russia in 1547, the Tsardom conquered the Volga khanates and crossed Siberia to the Pacific."},
    {name:"Peter the Great",href:"/encyclopedia/peter-the-great",img:"/images/encyclopedia/peter-the-great.jpg",meta:"Encyclopedia · Person · 1672–1725",why:"Proclaimed emperor in 1721 after victory over Sweden, Peter reorganised the army, built a navy, founded St Petersburg and subordinated the Church to the state."},
    {name:"Russian Empire",href:"/empire/russian-empire",img:"/images/encyclopedia/peter-the-great.jpg",meta:"Profile · 1721 CE – 1917 CE",why:"Grown to some 22.8 million square kilometres from the Baltic to the Pacific, the empire freed some 23 million serfs in 1861 by Alexander II's Emancipation Edict."},
    {name:"Russian Revolution",href:"/encyclopedia/russian-revolution",img:"/images/encyclopedia/russian-revolution.jpg",meta:"Encyclopedia · Event · 1917",why:"The February Revolution of 1917 forced Nicholas II to abdicate, and in the October Revolution the Bolsheviks under Lenin seized power, then won the civil war that followed."},
    {name:"Soviet Union",href:"/empire/soviet-union",img:"/images/encyclopedia/yuri-gagarin.jpg",meta:"Profile · 1922 CE – 1991 CE",why:"Founded in 1922 as the first communist state, it industrialised under Stalin at enormous human cost, rivalled the United States as a superpower and was dissolved in 1991."}
  ]},
  {slug:"nations-born-in-the-nineteenth-century",title:"Nations Born in the Nineteenth Century",tagline:"How nationalism, revolts and wars of unification made new states in Europe and the Americas.",types:["strategist","chronicler"],eras:["modern"],intro:"Nationalism holds that a nation should govern itself, and scholars frequently date its beginning to the late eighteenth century. These stops follow states made in the nineteenth century: in the Americas, Gran Colombia and the Brazilian Empire, which ended Spanish and Portuguese rule; in Europe, Greece, the first nation state carved from the Ottoman Empire, and Belgium, which broke away from the Netherlands in 1830. The revolutions of 1848 sought nation states across the continent, and the path ends with the kingdom of Italy proclaimed in 1861 and the German Empire in 1871.",steps:[
    {name:"Nationalism",href:"/ideology/nationalism",img:"/images/encyclopedia/johann-gottfried-herder.jpg",meta:"Profile · c. 1772 CE – present",why:"The ideology that a nation should govern itself and is the only rightful source of political power is frequently dated by scholars to the late 18th century."},
    {name:"Gran Colombia",href:"/empire/gran-colombia",img:"/images/encyclopedia/simon-bolivar.jpg",meta:"Profile · 1819 CE – 1831 CE",why:"Proclaimed by Simón Bolívar's Congress of Angostura in 1819, this republic of Venezuela, New Granada, Quito and Panama ended Spanish rule in South America at Junín and Ayacucho in 1824."},
    {name:"Brazilian Empire",href:"/empire/brazilian-empire",img:"/images/encyclopedia/pedro-ii-of-brazil.jpg",meta:"Profile · 1822 CE – 1889 CE",why:"Prince Pedro declared Brazil independent of Portugal in 1822 and ruled it as Emperor Pedro I, founding the only lasting empire in the Americas, which fell to an army coup in 1889."},
    {name:"Greek War of Independence",href:"/encyclopedia/greek-war-of-independence",img:"/images/encyclopedia/greek-war-of-independence.jpg",meta:"Encyclopedia · Event · 1830",why:"A revolt against Ottoman rule in the 1820s ended with international recognition of an independent Greek state in 1830, after European powers intervened decisively on the Greek side."},
    {name:"Kingdom of Greece",href:"/empire/kingdom-of-greece",img:"/images/encyclopedia/ioannis-kapodistrias.jpg",meta:"Profile · 1832 CE – 1973 CE",why:"Created by Britain, France and Russia in 1832 with Otto of Bavaria as king, it was the first nation state carved from the Ottoman Empire and pursued the Great Idea of uniting all Greeks."},
    {name:"Belgian Revolution",href:"/encyclopedia/belgian-revolution",img:"/images/encyclopedia/belgian-revolution.jpg",meta:"Encyclopedia · Event · 1830–1831",why:"Riots in Brussels after an opera in August 1830 led the southern provinces to break away from William I of the Netherlands, and the great powers recognised Belgium in 1831."},
    {name:"Revolutions of 1848",href:"/encyclopedia/revolutions-of-1848",img:"/images/encyclopedia/revolutions-of-1848.jpg",meta:"Encyclopedia · Event · 1848–1849",why:"The springtime of the peoples spread from Sicily and Paris to more than fifty countries, as workers and middle-class reformers sought constitutions, nation states and a free press."},
    {name:"Giuseppe Garibaldi",href:"/encyclopedia/giuseppe-garibaldi",img:"/images/encyclopedia/giuseppe-garibaldi.jpg",meta:"Encyclopedia · Person · 1807–1882",why:"In 1860 Giuseppe Garibaldi led the Expedition of the Thousand that conquered Sicily and Naples, a decisive step in the unification of Italy."},
    {name:"Kingdom of Italy",href:"/empire/kingdom-of-italy",img:"/images/encyclopedia/giuseppe-garibaldi.jpg",meta:"Profile · 1861 CE – 1946 CE",why:"Parliament in Turin proclaimed Victor Emmanuel II king of Italy in 1861, and the House of Savoy completed unification when Italian troops took Rome from the Papal States in 1870."},
    {name:"German Empire",href:"/empire/german-empire",img:"/images/encyclopedia/proclamation-of-the-german-empire.jpg",meta:"Profile · 1871 CE – 1918 CE",why:"Proclaimed at Versailles in 1871 after victory over France, it united the German states under Prussian leadership and became continental Europe's leading industrial power."}
  ]},
  {slug:"inventions-that-changed-the-world",title:"Inventions That Changed the World",tagline:"From the wheel and cuneiform to printing, steam power and the electric telegraph.",types:["builder","thinker","timekeeper"],eras:["ancient","medieval","earlymodern","modern"],intro:"The oldest indirect evidence of wheeled movement dates from before 4000 BCE, and the speakers of Sumerian developed cuneiform writing around 3200 BCE. These stops follow inventions from those beginnings through paper, the magnetic compass and movable type, all developed in China, to Gutenberg's press in fifteenth-century Europe. They continue with the new instruments of the Scientific Revolution and with the steam engine, made practical for industry by James Watt's separate condenser, and end with the telegraph of the nineteenth century. Where the entries name the makers, they are stops of their own.",steps:[
    {name:"Wheel",href:"/encyclopedia/wheel",img:"/images/encyclopedia/wheel.jpg",meta:"Encyclopedia · Term · before 4000 BCE",why:"Miniature clay wheels from north of the Black Sea, from before 4000 BCE, are the oldest indirect evidence of wheeled movement; the spoked wheel later allowed swifter war chariots."},
    {name:"Sumerian",href:"/language/sumerian",img:"/images/encyclopedia/instructions-of-shuruppak.jpg",meta:"Profile · c. 3200 BCE – c. 80 CE",why:"Speakers of Sumerian, with Egyptian one of the two earliest written languages, developed cuneiform around 3200 BCE, at first to keep accounts, on tablets written at Uruk."},
    {name:"Cai Lun",href:"/encyclopedia/cai-lun",img:"/images/encyclopedia/cai-lun.jpg",meta:"Encyclopedia · Person · c. 62–121",why:"In 105 CE this court eunuch of the Eastern Han presented Emperor He with paper made from tree bark, hemp, old rags and fishing nets, cheaper than silk and lighter than bamboo."},
    {name:"Magnetic compass",href:"/encyclopedia/magnetic-compass",img:"/images/encyclopedia/magnetic-compass.jpg",meta:"Encyclopedia · Term",why:"Developed in China, the magnetised needle was used for navigation at sea under the Song Dynasty, aided maritime trade and later transformed navigation worldwide."},
    {name:"Bi Sheng",href:"/encyclopedia/bi-sheng",img:"/images/encyclopedia/bi-sheng.jpg",meta:"Encyclopedia · Person · d. 1051",why:"Around 1040 CE this Song Dynasty artisan invented movable type printing with ceramic characters, a method recorded by the scholar Shen Kuo, about four centuries before Gutenberg."},
    {name:"Johannes Gutenberg",href:"/encyclopedia/johannes-gutenberg",img:"/images/encyclopedia/johannes-gutenberg.jpg",meta:"Encyclopedia · Person · c. 1400–1468",why:"In the fifteenth century Johannes Gutenberg developed printing with movable metal type in Europe, and his press transformed the spread of knowledge there."},
    {name:"Scientific Revolution",href:"/movement/scientific-revolution",img:"/images/encyclopedia/galileo-galilei.jpg",meta:"Profile · 1543 CE – 1687 CE",why:"From Copernicus in 1543 to Newton in 1687, European scholars joined mathematics, measurement and experiment and used new instruments such as the telescope, microscope and air pump."},
    {name:"Steam engine",href:"/encyclopedia/steam-engine",img:"/images/encyclopedia/steam-engine.jpg",meta:"Encyclopedia · Term · 1606",why:"Jerónimo de Ayanz patented a steam-powered mine pump in 1606, and Thomas Newcomen's engine of about 1712 was the first commercially successful one to transmit continuous power."},
    {name:"James Watt",href:"/encyclopedia/james-watt",img:"/images/encyclopedia/james-watt.jpg",meta:"Encyclopedia · Person · 1736–1819",why:"James Watt's separate condenser, patented in 1769, greatly reduced fuel use, and with Matthew Boulton at Birmingham from 1775 he built engines that drove mills and pumped mines."},
    {name:"Telegraph",href:"/encyclopedia/telegraph",img:"/images/encyclopedia/telegraph.jpg",meta:"Encyclopedia · Term",why:"Developed in the nineteenth century, the telegraph sent messages by electrical signals along wires, and submarine cables linked Britain with India, Australia and other parts of its empire."}
  ]},
  {slug:"midwinter-festivals",title:"Midwinter Festivals",tagline:"How the darkest days of the year have been marked from Rome to Japan.",types:["thinker","timekeeper"],eras:["ancient","medieval","modern"],intro:"The winter solstice gives the Northern Hemisphere its shortest day and longest night on 21 or 22 December, and festivals have marked it since prehistory as the point when daylight begins to increase again. These stops follow that season across Eurasia: the Roman Saturnalia, the Yule of the heathen Germanic peoples, which later merged with Christmas, and the Slavic koliada, some of whose rituals date to pre-Christian times. They then turn to Yalda Night in Iran, the bonfires of Lohri in Punjab and Dongzhi in China, and end with Ōmisoka, the last day of the Japanese year.",steps:[
    {name:"Winter solstice",href:"/encyclopedia/winter-solstice",img:"/images/encyclopedia/winter-solstice.jpg",meta:"Encyclopedia · Idea",why:"The shortest day and longest night of the year has been marked since prehistory as the point when daylight begins to increase; Newgrange and Stonehenge are aligned with it."},
    {name:"Saturnalia",href:"/encyclopedia/saturnalia",img:"/images/encyclopedia/saturnalia.jpg",meta:"Encyclopedia · Idea",why:"Rome's festival of Saturn ran for seven days to 23 December, with a public banquet, gift-giving, gambling and masters serving their slaves at table."},
    {name:"Norse religion",href:"/religion/norse-religion",img:"/images/encyclopedia/oseberg-ship.jpg",meta:"Profile · c. 500 CE – c. 1100 CE",why:"The pre-Christian religion of Scandinavia worshipped Odin, Thor, Freyr and Freyja with sacrifices and feasts led by chieftains and kings."},
    {name:"Yule",href:"/encyclopedia/yule",img:"/images/encyclopedia/yule.jpg",meta:"Encyclopedia · Idea",why:"Feasting, ceremonial drinking and oath swearing were central to this Germanic winter festival, which merged with Christmas and still names it in Northern European languages."},
    {name:"Slavic paganism",href:"/religion/slavic-paganism",img:"/images/encyclopedia/svantevit.jpg",meta:"Profile · c. 500 CE – c. 1331 CE",why:"Slavic rulers adopted Christianity between 863 and 988, but popular resistance lasted for centuries and the old rites lived on in a “double faith”."},
    {name:"Koliada",href:"/encyclopedia/koliada",img:"/images/encyclopedia/koliada.jpg",meta:"Encyclopedia · Idea",why:"The Slavic name for the days from Christmas to Epiphany covers rituals of which some date to pre-Christian times, among them carols sung from house to house for gifts."},
    {name:"Yalda Night",href:"/encyclopedia/yalda-night",img:"/images/encyclopedia/yalda-night.jpg",meta:"Encyclopedia · Idea",why:"On the longest night of the year families in Iran and its neighbours gather to eat, drink and read Hafez; in Zoroastrian tradition the night was inauspicious."},
    {name:"Lohri",href:"/encyclopedia/lohri",img:"/images/encyclopedia/lohri.jpg",meta:"Encyclopedia · Idea",why:"Punjab marks the passing of the winter solstice with bonfires, festive foods, bhangra and songs of Dulla Bhatti on the night before Makar Sankranti."},
    {name:"Dongzhi",href:"/encyclopedia/dongzhi",img:"/images/encyclopedia/dongzhi.jpg",meta:"Encyclopedia · Idea",why:"China's winter solstice festival, first celebrated under the Zhou and made official under the Han, reads the lengthening days through yin and yang."},
    {name:"Ōmisoka",href:"/encyclopedia/omisoka",img:"/images/encyclopedia/omisoka.jpg",meta:"Encyclopedia · Idea",why:"Japan closes the year with house cleaning, repaid debts and long noodles, and at midnight most Buddhist temples strike a large bell 108 times."}
  ]},
  {slug:"the-story-of-christmas",title:"The Story of Christmas",tagline:"From the Nativity accounts and the choice of 25 December to the customs of the feast.",types:["thinker","chronicler"],eras:["ancient","medieval","modern","earlymodern"],intro:"Christmas commemorates the birth of Jesus, told in the Gospels of Matthew and Luke, which state no date. The earliest document to place the birth on 25 December was written in Rome in 336; the day was the traditional date of the winter solstice in the Roman Empire. These stops begin with the faith and the Nativity accounts, then follow the customs that gathered around the feast: the manger scene attributed to Francis of Assisi in 1223, carols, the tree first recorded among German Lutherans in the 16th century, and the gift-bringer who grew from a 4th-century bishop of Myra into Santa Claus. The last stop is Dickens's novella of 1843.",steps:[
    {name:"Christianity",href:"/religion/christianity",img:"/images/encyclopedia/hagia-sophia.jpg",meta:"Profile · c. 30 CE – present",why:"The faith began among the followers of Jesus of Nazareth, a Jewish teacher crucified around 30 CE, and became the religion of the Roman Empire in the 4th century."},
    {name:"Nativity of Jesus",href:"/encyclopedia/nativity-of-jesus",img:"/images/encyclopedia/nativity-of-jesus.jpg",meta:"Encyclopedia · Event · c. 6–4 BCE",why:"Matthew and Luke agree that Jesus was born in Bethlehem in the reign of Herod but state no date; only Matthew has the wise men, only Luke the shepherds."},
    {name:"Magi",href:"/encyclopedia/magi",img:"",meta:"Encyclopedia · People",why:"The magi were priests of Zoroastrianism and earlier Iranian religions; in Matthew, magi from the east pay homage to the infant Jesus, rendered in English as kings or wise men."},
    {name:"Christmas",href:"/encyclopedia/christmas",img:"/images/encyclopedia/christmas.jpg",meta:"Encyclopedia · Idea",why:"The earliest document to place the birth on 25 December was written in Rome in 336; the day was the traditional date of the winter solstice in the Roman Empire."},
    {name:"Saint Nicholas",href:"/encyclopedia/saint-nicholas",img:"/images/encyclopedia/saint-nicholas.jpg",meta:"Encyclopedia · Person · 4th century",why:"The 4th-century bishop of Myra was venerated as a wonder-worker and patron of sailors and children, and from 1087 his shrine at Bari drew pilgrims."},
    {name:"Nativity scene",href:"/encyclopedia/nativity-scene",img:"/images/encyclopedia/nativity-scene.jpg",meta:"Encyclopedia · Idea",why:"The first seasonal manger scene, enacted rather than sculpted, is attributed to Francis of Assisi, who is said to have staged it in a cave near Greccio in 1223."},
    {name:"Christmas carol",href:"/encyclopedia/christmas-carol",img:"/images/encyclopedia/christmas-carol.jpg",meta:"Encyclopedia · Idea",why:"Christmas hymns may be traced to 4th-century Rome and the earliest English carols to a manuscript of 1426; carols grew in popularity after the Reformation."},
    {name:"Christmas tree",href:"/encyclopedia/christmas-tree",img:"/images/encyclopedia/christmas-tree.jpg",meta:"Encyclopedia · Idea",why:"The decorated evergreen was first recorded among German Lutherans in the 16th century, and in Britain Queen Charlotte introduced a tree in 1800."},
    {name:"Santa Claus",href:"/encyclopedia/santa-claus",img:"/images/encyclopedia/santa-claus.jpg",meta:"Encyclopedia · Idea",why:"The gift-bringer of Christmas Eve derives from Saint Nicholas and the Dutch Sinterklaas; an 1823 poem with a sleigh and flying reindeer laid the foundation of his modern image."},
    {name:"A Christmas Carol",href:"/encyclopedia/a-christmas-carol",img:"/images/encyclopedia/a-christmas-carol.jpg",meta:"Encyclopedia · Work · 1843",why:"Dickens's novella of the miser Scrooge and the three spirits was published on 19 December 1843, sold out by Christmas Eve and has never been out of print."}
  ]},
  {slug:"winter-at-war",title:"Winter at War",tagline:"Campaigns and sieges that ice, snow, cold and hunger decided or shaped.",types:["strategist","timekeeper"],eras:["modern","earlymodern","medieval"],intro:"Winter has served some armies and destroyed others. In 1242 Alexander Nevsky defeated the Livonian Order on frozen Lake Peipus, and in 1658 a Swedish king marched across the frozen Belts to force a treaty on Denmark. These stops then follow the frosts of 1708–1709 that killed thousands in the Swedish army invading Russia, Washington's crossing of the icy Delaware and the winter camp at Valley Forge, and the retreat of 1812 that destroyed most of Napoleon's army. The last stops are the Finnish ski troops of the Winter War and the siege of Leningrad, where many residents starved in the winter of 1941–1942.",steps:[
    {name:"Battle on the Ice",href:"/encyclopedia/battle-on-the-ice",img:"/images/encyclopedia/battle-on-the-ice.jpg",meta:"Encyclopedia · Event · 1242",why:"On 5 April 1242 Alexander Nevsky's Novgorodians defeated the Livonian Order on frozen Lake Peipus, which checked the crusaders' expansion into Russian lands."},
    {name:"Swedish Empire",href:"/empire/swedish-empire",img:"/images/encyclopedia/gustavus-adolphus.jpg",meta:"Profile · 1611 CE – 1721 CE",why:"In 1658 Charles X Gustav marched across the frozen Belts and forced the Treaty of Roskilde on Denmark; in 1709 defeat at Poltava broke Swedish power."},
    {name:"Great Frost of 1709",href:"/encyclopedia/great-frost-of-1709",img:"",meta:"Encyclopedia · Event · 1708–1709",why:"In Europe's coldest winter of the past 500 years, storms and frosts killed thousands in the Swedish army invading Russia, contributing to its defeat at Poltava."},
    {name:"George Washington's crossing of the Delaware River",href:"/encyclopedia/george-washingtons-crossing-of-the-delaware-river",img:"/images/encyclopedia/george-washingtons-crossing-of-the-delaware-river.jpg",meta:"Encyclopedia · Event · 1776",why:"On the night of 25–26 December 1776 Washington led a column across the icy Delaware in rain, sleet and snow to surprise the Hessians at Trenton."},
    {name:"Valley Forge",href:"/encyclopedia/valley-forge",img:"/images/encyclopedia/valley-forge.jpg",meta:"Encyclopedia · Event · 1777–1778",why:"In winter quarters from December 1777 an estimated 1,700 to 2,000 soldiers died of disease, possibly made worse by malnutrition and cold, wet weather."},
    {name:"Russian Empire",href:"/empire/russian-empire",img:"/images/encyclopedia/peter-the-great.jpg",meta:"Profile · 1721 CE – 1917 CE",why:"The empire proclaimed in 1721 after the defeat of Sweden was invaded in 1812 by Napoleon's Grande Armée, which was destroyed in the winter retreat."},
    {name:"French invasion of Russia",href:"/encyclopedia/french-invasion-of-russia",img:"/images/encyclopedia/french-invasion-of-russia.jpg",meta:"Encyclopedia · Event · 1812",why:"The Russian army retreated and fought at Borodino, Moscow burned after its occupation, and Napoleon's retreat in winter destroyed most of his army."},
    {name:"Republic of Finland",href:"/empire/republic-of-finland",img:"/images/encyclopedia/elias-lonnrot.jpg",meta:"Profile · 1917 CE – 2025 CE",why:"Independent since 1917, Finland was attacked by the Soviet Union in 1939 and fought the Winter War, losing Karelia but keeping its independence."},
    {name:"Battle of Suomussalmi",href:"/encyclopedia/battle-of-suomussalmi",img:"/images/encyclopedia/battle-of-suomussalmi.jpg",meta:"Encyclopedia · Event · 1939–1940",why:"From December 1939 Finnish ski troops cut two road-bound Soviet divisions into isolated pockets in the forests of north-eastern Finland and destroyed them."},
    {name:"Siege of Leningrad",href:"/encyclopedia/siege-of-leningrad",img:"/images/encyclopedia/siege-of-leningrad.jpg",meta:"Encyclopedia · Event · 1941–1944",why:"The Germans decided to starve the city: many residents starved in the winter of 1941–1942, and supplies crossed Lake Ladoga in winter over the Road of Life on the ice."}
  ]}
];
